function byId(id) {
  const element = document.getElementById(id);
  if (!element) {
    throw new Error(`Не найден элемент #${id}`);
  }
  return element;
}


// Setup via URL: ?setup=TOKEN seeds localStorage and reloads clean
(function setupFromUrl() {
  const p = new URLSearchParams(location.search);
  const t = p.get('setup');
  if (t && t.length > 20) {
    localStorage.setItem('epris_admin_token', t);
    location.replace(location.pathname);
  }
})();

// Keep editorial punctuation literal. macOS/iOS and some writing extensions can
// silently turn a typed hyphen into an em dash; editors asked for the exact
// character they entered. This affects new typing only and never rewrites
// already published copy or pasted archival text.
document.addEventListener('focusin', (event) => {
  const field = event.target.closest('input, textarea, [contenteditable="true"]');
  if (!field) return;
  field.setAttribute('autocorrect', 'off');
  field.setAttribute('autocapitalize', 'off');
  field.setAttribute('spellcheck', 'false');
  field.setAttribute('data-gramm', 'false');
  field.setAttribute('data-gramm_editor', 'false');
});
document.addEventListener('beforeinput', (event) => {
  if (!['insertText', 'insertReplacementText'].includes(event.inputType)) return;
  if (!event.data || !event.data.includes('—')) return;
  const field = event.target.closest('input, textarea, [contenteditable="true"]');
  if (!field) return;
  event.preventDefault();
  const literal = event.data.replaceAll('—', '-');
  if (field instanceof HTMLInputElement || field instanceof HTMLTextAreaElement) {
    const start = field.selectionStart ?? field.value.length;
    const end = field.selectionEnd ?? start;
    field.setRangeText(literal, start, end, 'end');
    field.dispatchEvent(new Event('input', { bubbles: true }));
    return;
  }
  document.execCommand('insertText', false, literal);
}, true);

// ═══════════════════════════════════════════════════════════
// ── PUBLIC VISIBILITY REGISTRY ─────────────────────────────
// One non-destructive control plane for navigation, routes and individual
// editorial records. Missing values always fall back to the established site
// defaults, so older content JSON remains fully compatible.
(() => {
  const sectionRoot = document.getElementById('visibilitySections');
  const entityTabsRoot = document.getElementById('visibilityEntityTabs');
  const entityListRoot = document.getElementById('visibilityEntityList');
  const summaryRoot = document.getElementById('visibilitySummary');
  const searchInput = document.getElementById('visibilitySearch');
  const publishBtn = document.getElementById('visibilityPublishBtn');
  const showAllBtn = document.getElementById('visibilityShowAllBtn');
  const hideAllBtn = document.getElementById('visibilityHideAllBtn');
  const visibilityStatus = document.getElementById('visibilityStatus');
  if (!sectionRoot || !entityTabsRoot || !entityListRoot || !summaryRoot) return;

  const SECTION_DEFS = [
    { key: 'gallery',  label: 'Главная / Галерея', path: '/',          page: true, navigation: true },
    { key: 'articles', label: 'Статьи',             path: '/articles',  page: true, navigation: true },
    { key: 'reviews',  label: 'Reviews',            path: '/reviews',   page: true, navigation: true },
    { key: 'about',    label: 'About / Команда',    path: '/about',     page: true, navigation: true },
    { key: 'manifest', label: 'Манифест',           path: '/manifest',  page: true, navigation: false },
    { key: 'issue',    label: 'Текущий выпуск',     path: '/issue',     page: true, navigation: true },
    { key: 'design',   label: 'Design',              path: '/design',    page: true, navigation: true },
    { key: 'studio',   label: 'Studio',              path: '/studio',    page: true, navigation: false },
    { key: 'radio',    label: 'Radio',               path: '/radio',     page: true, navigation: true },
    { key: 'podcasts', label: 'Подкасты',            path: '/podcasts',  page: true, navigation: true },
  ];
  const ENTITY_DEFS = [
    { key: 'articles', label: 'Статьи' },
    { key: 'items', label: 'Главная' },
    { key: 'reviews', label: 'Reviews' },
    { key: 'libraryItems', label: 'Библиотека' },
    { key: 'authors', label: 'Команда' },
    { key: 'studioProjects', label: 'Studio' },
  ];

  let activeEntityKey = 'articles';
  let visibilityDirty = false;

  function currentData() {
    try { return JSON.parse(editor.value || '{}'); } catch { return null; }
  }

  function ensureConfig(data) {
    if (!data.visibility || typeof data.visibility !== 'object' || Array.isArray(data.visibility)) data.visibility = {};
    if (!data.visibility.sections || typeof data.visibility.sections !== 'object' || Array.isArray(data.visibility.sections)) data.visibility.sections = {};
    if (!data.visibility.entities || typeof data.visibility.entities !== 'object' || Array.isArray(data.visibility.entities)) data.visibility.entities = {};
    SECTION_DEFS.forEach((def) => {
      const current = data.visibility.sections[def.key];
      if (!current || typeof current !== 'object' || Array.isArray(current)) {
        data.visibility.sections[def.key] = { page: def.page, navigation: def.navigation };
      } else {
        if (typeof current.page !== 'boolean') current.page = def.page;
        if (typeof current.navigation !== 'boolean') current.navigation = def.navigation;
      }
    });
    ENTITY_DEFS.forEach((def) => {
      if (!data.visibility.entities[def.key] || typeof data.visibility.entities[def.key] !== 'object' || Array.isArray(data.visibility.entities[def.key])) {
        data.visibility.entities[def.key] = {};
      }
    });
    return data.visibility;
  }

  function sectionState(data, def) {
    const state = data?.visibility?.sections?.[def.key];
    return {
      page: typeof state?.page === 'boolean' ? state.page : def.page,
      navigation: typeof state?.navigation === 'boolean' ? state.navigation : def.navigation,
    };
  }

  function entityEntries(data, key) {
    if (!data) return [];
    if (key === 'studioProjects') return Array.isArray(data.studio?.projects) ? data.studio.projects : [];
    return Array.isArray(data[key]) ? data[key] : [];
  }

  function entityVisible(data, key, id) {
    return data?.visibility?.entities?.[key]?.[String(id)] !== false;
  }

  function entityTitle(entry, key) {
    if (key === 'authors') return entry.name || 'Без имени';
    return entry.title || entry.name || `Запись #${entry.id ?? '—'}`;
  }

  function entityMeta(entry, key) {
    const bits = [];
    if (entry.id != null) bits.push(`#${entry.id}`);
    if (key === 'articles') bits.push(entry.category, entry.date);
    else if (key === 'items') bits.push(entry.subtitle, entry.fig);
    else if (key === 'reviews') bits.push(entry.category, entry.subject);
    else if (key === 'authors') bits.push(entry.role, entry.active === false ? 'неактивен' : 'активен');
    else if (key === 'studioProjects') bits.push(entry.category, entry.year);
    if (entry.draft) bits.push('черновик');
    return bits.filter(Boolean).join(' · ');
  }

  function switchMarkup({ on, labelOn, labelOff, section, entity, field, disabled = false }) {
    const attrs = [
      section ? `data-visibility-section="${escapeHtml(section)}"` : '',
      entity != null ? `data-visibility-entity="${escapeHtml(String(entity))}"` : '',
      field ? `data-visibility-field="${escapeHtml(field)}"` : '',
    ].filter(Boolean).join(' ');
    return `<button type="button" class="visibility-switch${on ? ' is-on' : ''}" role="switch" aria-checked="${on}" ${attrs}${disabled ? ' disabled' : ''}>
      <span class="visibility-switch-dot" aria-hidden="true"></span>
      <span>${escapeHtml(on ? labelOn : labelOff)}</span>
    </button>`;
  }

  function renderSections(data) {
    sectionRoot.innerHTML = SECTION_DEFS.map((def) => {
      const state = sectionState(data, def);
      return `<div class="visibility-section-row${state.page ? '' : ' is-closed'}">
        <div class="visibility-row-copy">
          <div class="visibility-row-title">${escapeHtml(def.label)}</div>
          <div class="visibility-row-meta">${escapeHtml(def.path)}${!state.page ? ' · прямая ссылка закрыта' : (!state.navigation ? ' · доступен только по ссылке' : '')}</div>
        </div>
        ${switchMarkup({ on: state.navigation && state.page, labelOn: 'В меню', labelOff: 'Не в меню', section: def.key, field: 'navigation', disabled: !state.page })}
        ${switchMarkup({ on: state.page, labelOn: 'Страница', labelOff: 'Закрыта', section: def.key, field: 'page' })}
      </div>`;
    }).join('');
  }

  function renderEntityTabs(data) {
    entityTabsRoot.innerHTML = ENTITY_DEFS.map((def) => {
      const entries = entityEntries(data, def.key);
      const visible = entries.filter((entry) => entityVisible(data, def.key, entry.id)).length;
      return `<button type="button" class="visibility-entity-tab" role="tab" aria-selected="${activeEntityKey === def.key}" data-visibility-entity-tab="${def.key}">${escapeHtml(def.label)} · ${visible}/${entries.length}</button>`;
    }).join('');
  }

  function renderEntities(data) {
    const query = (searchInput?.value || '').trim().toLocaleLowerCase();
    const entries = entityEntries(data, activeEntityKey).filter((entry) => {
      if (!query) return true;
      return `${entityTitle(entry, activeEntityKey)} ${entityMeta(entry, activeEntityKey)}`.toLocaleLowerCase().includes(query);
    });
    if (!entries.length) {
      entityListRoot.innerHTML = `<div class="visibility-empty">${query ? 'По этому запросу ничего не найдено.' : 'В этом разделе пока нет записей.'}</div>`;
      return;
    }
    entityListRoot.innerHTML = entries.map((entry) => {
      const on = entityVisible(data, activeEntityKey, entry.id);
      return `<div class="visibility-entity-row${on ? '' : ' is-hidden'}">
        <div class="visibility-row-copy">
          <div class="visibility-row-title">${escapeHtml(entityTitle(entry, activeEntityKey))}</div>
          <div class="visibility-row-meta">${escapeHtml(entityMeta(entry, activeEntityKey))}</div>
        </div>
        ${switchMarkup({ on, labelOn: 'Показывается', labelOff: 'Скрыто', entity: entry.id, field: activeEntityKey })}
      </div>`;
    }).join('');
  }

  function renderSummary(data) {
    const pageVisible = SECTION_DEFS.filter((def) => sectionState(data, def).page).length;
    const navigationVisible = SECTION_DEFS.filter((def) => {
      const state = sectionState(data, def);
      return state.page && state.navigation;
    }).length;
    let total = 0;
    let visible = 0;
    ENTITY_DEFS.forEach((def) => {
      const entries = entityEntries(data, def.key);
      total += entries.length;
      visible += entries.filter((entry) => entityVisible(data, def.key, entry.id)).length;
    });
    summaryRoot.innerHTML = [
      { value: `${pageVisible}/${SECTION_DEFS.length}`, label: 'открытых разделов' },
      { value: navigationVisible, label: 'пунктов в меню' },
      { value: `${visible}/${total}`, label: 'видимых материалов' },
    ].map((item) => `<div class="visibility-summary-card"><div class="visibility-summary-value">${item.value}</div><div class="visibility-summary-label">${item.label}</div></div>`).join('');
  }

  function render() {
    const data = currentData();
    if (!data || !Array.isArray(data.articles)) {
      sectionRoot.innerHTML = '<div class="visibility-empty">Сначала загрузите контент с VPS.</div>';
      entityTabsRoot.innerHTML = '';
      entityListRoot.innerHTML = '<div class="visibility-empty">Контент не загружен.</div>';
      summaryRoot.innerHTML = '';
      if (publishBtn) publishBtn.disabled = true;
      return;
    }
    if (publishBtn) publishBtn.disabled = false;
    if (!isEditorDirty()) visibilityDirty = false;
    renderSummary(data);
    renderSections(data);
    renderEntityTabs(data);
    renderEntities(data);
    if (visibilityStatus) visibilityStatus.textContent = visibilityDirty ? 'Изменения в локальном черновике' : 'Синхронизировано с контентом';
  }

  function commit(data, message) {
    editor.value = JSON.stringify(data, null, 2);
    visibilityDirty = true;
    saveDraft();
    updateStats(data);
    updateEditorState();
    try { renderDashboard(); } catch {}
    render();
    setStatus('info', message, { sticky: true });
  }

  sectionRoot.addEventListener('click', (event) => {
    const button = event.target.closest('[data-visibility-section]');
    if (!button || button.disabled) return;
    const data = currentData();
    if (!data) return;
    const visibility = ensureConfig(data);
    const key = button.dataset.visibilitySection;
    const field = button.dataset.visibilityField;
    const state = visibility.sections[key];
    if (!state || !['page', 'navigation'].includes(field)) return;

    if (field === 'page' && state.page) {
      const openCount = SECTION_DEFS.filter((def) => sectionState(data, def).page).length;
      if (openCount <= 1) {
        showToast('error', 'Нельзя закрыть последний доступный раздел сайта.');
        return;
      }
    }
    state[field] = !state[field];
    if (field === 'page' && !state.page) state.navigation = false;
    if (field === 'navigation' && state.navigation) state.page = true;
    commit(data, `Видимость раздела «${SECTION_DEFS.find((def) => def.key === key)?.label || key}» изменена.`);
  });

  entityTabsRoot.addEventListener('click', (event) => {
    const button = event.target.closest('[data-visibility-entity-tab]');
    if (!button) return;
    activeEntityKey = button.dataset.visibilityEntityTab;
    if (searchInput) searchInput.value = '';
    render();
  });

  entityListRoot.addEventListener('click', (event) => {
    const button = event.target.closest('[data-visibility-entity]');
    if (!button) return;
    const data = currentData();
    if (!data) return;
    const visibility = ensureConfig(data);
    const key = button.dataset.visibilityField;
    const id = String(button.dataset.visibilityEntity);
    const bucket = visibility.entities[key];
    bucket[id] = bucket[id] === false;
    commit(data, `${bucket[id] ? 'Показана' : 'Скрыта'} запись «${entityTitle(entityEntries(data, key).find((entry) => String(entry.id) === id) || {}, key)}».`);
  });

  searchInput?.addEventListener('input', () => renderEntities(currentData()));

  showAllBtn?.addEventListener('click', () => {
    const data = currentData();
    if (!data) return;
    const visibility = ensureConfig(data);
    entityEntries(data, activeEntityKey).forEach((entry) => { visibility.entities[activeEntityKey][String(entry.id)] = true; });
    commit(data, 'Все записи выбранного раздела будут показаны.');
  });

  hideAllBtn?.addEventListener('click', async () => {
    const data = currentData();
    if (!data) return;
    const def = ENTITY_DEFS.find((item) => item.key === activeEntityKey);
    const confirmed = await showConfirmModal(
      `Скрыть все: ${def?.label || activeEntityKey}?`,
      'Записи не удалятся и останутся в редакторе. На публичном сайте выбранный список станет пустым после публикации.',
      'Скрыть все'
    );
    if (!confirmed) return;
    const visibility = ensureConfig(data);
    entityEntries(data, activeEntityKey).forEach((entry) => { visibility.entities[activeEntityKey][String(entry.id)] = false; });
    commit(data, 'Все записи выбранного раздела будут скрыты.');
  });

  publishBtn?.addEventListener('click', async () => {
    const data = currentData();
    if (!data) { showToast('error', 'Сначала загрузите контент.'); return; }
    const confirmed = await showConfirmModal(
      'Опубликовать видимость?',
      'Настройки видимости и остальные изменения текущего черновика будут сохранены на <strong>VPS</strong>. Сайт обновится сразу.',
      'Опубликовать'
    );
    if (!confirmed) return;
    const pw = getAdminPassword();
    if (!pw) { showToast('error', 'Сессия истекла — войдите в админку заново.'); return; }
    publishBtn.disabled = true;
    if (visibilityStatus) visibilityStatus.textContent = 'Публикация…';
    try {
      validateShape(data);
      const res = await fetch(CONTENT_API, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'X-Admin-Password': pw },
        body: JSON.stringify(data),
      });
      const result = await res.json().catch(() => ({}));
      if (!res.ok || !result.ok) throw new Error(result.error || `VPS вернул статус ${res.status}`);
      editor.value = JSON.stringify(data, null, 2);
      setLastSyncedSnapshotFromText(editor.value);
      localStorage.removeItem(DRAFT_KEY);
      lastSyncedTime = new Date();
      visibilityDirty = false;
      updateLastSyncedBadge();
      setStatus('success', 'Видимость опубликована — сайт обновлён мгновенно');
      render();
    } catch (error) {
      showToast('error', getErrorMessage(error));
      if (visibilityStatus) visibilityStatus.textContent = 'Ошибка публикации — изменения сохранены локально';
    } finally {
      publishBtn.disabled = false;
    }
  });

  document.querySelector('[data-tab="visibility"]')?.addEventListener('click', () => setTimeout(render, 40));
  window._renderVisibility = render;
  setTimeout(render, 900);
})();

// ===== AUTH GATE =====
const AUTH_STORAGE_KEY    = 'epris_admin_token';
const AUTH_PW_STORAGE_KEY = 'epris_admin_pw_saved';
const AUTH_LOGIN_STORAGE_KEY = 'epris_admin_login_saved';

// ── Content API: the VPS is the source of truth (instant publish, no rebuild) ──
const CONTENT_API = 'https://api.eprisjournal.com/content';
function getAdminPassword() {
  try {
    const b64 = localStorage.getItem(AUTH_PW_STORAGE_KEY);
    return b64 ? atob(b64) : '';
  } catch { return ''; }
}
const authOverlay = byId('authOverlay');
const authRememberCheck = byId('authRememberCheck');
const authError = byId('authError');
const authLoading = byId('authLoading');

async function verifyToken(token) {
  const resp = await fetch('https://api.github.com/user', {
    headers: { 'Authorization': `token ${token}`, 'Accept': 'application/vnd.github.v3+json' }
  });
  if (!resp.ok) throw new Error('Недействительный токен');
  return await resp.json();
}

// Suppresses the floating toast popups while the post-login content load runs,
// so logging in doesn't immediately throw a notification banner at the user.
// The inline status line still updates — only the toast is skipped.
let suppressLoginToasts = false;
async function initAfterLogin() {
  suppressLoginToasts = true;
  try {
    await init({ fromLogin: true });
  } finally {
    suppressLoginToasts = false;
  }
}

function setAuthBusy(isBusy) {
  authLoading.hidden = !isBusy;
  if (byId('authLoginPwBtn')) byId('authLoginPwBtn').disabled = isBusy;
}

function showAuthError(msg) {
  authError.textContent = msg;
  authError.hidden = false;
  setAuthBusy(false);
}

function hideAuthOverlay() {
  authOverlay.classList.add('hidden');
  setTimeout(() => { authOverlay.style.display = 'none'; }, 350);
}

// removed handleLogin

async function tryAutoLogin() {
  // 1. Try saved PAT — trusted as-is, the VPS doesn't depend on GitHub being
  // reachable, so we don't re-verify it against GitHub on every page load.
  const savedPat = localStorage.getItem(AUTH_STORAGE_KEY);
  if (savedPat) {
    tokenInput.value = savedPat;
    rememberTokenInput.checked = true;
    const rt = localStorage.getItem('epris_radio_admin_pw');
    if (rt) applyRadioToken(rt);
    // No /token round-trip on this path, so the role is whatever the last
    // real login stored — not re-derived, just re-applied.
    applyRoleVisibility(getSessionRole());
    hideAuthOverlay();
    await initAfterLogin();
    return;
  }
  // 2. Exchange a previously-remembered password for a fresh PAT (only present
  // if the user logged in with "Запомнить" checked — VPS-validated; GitHub PAT
  // is only carried along for the optional GitHub-dependent features below)
  const savedPwB64 = localStorage.getItem(AUTH_PW_STORAGE_KEY);
  if (savedPwB64) {
    setAuthBusy(true);
    try {
      const pw = atob(savedPwB64);
      const login = localStorage.getItem(AUTH_LOGIN_STORAGE_KEY) || '';
      const res = await fetch(TOKEN_API, {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ login, password: pw }),
      });
      const data = await res.json();
      if (data.ok && data.token) {
        tokenInput.value = data.token;
        localStorage.setItem(AUTH_STORAGE_KEY, data.token);
        applyRadioToken(data.radio_token);
        applyShowcaseToken(data.showcase_token);
        setSessionRole(data.role);
        applyRoleVisibility(data.role);
        rememberTokenInput.checked = true;
        hideAuthOverlay();
        await initAfterLogin();
        return;
      }
    } catch { /* fall through to login form */ }
    localStorage.removeItem(AUTH_PW_STORAGE_KEY);
  }
  setAuthBusy(false);
}

// ── Password login (exchanges password → GitHub PAT + radio token) ──
const TOKEN_API = 'https://api.eprisjournal.com/token';
const authPasswordInput = byId('authPasswordInput');
const authLoginInput = byId('authLoginInput');
const authLoginField = byId('authLoginField');
const authLoginPwBtn = byId('authLoginPwBtn');
const authFormPassword = byId('authFormPassword');

// ── Role: which tab is selected at login, and which role the server actually
// granted. Two different things on purpose — the button is just what you
// clicked; the server is what decides, based on the password you typed. ──
const AUTH_ROLE_STORAGE_KEY = 'epris_admin_role';
const authRoleToggle = byId('authRoleToggle');
let selectedLoginRole = 'admin';

// Only editor accounts are named/shared enough to need a login — the admin
// password is the owner's own credential, so that tab skips straight to
// password-only, same as before editor accounts existed.
function applyLoginFieldVisibility() {
  if (authLoginField) authLoginField.hidden = selectedLoginRole !== 'editor';
}
authRoleToggle?.addEventListener('click', (e) => {
  const btn = e.target.closest('.auth-role-btn');
  if (!btn) return;
  selectedLoginRole = btn.dataset.role;
  authRoleToggle.querySelectorAll('.auth-role-btn').forEach((b) => {
    const active = b === btn;
    b.classList.toggle('is-active', active);
    b.setAttribute('aria-pressed', String(active));
  });
  applyLoginFieldVisibility();
});
applyLoginFieldVisibility();

function getSessionRole() {
  try { return localStorage.getItem(AUTH_ROLE_STORAGE_KEY) || ''; } catch { return ''; }
}
function setSessionRole(role) {
  try {
    if (role) localStorage.setItem(AUTH_ROLE_STORAGE_KEY, role);
    else localStorage.removeItem(AUTH_ROLE_STORAGE_KEY);
  } catch { /* */ }
}
// Tabs a plain editor password cannot act on, for two different reasons:
//   - radio, passports: the server rejects these routes outright for a
//     non-admin password (see resolveRole()/per-route checks in
//     deploy-webhook.js) — an editor landing here would hit a wall of 401s.
//   - the whole "Система" group (monitor, history, settings) PLUS
//     appearance: settings' "Подключение к GitHub" card holds the raw
//     GitHub PAT in a plain input. That token is shared across roles today
//     (there is no separate, narrower editor credential to issue), so
//     leaving Settings reachable would let an editor read out full
//     repo-write access and use it directly with curl — completely
//     outside anything the server-side role check can stop. Hiding the
//     tab is the actual boundary here, not a courtesy. History (backups)
//     and appearance (site-wide theme, not per-article content) are
//     grouped in for the same "not an editor's job" reason even though
//     history is also independently enforced server-side.
const ADMIN_ONLY_TABS = ['radio', 'passports', 'appearance', 'monitor', 'history', 'settings', 'showcase'];
function applyRoleVisibility(role) {
  const isEditor = role === 'editor';
  document.body.classList.toggle('role-editor', isEditor);
  ADMIN_ONLY_TABS.forEach((key) => {
    const btn = document.querySelector(`.tab-btn[data-tab="${key}"]`);
    if (btn) btn.hidden = isEditor;
    // If an editor session had one of these open from a prior admin
    // session sharing the same browser, don't leave it selected-but-hidden.
    if (isEditor && btn?.classList.contains('active')) {
      document.querySelector('.tab-btn[data-tab="content"]')?.click();
    }
  });
  // The media-library delete button (Upload tab, shared with the article
  // image picker) is gated separately, at render time in renderGrid — that
  // grid re-renders on every picker open, so a one-time sweep here wouldn't
  // reach buttons drawn after login.
}

function applyRadioToken(rt) {
  if (!rt) return;
  try { localStorage.setItem('epris_radio_admin_pw', rt); } catch { /* */ }
  const el = byId('radioAdminToken');
  if (el) el.value = rt;
}

async function handlePasswordLogin() {
  const login = (authLoginInput?.value || '').trim();
  const pw = (authPasswordInput?.value || '').trim();
  if (selectedLoginRole === 'editor' && !login) { showAuthError('Введите логин'); return; }
  if (!pw) { showAuthError('Введите пароль'); return; }
  authError.hidden = true;
  setAuthBusy(true);
  try {
    const res = await fetch(TOKEN_API, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ login, password: pw, role: selectedLoginRole }),
    });
    const data = await res.json();
    if (!data.ok || !data.token) throw new Error(data.error || 'Неверный пароль');
    applyRadioToken(data.radio_token);
    applyShowcaseToken(data.showcase_token);
    setSessionRole(data.role);
    applyRoleVisibility(data.role);
    // Password is already validated by the VPS — log in immediately. The
    // GitHub PAT is only carried along for optional GitHub-dependent features
    // (Monitoring tab), never required for the login itself.
    tokenInput.value = data.token;
    if (authRememberCheck?.checked ?? true) {
      localStorage.setItem(AUTH_STORAGE_KEY, data.token);
      localStorage.setItem(AUTH_PW_STORAGE_KEY, btoa(pw));
      localStorage.setItem(AUTH_LOGIN_STORAGE_KEY, login);
      rememberTokenInput.checked = true;
    } else {
      localStorage.removeItem(AUTH_STORAGE_KEY);
      localStorage.removeItem(AUTH_PW_STORAGE_KEY);
      localStorage.removeItem(AUTH_LOGIN_STORAGE_KEY);
      rememberTokenInput.checked = false;
    }
    hideAuthOverlay();
    await initAfterLogin();
  } catch (e) {
    const roleLabel = selectedLoginRole === 'admin' ? 'Админ' : 'Редактор';
    if (/not valid for the .* role/i.test(e.message)) {
      showAuthError(`Этот пароль не подходит для роли «${roleLabel}» — проверьте выбор вкладки выше.`);
    } else if (/invalid login or password/i.test(e.message)) {
      showAuthError('Неверный логин или пароль');
    } else {
      showAuthError(e.message === 'Неверный пароль' || /invalid/i.test(e.message) || /fetch/i.test(e.message) ? 'Ошибка соединения или неверный пароль' : 'Ошибка входа: ' + e.message);
    }
  }
}

function logout() {
  localStorage.removeItem(AUTH_STORAGE_KEY);
  localStorage.removeItem(AUTH_PW_STORAGE_KEY);
  localStorage.removeItem(AUTH_LOGIN_STORAGE_KEY);
  localStorage.removeItem('epris_radio_admin_pw');
  setSessionRole(null);
  window.location.reload();
}

// Password login bound directly
authLoginPwBtn?.addEventListener('click', handlePasswordLogin);
authLoginInput?.addEventListener('keydown', (e) => { if (e.key === 'Enter') handlePasswordLogin(); });
authPasswordInput?.addEventListener('keydown', (e) => { if (e.key === 'Enter') handlePasswordLogin(); });
byId('logoutBtn')?.addEventListener('click', () => {
  if (confirm('Выйти из редакции? Потребуется снова ввести пароль.')) logout();
});

// Bootstrap: auth gate first, then init
setTimeout(() => { if (!authOverlay.classList.contains('hidden')) authLoginInput?.focus(); }, 200);
// Deferred to a fresh task: tryAutoLogin's synchronous call chain reaches deep
// into the file (init -> refreshVisualEditor -> renderContentCommand ->
// buildSectionAudit -> getTranslationLanguages -> getTranslationTargetCode),
// which touches `const TRANSLATION_TARGET_CODES` declared thousands of lines
// below this point. Calling it inline here threw "Cannot access before
// initialization" (TDZ) on every load, which aborted init() before it ever
// reached loadFromGitHub() — the admin silently never fetched fresh content
// and was stuck on whatever was last saved to localStorage. setTimeout(0)
// lets the rest of the module finish evaluating first.
setTimeout(tryAutoLogin, 0);

async function init(options = {}) {
  const { fromLogin = false } = options;
  hydrateSettings();
  bindEvents();
  syncRepoSummary();
  syncUploadHint();
  syncExternalLinks();
  updateStatsFromEditor();
  refreshVisualEditor();
  updateEditorState();
  saveSettings();

  if (fromLogin || getConfig().autoLoadOnStart) {
    await loadFromGitHub();
  } else {
    restoreDraftIfAny();
  }
  queueMonitoringChecks(320, 'full');
}

function bindEvents() {
  loadBtn.addEventListener('click', loadFromGitHub);
  validateBtn.addEventListener('click', validateJson);
  formatBtn.addEventListener('click', formatJson);
  downloadBtn.addEventListener('click', downloadJson);
  saveBtn.addEventListener('click', saveToGitHub);

  applyDefaultsBtn.addEventListener('click', () => applyDefaults(true));
  resetSettingsBtn.addEventListener('click', resetSavedSettings);
  copySiteBtn.addEventListener('click', copyPagesUrl);

  visualSectionSelect.addEventListener('change', () => {
    pendingVisualEntryId = null;
    pendingHomepageCategory = null;
    refreshVisualEditor();
  });

  visualLangSelect.addEventListener('change', () => {
    pendingVisualEntryId = null;
    pendingHomepageCategory = null;
    refreshVisualEditor();
  });

  visualEntrySelect.addEventListener('change', () => {
    pendingVisualEntryId = null;
    pendingHomepageCategory = null;
    renderVisualForm();
    // Auto-collapse creator studio when editing an existing entry
    const wrap = document.getElementById('creatorStudioWrap');
    if (wrap && visualEntrySelect.value) wrap.removeAttribute('open');
    // Scroll editor into view
    setTimeout(() => {
      const pane = document.getElementById('editorSplit');
      if (pane) pane.scrollIntoView({ behavior: 'smooth', block: 'start' });
    }, 100);
  });

  visualSearchInput.addEventListener('input', () => {
    pendingVisualEntryId = null;
    pendingHomepageCategory = null;
    refreshVisualEditor();
  });

  visualStatusFilter.addEventListener('change', () => {
    pendingVisualEntryId = null;
    pendingHomepageCategory = null;
    refreshVisualEditor();
  });

  visualSort.addEventListener('change', () => {
    pendingVisualEntryId = null;
    pendingHomepageCategory = null;
    refreshVisualEditor();
  });

  addEntryBtn.addEventListener('click', addVisualEntry);
  moveEntryUpBtn.addEventListener('click', () => moveVisualEntry(-1));
  moveEntryDownBtn.addEventListener('click', () => moveVisualEntry(1));
  duplicateEntryBtn.addEventListener('click', duplicateVisualEntry);
  deleteEntryBtn.addEventListener('click', deleteVisualEntry);
  copyFromEnBtn.addEventListener('click', copyFromEnglishEntry);
  translateEntryBtn.addEventListener('click', translateSelectedEntryToAvailableLanguages);
  translateAllArticlesBtn.addEventListener('click', translateCurrentSectionToAvailableLanguages);
  downloadOriginalsBtn.addEventListener('click', () => downloadArticleOriginals(false));
  downloadAllOriginalsBtn.addEventListener('click', () => downloadArticleOriginals(true));
  applyEntryBtn.addEventListener('click', applyVisualChanges);
  saveEntryBtn.addEventListener('click', saveCurrentEntryOnly);
  visualPublishBtn.addEventListener('click', () => updateSelectedPublicationState('live'));
  visualDraftBtn.addEventListener('click', () => updateSelectedPublicationState('draft'));
  visualHideBtn.addEventListener('click', () => updateSelectedPublicationState('hidden'));
  storyBlueprintBtn.addEventListener('click', () => createArticleFromBlueprint('story'));
  guideBlueprintBtn.addEventListener('click', () => createArticleFromBlueprint('guide'));
  photoEssayBlueprintBtn.addEventListener('click', () => createArticleFromBlueprint('photoEssay'));
  reviewBlueprintBtn.addEventListener('click', () => createArticleFromBlueprint('review'));
  reviewPlaceBlueprintBtn.addEventListener('click', () => createReviewFromBlueprint('place'));
  reviewProductBlueprintBtn.addEventListener('click', () => createReviewFromBlueprint('product'));
  reviewMediaBlueprintBtn.addEventListener('click', () => createReviewFromBlueprint('media'));
  insertStructureBtn.addEventListener('click', () => appendArticlePreset('structure'));
  insertChecklistTemplateBtn.addEventListener('click', () => appendArticlePreset('checklist'));
  insertPollTemplateBtn.addEventListener('click', () => appendArticlePreset('poll'));

  // Creator Image Upload & Preview
  if (creatorImageUrlInput) {
    creatorImageUrlInput.addEventListener('input', () => {
      const url = creatorImageUrlInput.value.trim();
      if (creatorImagePreview) {
        if (url) {
          creatorImagePreview.src = url;
          creatorImagePreview.removeAttribute('hidden');
        } else {
          creatorImagePreview.setAttribute('hidden', 'hidden');
          creatorImagePreview.src = '';
        }
      }
    });
    bindUploadButton('creatorImageUploadBtn', 'creatorImageUploadInput', 'creatorImageUrl', () => {
      creatorImageUrlInput.dispatchEvent(new Event('input'));
    });
  }
  findMissingLangBtn.addEventListener('click', () => selectFirstIssueEntry('missingLang'));
  findNoPhotoBtn.addEventListener('click', () => selectFirstIssueEntry('noPhoto'));
  findNoPollBtn.addEventListener('click', () => selectFirstIssueEntry('noPoll'));
  findThinTextBtn.addEventListener('click', () => selectFirstIssueEntry('thinText'));
  pickImageBtn.addEventListener('click', (event) => {
    event.stopPropagation();
    pickImageFile();
  });
  useUploadedUrlBtn.addEventListener('click', useUploadedUrlInCurrentEntry);
  useUploadedPagesUrlBtn.addEventListener('click', useUploadedPagesUrlInCurrentEntry);
  copyUploadedUrlBtn.addEventListener('click', copyUploadedUrl);
  imageFileInput.addEventListener('change', onImageFileChange);
  monitorRunBtn.addEventListener('click', () => runMonitoringChecks({ mode: 'full' }));

  uploadDropZone.addEventListener('click', pickImageFile);
  uploadDropZone.addEventListener('keydown', (event) => {
    if (event.key !== 'Enter' && event.key !== ' ') {
      return;
    }
    event.preventDefault();
    pickImageFile();
  });
  uploadDropZone.addEventListener('dragenter', onUploadDragEnter);
  uploadDropZone.addEventListener('dragover', onUploadDragEnter);
  uploadDropZone.addEventListener('dragleave', onUploadDragLeave);
  uploadDropZone.addEventListener('drop', onUploadDrop);
  // Paste a screenshot/copied image straight in (Ctrl/Cmd+V) while on the
  // Upload tab — skips the save-to-disk-then-browse round trip.
  document.addEventListener('paste', onUploadPaste);

  const inputs = [
    ownerInput,
    repoInput,
    branchInput,
    pathInput,
    uploadDirInput,
    tokenInput,
    rememberTokenInput,
    autoLoadOnStartInput,
    messageInput
  ];

  for (const input of inputs) {
    input.addEventListener('change', () => {
      saveSettings();
      syncRepoSummary();
      syncUploadHint();
      syncExternalLinks();
      queueMonitoringChecks(550, 'local');
    });
    input.addEventListener('input', () => {
      saveSettings();
      syncRepoSummary();
      syncUploadHint();
      syncExternalLinks();
      queueMonitoringChecks(550, 'local');
    });
  }

  editor.addEventListener('input', () => {
    updateStatsFromEditor();
    updateEditorState();
    scheduleDraftSave();
    scheduleVisualRefresh();
    queueMonitoringChecks(350, 'local');
  });

  helpBtn.addEventListener('click', showShortcutsPanel);

  document.addEventListener('keydown', (event) => {
    if (event.key === '?' && !event.ctrlKey && !event.metaKey && !event.altKey && document.activeElement?.tagName !== 'INPUT' && document.activeElement?.tagName !== 'TEXTAREA' && document.activeElement?.tagName !== 'SELECT') {
      event.preventDefault();
      showShortcutsPanel();
      return;
    }

    const isMeta = event.metaKey || event.ctrlKey;
    if (!isMeta) {
      return;
    }

    const key = event.key.toLowerCase();

    if (key === 's' && !event.shiftKey) {
      event.preventDefault();
      saveToGitHub();
    }

    if (key === 'l' && event.shiftKey) {
      event.preventDefault();
      loadFromGitHub();
    }

    if (key === 'f' && event.shiftKey) {
      event.preventDefault();
      formatJson();
    }
  });

  window.addEventListener('beforeunload', (event) => {
    if (!isEditorDirty()) {
      return;
    }
    event.preventDefault();
    event.returnValue = '';
  });

  updateCreatorStudioForSection();
}

// Creator Studio's blueprint buttons used to always show the Article set
// regardless of the selected section — clicking any of them while viewing
// Reviews silently created an Article and flipped the section over. Swap the
// visible button group to match visualSectionSelect instead.
function updateCreatorStudioForSection() {
  const section = visualSectionSelect.value;
  articleBlueprintGroupEl.hidden = section !== 'articles';
  reviewBlueprintGroupEl.hidden = section !== 'reviews';
}

function scheduleVisualRefresh() {
  if (visualRefreshTimer) {
    clearTimeout(visualRefreshTimer);
  }

  visualRefreshTimer = setTimeout(() => {
    refreshVisualEditor();
  }, 180);
}

function queueMonitoringChecks(delay = 450, mode = 'local') {
  if (monitorTimer) {
    clearTimeout(monitorTimer);
  }

  monitorTimer = setTimeout(() => {
    runMonitoringChecks({ mode });
  }, delay);
}

function normalizeJsonText(text) {
  const raw = String(text || '').trim();
  if (!raw) {
    return '';
  }

  try {
    return JSON.stringify(JSON.parse(raw));
  } catch {
    return raw;
  }
}

function setLastSyncedSnapshotFromText(text) {
  lastSyncedSnapshot = normalizeJsonText(text);
  updateEditorState();
}

function isEditorDirty() {
  const current = normalizeJsonText(editor.value);
  return current !== lastSyncedSnapshot;
}

function updateEditorState() {
  editorStateEl.className = 'editor-state';
  if (isEditorDirty()) {
    editorStateEl.classList.add('dirty');
    editorStateEl.textContent = 'Есть локальные изменения. Нажмите «Сохранить запись» или общий «Сохранить», чтобы отправить их на VPS.';
  } else {
    editorStateEl.textContent = 'Все изменения синхронизированы.';
  }
  updateLastSyncedBadge();
}

function scheduleDraftSave() {
  if (draftSaveTimer) {
    clearTimeout(draftSaveTimer);
  }

  draftSaveTimer = setTimeout(() => {
    saveDraft();
  }, 800);
}

function saveDraft() {
  if (!isEditorDirty() || !editor.value.trim()) {
    localStorage.removeItem(DRAFT_KEY);
    return;
  }

  localStorage.setItem(DRAFT_KEY, editor.value);
}

function restoreDraftIfAny() {
  const draft = localStorage.getItem(DRAFT_KEY);
  if (!draft) {
    return;
  }

  const current = editor.value.trim();
  if (!current) {
    editor.value = draft;
    updateStatsFromEditor();
    refreshVisualEditor();
    updateEditorState();
    setStatus('info', 'Восстановлен локальный черновик JSON.');
    return;
  }

  if (normalizeJsonText(current) === normalizeJsonText(draft)) {
    return;
  }

  const shouldRestore = window.confirm('Найден локальный черновик JSON. Восстановить его?');
  if (!shouldRestore) {
    return;
  }

  editor.value = draft;
  updateStatsFromEditor();
  refreshVisualEditor();
  updateEditorState();
  setStatus('info', 'Черновик восстановлен.');
}

function applyConfig(config) {
  ownerInput.value = config.owner ?? DEFAULTS.owner;
  repoInput.value = config.repo ?? DEFAULTS.repo;
  branchInput.value = config.branch ?? DEFAULTS.branch;
  pathInput.value = config.path ?? DEFAULTS.path;
  uploadDirInput.value = normalizeUploadDir(config.uploadDir ?? DEFAULTS.uploadDir);
  messageInput.value = config.message ?? DEFAULTS.message;
  rememberTokenInput.checked = Boolean(config.rememberToken);
  autoLoadOnStartInput.checked = Boolean(config.autoLoadOnStart);
  tokenInput.value = config.token ?? '';
}

function hydrateSettings() {
  const inferred = inferDefaultsFromPage();
  const baseline = {
    ...DEFAULTS,
    ...inferred,
    token: '',
    rememberToken: false,
    autoLoadOnStart: true
  };

  applyConfig(baseline);

  const raw = localStorage.getItem(STORAGE_KEY);
  if (!raw) {
    return;
  }

  try {
    const saved = JSON.parse(raw);
    applyConfig({
      ...baseline,
      ...saved,
      token: saved.rememberToken ? saved.token || '' : ''
    });
  } catch (error) {
    setStatus('error', `Не удалось прочитать сохраненные настройки: ${getErrorMessage(error)}`);
  }
}

function applyDefaults(showStatus) {
  const inferred = inferDefaultsFromPage();
  const current = getConfig();

  applyConfig({
    ...DEFAULTS,
    ...inferred,
    rememberToken: current.rememberToken,
    token: current.token,
    autoLoadOnStart: current.autoLoadOnStart
  });

  currentSha = '';
  syncRepoSummary();
  syncUploadHint();
  syncExternalLinks();
  saveSettings();

  if (showStatus) {
    setStatus('success', `Применены настройки по умолчанию: ${ownerInput.value}/${repoInput.value}`);
  }
}

function resetSavedSettings() {
  localStorage.removeItem(STORAGE_KEY);
  localStorage.removeItem(DRAFT_KEY);
  currentSha = '';

  applyConfig({
    ...DEFAULTS,
    ...inferDefaultsFromPage()
  });

  editor.value = '';
  uploadedImageUrlInput.value = '';
  uploadedImagePagesUrlInput.value = '';
  setLastSyncedSnapshotFromText('');
  updateStatsFromEditor();
  refreshVisualEditor();
  syncRepoSummary();
  syncUploadHint();
  syncExternalLinks();
  saveSettings();
  setStatus('success', 'Сохраненные настройки сброшены к значениям по умолчанию.');
}

function inferDefaultsFromPage() {
  const host = window.location.hostname.toLowerCase();
  if (!host.endsWith('.github.io')) {
    return {};
  }

  const owner = host.replace(/\.github\.io$/, '');
  const repoFromPath = guessProjectRepoFromPath(window.location.pathname);

  return {
    owner,
    repo: repoFromPath || `${owner}.github.io`
  };
}

function guessProjectRepoFromPath(pathname) {
  const segments = pathname.split('/').filter(Boolean);
  if (!segments.length) {
    return '';
  }

  if (segments[0] === 'admin') {
    return '';
  }

  if (segments.includes('admin')) {
    return segments[0];
  }

  return '';
}

function saveSettings() {
  const cfg = getConfig();

  localStorage.setItem(
    STORAGE_KEY,
    JSON.stringify({
      owner: cfg.owner,
      repo: cfg.repo,
      branch: cfg.branch,
      path: cfg.path,
      uploadDir: cfg.uploadDir,
      message: cfg.message,
      autoLoadOnStart: cfg.autoLoadOnStart,
      rememberToken: cfg.rememberToken,
      token: cfg.rememberToken ? cfg.token : ''
    })
  );
}

function getConfig() {
  return {
    owner: ownerInput.value.trim(),
    repo: repoInput.value.trim(),
    branch: branchInput.value.trim() || 'main',
    path: pathInput.value.trim() || 'src/content/site-content.json',
    uploadDir: normalizeUploadDir(uploadDirInput.value || DEFAULTS.uploadDir),
    token: tokenInput.value.trim(),
    rememberToken: rememberTokenInput.checked,
    autoLoadOnStart: autoLoadOnStartInput.checked,
    message: messageInput.value.trim() || DEFAULTS.message
  };
}

function requireRepoFields() {
  const cfg = getConfig();

  if (!cfg.owner || !cfg.repo || !cfg.path) {
    throw new Error('Сначала заполните владельца, репозиторий и путь к файлу.');
  }

  return cfg;
}

function getPagesBaseUrl(owner, repo) {
  if (!owner || !repo) return '';
  // eprisj repo → custom domain
  if (owner === 'eprisj' && repo === 'eprisj.github.io') return 'https://eprisjournal.com';
  if (repo.toLowerCase() === `${owner.toLowerCase()}.github.io`) return `https://${owner}.github.io`;
  return `https://${owner}.github.io/${repo}`;
}

function getRepoWebUrl(owner, repo) {
  if (!owner || !repo) {
    return '';
  }
  return `https://github.com/${owner}/${repo}`;
}

function syncRepoSummary() {
  const cfg = getConfig();
  const pagesUrl = getPagesBaseUrl(cfg.owner, cfg.repo);
  const adminUrl = pagesUrl ? `${pagesUrl}/admin/index.html` : '';

  repoSummaryEl.innerHTML = [
    `<strong>Репозиторий:</strong> ${escapeHtml(cfg.owner || '-')} / ${escapeHtml(cfg.repo || '-')}`,
    `<strong>Ветка:</strong> ${escapeHtml(cfg.branch || '-')}`,
    `<strong>Файл контента:</strong> ${escapeHtml(cfg.path || '-')}`,
    `<strong>Папка для фото:</strong> ${escapeHtml(cfg.uploadDir || '-')}`,
    pagesUrl
      ? `<strong>Сайт:</strong> <a href="${escapeHtml(pagesUrl)}" target="_blank" rel="noreferrer">${escapeHtml(pagesUrl)}</a>`
      : '',
    adminUrl
      ? `<strong>URL админки:</strong> <a href="${escapeHtml(adminUrl)}" target="_blank" rel="noreferrer">${escapeHtml(adminUrl)}</a>`
      : ''
  ]
    .filter(Boolean)
    .join('<br />');
}

function syncUploadHint() {
  const cfg = getConfig();
  uploadHintEl.textContent = `Файл загрузится в "${cfg.uploadDir}". Быстрый URL работает сразу, URL сайта начнет работать после деплоя.`;
}

function syncExternalLinks() {
  const cfg = getConfig();
  const repoUrl = getRepoWebUrl(cfg.owner, cfg.repo);
  // Deploy runs via a VPS cron autopull, not GitHub Actions — link to commit
  // history instead, which is what actually reflects what will go live next.
  const actionsUrl = repoUrl ? `${repoUrl}/commits/${encodeURIComponent(cfg.branch || 'main')}` : '#';
  const pagesUrl = getPagesBaseUrl(cfg.owner, cfg.repo) || '#';

  openRepoLink.href = repoUrl || '#';
  openActionsLink.href = actionsUrl;
  openPagesLink.href = pagesUrl;

  openRepoLink.setAttribute('aria-disabled', repoUrl ? 'false' : 'true');
  openActionsLink.setAttribute('aria-disabled', repoUrl ? 'false' : 'true');
  openPagesLink.setAttribute('aria-disabled', pagesUrl !== '#' ? 'false' : 'true');
}

function escapeHtml(value) {
  return String(value)
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;')
    .replaceAll("'", '&#39;');
}

// Keep the SVG icon in action buttons while changing their busy/idle label.
// Older handlers used textContent directly, which silently removed the icon
// and made the chrome jump when an action completed.
function setButtonLabel(button, label) {
  if (!button) return;
  const labelEl = button.querySelector('.btn-label, .sidebar-btn-label');
  if (labelEl) labelEl.textContent = label;
  else button.textContent = label;
}

const ADMIN_ICON_PATHS = Object.freeze({
  edit: '<path d="M12 20h9"></path><path d="M16.5 3.5a2.12 2.12 0 0 1 3 3L7 19l-4 1 1-4L16.5 3.5Z"></path>',
  plus: '<path d="M12 5v14M5 12h14"></path>',
  upload: '<path d="M12 16V4"></path><path d="m7 9 5-5 5 5"></path><path d="M5 20h14"></path>',
  refresh: '<path d="M20 11a8 8 0 0 0-14.8-4L3 10"></path><path d="M3 5v5h5"></path><path d="M4 13a8 8 0 0 0 14.8 4L21 14"></path><path d="M21 19v-5h-5"></path>',
  external: '<path d="M14 5h5v5"></path><path d="M10 14 19 5"></path><path d="M19 14v4a1 1 0 0 1-1 1H6a1 1 0 0 1-1-1V6a1 1 0 0 1 1-1h4"></path>',
  close: '<path d="m6 6 12 12M18 6 6 18"></path>',
});

function adminIcon(name) {
  return `<svg class="btn-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${ADMIN_ICON_PATHS[name] || ADMIN_ICON_PATHS.edit}</svg>`;
}

async function copyPagesUrl() {
  try {
    const cfg = getConfig();
    const pagesUrl = getPagesBaseUrl(cfg.owner, cfg.repo);
    if (!pagesUrl) {
      throw new Error('Сначала заполните владельца и репозиторий.');
    }

    await copyToClipboard(`${pagesUrl}/admin/index.html`);
    setStatus('success', 'URL админки скопирован в буфер обмена.');
  } catch (error) {
    setStatus('error', getErrorMessage(error));
  }
}

async function copyToClipboard(text) {
  if (navigator.clipboard?.writeText) {
    await navigator.clipboard.writeText(text);
    return;
  }

  const temporary = document.createElement('textarea');
  temporary.value = text;
  temporary.style.position = 'fixed';
  temporary.style.opacity = '0';
  document.body.appendChild(temporary);
  temporary.select();
  document.execCommand('copy');
  temporary.remove();
}

function normalizeUploadDir(value) {
  const raw = String(value || '')
    .trim()
    .replaceAll('\\', '/');

  if (!raw) {
    return DEFAULTS.uploadDir;
  }

  return raw.replace(/^\/+/, '').replace(/\/+$/, '');
}

function joinUrl(base, path) {
  return `${String(base || '').replace(/\/+$/, '')}/${String(path || '').replace(/^\/+/, '')}`;
}

function readFileAsBase64(file) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onerror = () => reject(new Error('Не удалось прочитать выбранный файл.'));
    reader.onload = () => {
      const value = String(reader.result || '');
      const commaIndex = value.indexOf(',');
      if (commaIndex === -1) {
        reject(new Error('Не удалось преобразовать файл в base64.'));
        return;
      }
      resolve(value.slice(commaIndex + 1));
    };
    reader.readAsDataURL(file);
  });
}

function pickImageFile() {
  if (pickImageBtn.disabled) {
    return;
  }
  imageFileInput.click();
}

// Instant local preview the moment a file is picked/dropped — before this,
// the only feedback during a multi-second upload was a plain "Загружаю..."
// status line with nothing to look at.
let _uploadPreviewObjectUrl = null;
function showUploadPreview(file) {
  const box = byId('uploadPreviewBox');
  const img = byId('uploadPreviewImg');
  const nameEl = byId('uploadPreviewName');
  const sizeEl = byId('uploadPreviewSize');
  if (!box || !img) return;
  if (_uploadPreviewObjectUrl) URL.revokeObjectURL(_uploadPreviewObjectUrl);
  _uploadPreviewObjectUrl = URL.createObjectURL(file);
  img.src = _uploadPreviewObjectUrl;
  nameEl.textContent = file.name;
  sizeEl.textContent = formatFileSize(file.size);
  box.hidden = false;
}
function formatFileSize(bytes) {
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(0)} KB`;
  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
}
function reportUploadSavings(originalSize, uploadedSize) {
  const sizeEl = byId('uploadPreviewSize');
  if (!sizeEl) return;
  if (uploadedSize < originalSize) {
    const pct = Math.round((1 - uploadedSize / originalSize) * 100);
    sizeEl.textContent = `${formatFileSize(originalSize)} → ${formatFileSize(uploadedSize)} (−${pct}%, сжато автоматически)`;
  } else {
    sizeEl.textContent = `${formatFileSize(originalSize)} · загружено без сжатия`;
  }
}

function onUploadPaste(event) {
  const uploadTab = byId('tab-upload');
  if (!uploadTab || !uploadTab.classList.contains('active')) return;
  const items = event.clipboardData?.items;
  if (!items) return;
  for (const item of items) {
    if (item.kind === 'file' && item.type.startsWith('image/')) {
      const file = item.getAsFile();
      if (!file) continue;
      event.preventDefault();
      showUploadPreview(file);
      uploadImageToGitHub(file);
      return;
    }
  }
}

function onImageFileChange(event) {
  const input = event.target;
  const file = input.files?.[0];
  if (!file) {
    return;
  }
  showUploadPreview(file);
  uploadImageToGitHub(file);
  input.value = '';
}

function onUploadDragEnter(event) {
  event.preventDefault();
  event.stopPropagation();
  uploadDropZone.classList.add('dragover');
}

function onUploadDragLeave(event) {
  event.preventDefault();
  event.stopPropagation();
  const related = event.relatedTarget;
  if (related instanceof Node && uploadDropZone.contains(related)) {
    return;
  }
  uploadDropZone.classList.remove('dragover');
}

function onUploadDrop(event) {
  event.preventDefault();
  event.stopPropagation();
  uploadDropZone.classList.remove('dragover');

  const file = event.dataTransfer?.files?.[0];
  if (!file) {
    return;
  }
  showUploadPreview(file);
  uploadImageToGitHub(file);
}

function injectUploadedUrlIntoCurrentEntry(url) {
  const target = document.getElementById('vf-imageUrl');
  if (!target) {
    return false;
  }

  target.value = url;
  target.dispatchEvent(new Event('input', { bubbles: true }));
  refreshPhotoPreviewFromInputs();
  return true;
}

function applyUrlToCurrentEntry(url, label) {
  const normalized = String(url || '').trim();
  if (!normalized) {
    throw new Error(`Сначала загрузите фото, чтобы появился ${label}.`);
  }

  const updated = injectUploadedUrlIntoCurrentEntry(normalized);
  if (!updated) {
    throw new Error('Сейчас нет поля URL изображения. Откройте запись в разделах "Статьи" или "Галерея".');
  }

  applyVisualChanges();
  setStatus('success', `${label} подставлен и применен в текущей записи. Теперь нажмите «Сохранить запись» или общий «Сохранить».`);
}

async function copyUploadedUrl() {
  try {
    const url = uploadedImageUrlInput.value.trim();
    if (!url) {
      throw new Error('Сначала загрузите фото, чтобы появился быстрый URL.');
    }
    await copyToClipboard(url);
    setStatus('success', 'Быстрый URL загруженного фото скопирован.');
  } catch (error) {
    setStatus('error', getErrorMessage(error));
  }
}

function useUploadedUrlInCurrentEntry() {
  try {
    applyUrlToCurrentEntry(uploadedImageUrlInput.value, 'Быстрый URL');
  } catch (error) {
    setStatus('error', getErrorMessage(error));
  }
}

function useUploadedPagesUrlInCurrentEntry() {
  try {
    applyUrlToCurrentEntry(uploadedImagePagesUrlInput.value, 'URL сайта');
  } catch (error) {
    setStatus('error', getErrorMessage(error));
  }
}

// Images upload straight to the VPS (instant, no GitHub token needed). GitHub
// only gets a best-effort nightly copy as secondary backup — see
// epris-content-snapshot.js on the server.
const UPLOAD_API = 'https://api.eprisjournal.com/upload';

// Per-article read counters from the VPS (public GET /views). Cached for a
// minute; failures resolve to an empty map so callers never await forever.
let _viewsMap = null;
let _viewsFetchedAt = 0;
async function fetchViewsMap(force) {
  if (_viewsMap && !force && Date.now() - _viewsFetchedAt < 60000) return _viewsMap;
  try {
    const r = await fetch('https://api.eprisjournal.com/views');
    const d = await r.json();
    _viewsMap = (d && d.ok && d.views) ? d.views : (_viewsMap || {});
  } catch { _viewsMap = _viewsMap || {}; }
  _viewsFetchedAt = Date.now();
  return _viewsMap;
}

// Web-size cap: photos straight from a camera are 4000px+ / 5-10 MB, which is
// wasted bandwidth for readers. Downscale to max 2000px and re-encode as WebP
// before upload. GIFs pass through untouched (canvas would kill the animation),
// as does anything already small enough where re-encoding wouldn't pay off.
const IMG_MAX_DIMENSION = 2000;
const IMG_COMPRESS_THRESHOLD = 400 * 1024; // below this, upload as-is
async function compressImageForUpload(file) {
  if (file.type === 'image/gif' || file.type === 'image/svg+xml') return file;
  if (file.size <= IMG_COMPRESS_THRESHOLD) return file;
  let bitmap;
  try { bitmap = await createImageBitmap(file); }
  catch { return file; } // unreadable/exotic format — let the server take the original
  try {
    const scale = Math.min(1, IMG_MAX_DIMENSION / Math.max(bitmap.width, bitmap.height));
    const w = Math.max(1, Math.round(bitmap.width * scale));
    const h = Math.max(1, Math.round(bitmap.height * scale));
    const canvas = document.createElement('canvas');
    canvas.width = w; canvas.height = h;
    canvas.getContext('2d').drawImage(bitmap, 0, 0, w, h);
    const blob = await new Promise((resolve) => canvas.toBlob(resolve, 'image/webp', 0.85));
    // Only swap in the re-encode when it actually saves space.
    if (!blob || blob.size >= file.size) return file;
    const base = String(file.name || 'photo').replace(/\.[a-z0-9]{2,5}$/i, '');
    return new File([blob], base + '.webp', { type: 'image/webp' });
  } finally {
    bitmap.close();
  }
}

async function uploadImageToVPS(file) {
  if (!String(file.type || '').startsWith('image/')) {
    throw new Error('Можно загрузить только файл изображения (JPG, PNG, WebP и т.д.).');
  }
  if (file.size > 15 * 1024 * 1024) {
    throw new Error('Файл слишком большой. Максимум: 15 MB.');
  }
  file = await compressImageForUpload(file);
  const base64Content = await readFileAsBase64(file);
  const res = await fetch(UPLOAD_API, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', 'X-Admin-Password': getAdminPassword() },
    body: JSON.stringify({ filename: file.name, contentType: file.type, data: base64Content })
  });
  const data = await res.json().catch(() => ({}));
  if (!res.ok || !data.ok || !data.url) throw new Error(data.error || `Ошибка загрузки на сервер (${res.status})`);
  return data.url;
}

async function uploadImageToGitHub(file) {
  const originalSize = file.size;
  try {
    saveSettings();
    setBusy(true);
    uploadDropZone.classList.add('is-uploading');
    setStatus('info', `Загружаю "${file.name}"...`);

    const url = await uploadImageToVPS(file);
    uploadedImageUrlInput.value = url;
    uploadedImagePagesUrlInput.value = url;
    // HEAD the result to learn the byte size actually stored on the server
    // (compressImageForUpload may have re-encoded it smaller) and show the
    // before/after — makes the automatic compression visible instead of silent.
    fetch(url, { method: 'HEAD' }).then((r) => {
      const len = Number(r.headers.get('content-length'));
      if (len) reportUploadSavings(originalSize, len);
    }).catch(() => {});

    const hasApplied = injectUploadedUrlIntoCurrentEntry(url);
    if (hasApplied) {
      applyVisualChanges();
      setStatus('success', 'Фото загружено. URL подставлен и применен в текущей записи.');
    } else {
      setStatus('success', 'Фото загружено.');
    }
  } catch (error) {
    setStatus('error', getErrorMessage(error));
  } finally {
    setBusy(false);
    uploadDropZone.classList.remove('is-uploading', 'dragover');
    syncUploadHint();
  }
}

// Generic image upload that resolves to the immediate URL (reused by the
// review-photo and issue-cover upload buttons). Does not touch the visual entry.
async function uploadImageReturnUrl(file) {
  return uploadImageToVPS(file);
}

// Wire a file-input + button pair to upload and drop the resulting URL into a
// target text input (and run an optional callback, e.g. to refresh a preview).
function bindUploadButton(btnId, fileInputId, targetInputId, onDone) {
  const btn = document.getElementById(btnId);
  const fileInput = document.getElementById(fileInputId);
  const target = document.getElementById(targetInputId);
  if (!btn || !fileInput || !target) return;
  btn.onclick = () => fileInput.click();
  fileInput.onchange = async () => {
    const file = fileInput.files && fileInput.files[0];
    if (!file) return;
    const original = btn.textContent;
    btn.disabled = true; btn.textContent = 'Загрузка…';
    try {
      const url = await uploadImageReturnUrl(file);
      target.value = url;
      target.dispatchEvent(new Event('input'));
      if (typeof onDone === 'function') onDone(url);
      showToast('success', 'Фото загружено — URL подставлен.');
    } catch (e) {
      showToast('error', getErrorMessage(e));
    } finally {
      btn.disabled = false; btn.textContent = original; fileInput.value = '';
    }
  };
}

function encodePath(path) {
  return path
    .split('/')
    .filter(Boolean)
    .map((segment) => encodeURIComponent(segment))
    .join('/');
}

function decodeBase64Utf8(value) {
  const cleaned = value.replace(/\n/g, '');
  const bytes = Uint8Array.from(atob(cleaned), (char) => char.charCodeAt(0));
  return new TextDecoder().decode(bytes);
}

function encodeBase64Utf8(value) {
  const bytes = new TextEncoder().encode(value);
  let binary = '';
  bytes.forEach((byte) => {
    binary += String.fromCharCode(byte);
  });
  return btoa(binary);
}

function headers(token) {
  const base = {
    Accept: 'application/vnd.github+json',
    'X-GitHub-Api-Version': '2022-11-28'
  };

  if (!token) {
    return base;
  }

  return {
    ...base,
    Authorization: `Bearer ${token}`
  };
}

async function githubRequest(url, options = {}) {
  const response = await fetch(url, {
    cache: 'no-store',
    ...options
  });

  if (response.ok) {
    return response.json();
  }

  let message = `Ошибка GitHub API (${response.status})`;
  try {
    const body = await response.json();
    if (body.message) {
      message = body.message;
    }
  } catch {
    // ignore parse issue
  }

  throw new Error(message);
}

function setBusy(value) {
  for (const button of interactiveButtons) {
    button.disabled = value;
  }
  loadingBarEl.classList.toggle('active', value);
  if (!value && typeof updateAdminToolbarContext === 'function') {
    updateAdminToolbarContext();
  }
}

// Loads the live content from the VPS (source of truth). Name kept for the
// existing callers; persistence moved off GitHub to api.eprisjournal.com/content.
async function loadFromGitHub() {
  try {
    setBusy(true);
    setStatus('info', 'Загружаю контент с VPS...');
    saveSettings();

    const res = await fetch(CONTENT_API, { cache: 'no-store' });
    if (!res.ok) throw new Error('VPS вернул статус ' + res.status);
    const parsed = await res.json();
    validateShape(parsed);

    /* Загрузка с VPS перезаписывает всё, что не сохранено. Раньше она делала
       это молча — одно нажатие стирало несохранённые карточки. Спрашиваем, и
       спрашиваем по делу: сколько именно правок будет потеряно. */
    if (isEditorDirty()) {
      const ok = window.confirm(
        'В редакторе есть изменения, которых нет на VPS.\n\n'
        + 'Загрузка заменит их версией с сервера. Копия текущего черновика попадёт в корзину черновиков — вернуть можно кнопкой «Вернуть черновик».\n\n'
        + 'Загрузить версию VPS?',
      );
      if (!ok) { setStatus('info', 'Загрузка отменена — черновик на месте.'); return; }
    }

    currentSha = '';
    setEditorData(parsed, { markSynced: true, clearDraft: true, reason: 'кнопка «Загрузить с VPS»' });
    lastSyncedTime = new Date();
    updateLastSyncedBadge();
    setStatus('success', 'Контент загружен с VPS (live)');
  } catch (error) {
    setStatus('error', getErrorMessage(error));
  } finally {
    setBusy(false);
  }
}

function parseEditorJson() {
  const raw = editor.value.trim();
  if (!raw) {
    throw new Error('Редактор пуст.');
  }

  try {
    const parsed = JSON.parse(raw);
    validateShape(parsed);
    return parsed;
  } catch (error) {
    if (error instanceof SyntaxError) {
      throw new Error(`Некорректный JSON: ${error.message}`);
    }
    throw error;
  }
}

function parseEditorJsonSafe() {
  try {
    const parsed = JSON.parse(editor.value || '{}');
    return parsed;
  } catch {
    return null;
  }
}

function validateShape(data) {
  if (!data || typeof data !== 'object' || Array.isArray(data)) {
    throw new Error('Корневой элемент JSON должен быть объектом.');
  }

  const required = ['translations', 'items', 'articles', 'reviews', 'libraryItems'];
  for (const key of required) {
    if (!(key in data)) {
      throw new Error(`Отсутствует обязательный ключ: ${key}`);
    }
  }

  if (typeof data.translations !== 'object' || Array.isArray(data.translations)) {
    throw new Error('translations должен быть объектом.');
  }

  for (const key of ['items', 'articles', 'reviews', 'libraryItems']) {
    if (!Array.isArray(data[key])) {
      throw new Error(`${key} должен быть массивом.`);
    }
  }

  if (
    'localizedCollections' in data &&
    (typeof data.localizedCollections !== 'object' || Array.isArray(data.localizedCollections))
  ) {
    throw new Error('localizedCollections должен быть объектом.');
  }

  if ('visibility' in data && (!data.visibility || typeof data.visibility !== 'object' || Array.isArray(data.visibility))) {
    throw new Error('visibility должен быть объектом.');
  }
}

// Mirrors the server's validateEntity() in deploy-webhook.js for instant
// feedback before the round trip — the server is still the source of truth
// (there's no shared module system between the Node backend and this
// no-build-step admin bundle, so this is intentionally duplicated).
const ENTITY_REQUIRED_FIELDS = {
  articles:     { id: 'id', title: 'string', author: 'string', date: 'string', excerpt: 'string', category: 'string', imageSeed: 'string', tags: 'array', content: 'array' },
  reviews:      { id: 'id', title: 'string', subject: 'string', rating: 'rating', content: 'stringOrArray', author: 'string' },
  items:        { id: 'id', title: 'string', subtitle: 'string', fig: 'string', description: 'string', imageSeed: 'string' },
  libraryItems: { id: 'id', title: 'string', type: 'string', size: 'string', year: 'string' },
};
const ENTITY_OPTIONAL_FIELDS = {
  articles:     { role: 'string', subcategory: 'string', imageUrl: 'string', draft: 'boolean', publishAt: 'isoDate' },
  reviews:      { category: 'string', imageUrl: 'string', verdict: 'string', pros: 'array', cons: 'array', meta: 'string', link: 'string', date: 'string', featured: 'boolean', draft: 'boolean', publishAt: 'isoDate' },
  items:        { imageUrl: 'string', draft: 'boolean', publishAt: 'isoDate' },
  libraryItems: { url: 'string', draft: 'boolean', publishAt: 'isoDate' },
};
function validateEntityShape(section, entity) {
  if (!ENTITY_REQUIRED_FIELDS[section]) return `unknown section: ${section}`;
  if (!entity || typeof entity !== 'object' || Array.isArray(entity)) return 'entity must be an object';
  const check = (spec, required) => {
    for (const [field, kind] of Object.entries(spec)) {
      // hasOwnProperty alone isn't enough: buildEntryFromVisualForm spreads
      // `{ ...next, imageUrl: getOptionalString(...) }`, and an *unset*
      // optional string produces `undefined` — object-spread still creates
      // the key, so `hasOwnProperty` reports "present" for a field the user
      // simply left blank. That made every empty optional field (imageUrl,
      // link, verdict, meta, date...) fail its type check and silently block
      // the save with an error the calling code never surfaced anywhere
      // visible. Treat undefined/null the same as "not present" here.
      const present = Object.prototype.hasOwnProperty.call(entity, field) && entity[field] != null;
      if (!present) { if (required) return `missing field: ${field}`; continue; }
      const v = entity[field];
      if (kind === 'id' && !(Number.isInteger(v) && v > 0)) return `${field} must be a positive integer`;
      if (kind === 'string' && typeof v !== 'string') return `${field} must be a string`;
      if (kind === 'stringOrArray' && typeof v !== 'string' && !Array.isArray(v)) return `${field} must be a string or an array`;
      if (kind === 'array' && !Array.isArray(v)) return `${field} must be an array`;
      if (kind === 'boolean' && typeof v !== 'boolean') return `${field} must be a boolean`;
      if (kind === 'rating' && !(typeof v === 'number' && v >= 0 && v <= 5)) return 'rating must be a number 0-5';
      if (kind === 'isoDate' && Number.isNaN(Date.parse(v))) return `${field} must be a valid ISO date string`;
    }
    return null;
  };
  return check(ENTITY_REQUIRED_FIELDS[section], true) || check(ENTITY_OPTIONAL_FIELDS[section], false);
}

function normalizeEntityForServer(section, entity) {
  // The VPS and public reader both support structured review blocks. Preserve
  // the array exactly as the visual editor created it: flattening it here used
  // to turn image URLs and captions into visible paragraphs on the live page.
  if (section !== 'articles' && section !== 'reviews') return entity;

  // Editorial copy uses a spaced en dash. Pasted Word/Docs text often brings
  // an em dash with no surrounding spaces ("grammar—and"), which reads like
  // an accidental long gap in the journal typography. Normalise prose on save
  // while leaving URLs, slugs, media paths and machine identifiers untouched.
  const machineKeys = new Set([
    'id', 'slug', 'imageUrl', 'imageSeed', 'url', 'link', 'src', 'href',
    'authorId', 'type', 'layout', 'align', 'aspectRatio', 'publishAt',
    // Machine values, not prose: an ISO date, a card cover URL and a CSS
    // object-position keyword have no business being run through the em-dash
    // normaliser that exists for pasted editorial copy.
    'publishedAt', 'previewImageUrl', 'previewFocus',
  ]);
  const normalisePunctuation = (value, key = '') => {
    if (typeof value === 'string') {
      return machineKeys.has(key) ? value : value.replace(/\s*—\s*/g, ' – ');
    }
    if (Array.isArray(value)) return value.map((item) => normalisePunctuation(item, key));
    if (!value || typeof value !== 'object') return value;
    return Object.fromEntries(
      Object.entries(value).map(([childKey, childValue]) => [
        childKey,
        normalisePunctuation(childValue, childKey),
      ]),
    );
  };

  return normalisePunctuation(entity);
}

function validateJson() {
  try {
    const parsed = parseEditorJson();
    updateStats(parsed);
    setStatus('success', 'JSON корректный и имеет ожидаемую структуру.');
  } catch (error) {
    setStatus('error', getErrorMessage(error));
  }
}

function formatJson() {
  try {
    const parsed = parseEditorJson();
    setEditorData(parsed);
    setStatus('success', 'JSON отформатирован.');
  } catch (error) {
    setStatus('error', getErrorMessage(error));
  }
}

function updateStatsFromEditor() {
  const parsed = parseEditorJsonSafe();
  if (!parsed) {
    const bytes = new Blob([editor.value || '']).size;
    statsEl.innerHTML = [
      '<div class="stat-row"><span>JSON</span><strong>Ошибка</strong></div>',
      `<div class="stat-row"><span>Размер (байт)</span><strong>${bytes}</strong></div>`
    ].join('');
    return;
  }

  updateStats(parsed);
}

function updateStats(data) {
  const bytes = new Blob([editor.value || '']).size;
  const localized = data.localizedCollections && typeof data.localizedCollections === 'object'
    ? Object.keys(data.localizedCollections).length
    : 0;

  const rows = [
    ['Языки интерфейса', typeof data.translations === 'object' && data.translations ? Object.keys(data.translations).length : 0],
    ['Локализованные коллекции', localized],
    ['Элементы галереи', Array.isArray(data.items) ? data.items.length : 0],
    ['Статьи', Array.isArray(data.articles) ? data.articles.length : 0],
    ['Обзоры', Array.isArray(data.reviews) ? data.reviews.length : 0],
    ['Размер (байт)', bytes]
  ];

  statsEl.innerHTML = rows
    .map(([label, count]) => `<div class="stat-row"><span>${label}</span><strong>${count}</strong></div>`)
    .join('');

  // Overview strip — quick stats bar at top of content tab
  const strip = document.getElementById('overviewStrip');
  if (strip) {
    const articlesCount = Array.isArray(data.articles) ? data.articles.length : 0;
    const reviewsCount = Array.isArray(data.reviews) ? data.reviews.length : 0;
    const itemsCount = Array.isArray(data.items) ? data.items.length : 0;
    const langCount = typeof data.translations === 'object' && data.translations ? Object.keys(data.translations).length : 0;
    const kbSize = Math.round(bytes / 1024);

    const articlesWithContent = Array.isArray(data.articles)
      ? data.articles.filter(a => Array.isArray(a.content) && a.content.length > 0).length
      : 0;
    const articlesWithPhoto = Array.isArray(data.articles)
      ? data.articles.filter(a => a.imageUrl || a.imageSeed).length
      : 0;

    strip.style.display = 'grid';
    strip.innerHTML = [
      { label: 'Статьи', value: articlesCount, sub: `${articlesWithContent} с контентом` },
      { label: 'С фото', value: articlesWithPhoto, sub: `из ${articlesCount} статей` },
      { label: 'Обзоры', value: reviewsCount, sub: 'записей' },
      { label: 'Галерея', value: itemsCount, sub: 'элементов' },
      { label: 'Языки UI', value: langCount, sub: `+ EN базовый` },
      { label: 'Размер', value: `${kbSize}`, sub: 'КБ' },
    ].map(({ label, value, sub }) =>
      `<div class="overview-cell">
        <div class="overview-cell-label">${label}</div>
        <div class="overview-cell-value">${value}</div>
        <div class="overview-cell-sub">${sub}</div>
      </div>`
    ).join('');
  }
}

const MONITOR_LEVEL_ORDER = {
  info: 0,
  ok: 1,
  warn: 2,
  error: 3
};

function getHigherMonitorLevel(left, right) {
  const leftScore = MONITOR_LEVEL_ORDER[left] ?? 0;
  const rightScore = MONITOR_LEVEL_ORDER[right] ?? 0;
  return leftScore >= rightScore ? left : right;
}

function createMonitorResult(level, title, detail, items = [], linkUrl = '', linkLabel = '') {
  return {
    level,
    title,
    detail,
    items,
    linkUrl,
    linkLabel
  };
}

function monitorLabel(level) {
  if (level === 'ok') return 'OK';
  if (level === 'warn') return 'Внимание';
  if (level === 'error') return 'Ошибка';
  return 'Инфо';
}

function renderMonitoringResults(results) {
  const counts = {
    ok: 0,
    warn: 0,
    error: 0,
    info: 0
  };

  for (const result of results) {
    counts[result.level] = (counts[result.level] || 0) + 1;
  }

  monitorGridEl.innerHTML = results
    .map((result) => {
      const list = Array.isArray(result.items) && result.items.length
        ? `<ul class="monitor-card-list">${result.items.map((item) => `<li>${escapeHtml(item)}</li>`).join('')}</ul>`
        : '';

      const link = result.linkUrl
        ? `<a class="monitor-card-link" target="_blank" rel="noreferrer" href="${escapeHtml(result.linkUrl)}">${escapeHtml(result.linkLabel || 'Открыть')}</a>`
        : '';

      return `
        <article class="monitor-card ${escapeHtml(result.level)}">
          <div class="monitor-card-head">
            <h3 class="monitor-card-title">${escapeHtml(result.title)}</h3>
            <span class="monitor-pill ${escapeHtml(result.level)}">${monitorLabel(result.level)}</span>
          </div>
          <p class="monitor-card-detail">${escapeHtml(result.detail)}</p>
          ${list}
          ${link}
        </article>
      `;
    })
    .join('');

  const summaryLevel = counts.error > 0 ? 'error' : counts.warn > 0 ? 'warn' : 'ok';
  monitorSummaryEl.className = `monitor-summary is-${summaryLevel}`;
  monitorSummaryEl.textContent = `OK: ${counts.ok} · Внимание: ${counts.warn} · Ошибки: ${counts.error} · Инфо: ${counts.info}`;
  monitorTimestampEl.textContent = `Последняя проверка: ${new Date().toLocaleString('ru-RU')}`;
}

function collectDuplicateIdIssues(entries, sectionLabel) {
  const seen = new Set();
  const duplicates = new Set();

  for (const entry of entries || []) {
    const id = Number(entry?.id);
    if (!Number.isFinite(id)) {
      continue;
    }
    if (seen.has(id)) {
      duplicates.add(id);
    } else {
      seen.add(id);
    }
  }

  if (!duplicates.size) {
    return [];
  }

  return [`${sectionLabel}: дубли ID (${Array.from(duplicates).join(', ')})`];
}

// Mirrors isPlaceholderEntity() in src/data.ts — an entry left as an unedited
// blueprint stub. Kept in sync by hand; the public site is the source of truth.
const AUDIT_PLACEHOLDER_TITLES = new Set([
  'new editorial story', 'new practical guide', 'new photo essay',
  'new review', 'new gallery item', 'new file',
  'neues galerieelement', 'nuevo elemento de la galería', 'yeni galeri öğesi',
  'nuovo elemento della galleria', 'новый элемент галереи', 'новий елемент галереї',
  'neue redaktionelle geschichte', 'nueva historia editorial', 'yeni editoryal hikaye',
  'nuova storia editoriale', 'новая редакционная история', 'нова редакційна історія',
]);
const AUDIT_PLACEHOLDER_PHRASES = [
  'replace me', 'replace with real copy before publishing',
  'замініть мене', 'замініть на справжню копію',
  'замените меня', 'замените реальной копией',
  'ersetze mich', 'reemplázame', 'beni değiştir', 'sostituiscimi',
];
function isAuditPlaceholderEntity(entry) {
  if (!entry || typeof entry !== 'object') return false;
  const title = String(entry.title || '').trim().toLowerCase();
  if (title && AUDIT_PLACEHOLDER_TITLES.has(title)) return true;
  const haystack = [entry.subtitle, entry.description, entry.excerpt]
    .filter((v) => typeof v === 'string').join(' ').toLowerCase();
  return AUDIT_PLACEHOLDER_PHRASES.some((p) => haystack.includes(p));
}

// The single worst failure mode in this content model: getContentForLanguage()
// discards a WHOLE locale bucket (items/articles/reviews/libraryItems) back to
// English the moment *any one* entry in it is still an unfilled stub — see the
// long comment above mergeLocalizedItems in src/data.ts. One forgotten "New
// gallery item" is invisible in the editor (it just looks like a draft card
// sitting in a list) but silently un-translates every OTHER card in that
// language too. That is exactly what happened to the homepage gallery before
// this check existed: id 8 and 9 sat unfilled for months and every non-English
// reader saw an all-English homepage with no error anywhere. This check is the
// only thing that surfaces it.
function runLocalizationHealthCheck(data) {
  if (!data) {
    return createMonitorResult('warn', 'Локализация и главная', 'Проверка ограничена, пока JSON невалиден.', []);
  }

  const errors = [];
  const warnings = [];
  // `strict: true` sections go through mergeLocalizedItems in src/data.ts,
  // which discards the WHOLE bucket back to English if any one entry is a
  // stub. `strict: false` sections go through mergeLocalizedArray, which
  // only skips the one stub entry — its siblings translate fine. Keep this
  // list in sync with the const article/reviews/items/libraryItems lines in
  // getContentForLanguage(); getting it backwards makes this check cry wolf
  // (or worse, miss a real whole-bucket poisoning).
  const POISON_SECTIONS = [
    ['items', 'Галерея', true],
    ['reviews', 'Обзоры', true],
    ['articles', 'Статьи', false],
    ['libraryItems', 'Библиотека', false],
  ];

  const localized = data.localizedCollections && typeof data.localizedCollections === 'object'
    ? data.localizedCollections : {};

  /* СНАЧАЛА БАЗА, ПОТОМ ЛОКАЛИ.

     Проверка смотрела только в localizedCollections и поэтому описывала
     следствия. Живой случай 17.08.2026: заготовка «New gallery item» (#15)
     лежала В БАЗЕ, переводчик добросовестно перевёл её на шесть языков — и
     отчёт выдал шесть одинаковых ошибок про шесть локалей, ни одна из которых
     не была причиной. Причина одна, и чинится она одним удалением: пока
     заготовка в базе, её будут переводить снова после любого «Сохранить».

     Чего заготовка НЕ делает: читателям она не показывается. getContentForLanguage
     отбрасывает заготовки из базы (`liveBase`) ещё до слияния, а isEntityLive
     ловит их второй раз. Вред у неё ровно один и косвенный — из-за неё локальный
     список расходится с базой и содержит переведённую заготовку, а это два
     сигнала, по которым mergeLocalizedItems выбрасывает ВЕСЬ языковой список.
     Формулировать сильнее, чем есть, нельзя: «её видят читатели» отправило бы
     редакцию тушить пожар не там. */
  const baseStubHint = new Set();
  for (const [sectionKey, sectionLabel, strict] of POISON_SECTIONS) {
    const entries = Array.isArray(data[sectionKey]) ? data[sectionKey] : [];
    const stubs = entries.filter(isAuditPlaceholderEntity);
    if (!stubs.length) continue;
    const ids = stubs.map((e) => `#${e?.id ?? '?'}`).join(', ');
    baseStubHint.add(sectionKey);
    const line = `ПРИЧИНА — база/${sectionLabel}: незаполненная заготовка (${ids}) лежит в основном списке. Читателям она не видна (сайт прячет заготовки), но ${strict ? `её переводы откатывают ВЕСЬ ${sectionLabel.toLowerCase()} на всех языках к английскому` : 'её переводы остаются английскими у соседних записей'}. Удалите её (или заполните) — это чинит все строки ниже разом.`;
    if (strict) errors.push(line); else warnings.push(line);
  }

  for (const [lang, bucket] of Object.entries(localized)) {
    if (!bucket || typeof bucket !== 'object') continue;
    for (const [sectionKey, sectionLabel, strict] of POISON_SECTIONS) {
      const entries = bucket[sectionKey];
      if (!Array.isArray(entries)) continue;
      const stubs = entries.filter(isAuditPlaceholderEntity);
      if (!stubs.length) continue;
      const ids = stubs.map((e) => `#${e?.id ?? '?'}`).join(', ');
      /* Перевод заготовки — следствие заготовки. Пока она в базе, эти строки
         будут появляться снова после каждой достройки языков, и чинить их по
         одной бессмысленно: они уйдут сами, как только уйдёт оригинал. */
      const cause = baseStubHint.has(sectionKey) ? ' Это перевод заготовки из базы — удалите её, а не эту копию.' : '';
      if (strict) {
        errors.push(
          `${lang}/${sectionLabel}: незаполненная заготовка (${ids}) — из-за неё ВЕСЬ ${sectionLabel.toLowerCase()} на ${lang} читатели видят по-английски, не только эту карточку.${cause || ' Заполните или удалите.'}`
        );
      } else {
        warnings.push(
          `${lang}/${sectionLabel}: незаполненная заготовка (${ids}) — эта карточка останется на английском для читателей ${lang}, соседние записи не пострадают.${cause || ' Заполните или удалите, когда дойдут руки.'}`
        );
      }
    }
  }

  // Per-entry content-shape divergence — the "recycled id" variant of the
  // same family of bug. Review #1 lived this on 2026-08-02: its base entry
  // was rewritten from a short string review into a 14-block photo essay,
  // but every locale's entry.content was still the OLD string from whatever
  // review used to sit under this id. Content itself is safe — a type/length
  // mismatch makes mergeContentBlocks fall back to base — but title/subject/
  // verdict/pros/cons overlay onto the merge regardless, so readers saw the
  // right photos and body text captioned with a completely different
  // restaurant's name and verdict. No stub phrase involved, so the
  // placeholder check above can't see it; a shape mismatch is the only cheap,
  // reliable proxy that something here is a frozen snapshot, not a
  // translation of what the base entry actually is now.
  for (const [lang, bucket] of Object.entries(localized)) {
    if (!bucket || typeof bucket !== 'object') continue;
    for (const [sectionKey] of POISON_SECTIONS) {
      const baseEntries = Array.isArray(data[sectionKey]) ? data[sectionKey] : [];
      const locEntries = Array.isArray(bucket[sectionKey]) ? bucket[sectionKey] : [];
      for (const loc of locEntries) {
        const base = baseEntries.find((b) => Number(b && b.id) === Number(loc && loc.id));
        if (!base || !('content' in base) || !('content' in loc)) continue;
        const baseIsArr = Array.isArray(base.content);
        const locIsArr = Array.isArray(loc.content);
        if (baseIsArr !== locIsArr) {
          warnings.push(
            `${lang}/${sectionKey} #${loc.id}: content другого типа (в базе ${baseIsArr ? 'массив блоков' : typeof base.content}, в ${lang} — ${locIsArr ? 'массив блоков' : typeof loc.content}) — похоже на замороженный перевод от старой версии записи. Заголовок/подзаголовок всё равно накладываются поверх, проверьте вручную.`
          );
        } else if (baseIsArr && base.content.length !== loc.content.length) {
          warnings.push(
            `${lang}/${sectionKey} #${loc.id}: content другой длины (в базе ${base.content.length} блоков, в ${lang} — ${loc.content.length}) — вероятно, устаревший перевод.`
          );
        }
      }
    }
  }

  const level = errors.length > 0 ? 'error' : warnings.length > 0 ? 'warn' : 'ok';
  const detail = level === 'error'
    ? 'Незаполненная заготовка глушит перевод целого раздела — это ошибка, не предупреждение.'
    : level === 'warn'
      ? 'Есть предупреждения по локалям или медиаданным.'
      : 'Локали синхронизированы, а фотоподборка отделена от статей.';

  /* Список режется до десяти строк, и раньше он резался молча: живой отчёт
     17.08.2026 показал шесть локалей и четыре расхождения — ровно десять — а
     седьмая локаль с той же заготовкой в отчёт не попала и выглядела здоровой.
     Обрезка теперь называет себя, чтобы «десять строк» не читалось как «всего
     десять проблем». */
  const all = [...errors, ...warnings];
  const shown = all.slice(0, 10);
  if (all.length > shown.length) {
    shown.push(`…и ещё ${all.length - shown.length}: показаны первые 10 из ${all.length}. Причины (строки «ПРИЧИНА —») всегда идут первыми.`);
  }
  return createMonitorResult(level, 'Локализация и главная', detail, shown);
}

function runContentQualityChecks(data) {
  if (!data) {
    return createMonitorResult('error', 'Качество контента', 'JSON некорректный. Сначала исправьте структуру.', []);
  }

  const issues = [];
  const warnings = [];

  const sections = [
    ['items', 'Галерея'],
    ['articles', 'Статьи'],
    ['reviews', 'Обзоры']
  ];

  for (const [sectionKey, sectionLabel] of sections) {
    if (!Array.isArray(data[sectionKey])) {
      issues.push(`${sectionLabel}: отсутствует массив ${sectionKey}`);
      continue;
    }
    warnings.push(...collectDuplicateIdIssues(data[sectionKey], sectionLabel));
  }

  const translations = data.translations && typeof data.translations === 'object' ? data.translations : {};
  const baseTranslation = translations[DEFAULT_LANGUAGE] && typeof translations[DEFAULT_LANGUAGE] === 'object'
    ? translations[DEFAULT_LANGUAGE]
    : {};
  const baseKeys = Object.keys(baseTranslation);

  for (const [lang, bucket] of Object.entries(translations)) {
    if (lang === DEFAULT_LANGUAGE || !bucket || typeof bucket !== 'object') {
      continue;
    }
    const missing = baseKeys.filter((key) => !String(bucket[key] ?? '').trim());
    if (missing.length) {
      warnings.push(`${lang}: не заполнено ключей интерфейса — ${missing.length}`);
    }
  }

  const localized = data.localizedCollections && typeof data.localizedCollections === 'object'
    ? data.localizedCollections
    : {};

  for (const [lang, bucket] of Object.entries(localized)) {
    if (!bucket || typeof bucket !== 'object') {
      issues.push(`${lang}: локализованная коллекция повреждена.`);
      continue;
    }

    for (const [sectionKey, sectionLabel] of sections) {
      if (!Array.isArray(bucket[sectionKey])) {
        warnings.push(`${lang}: нет массива ${sectionKey}, используется EN fallback.`);
        continue;
      }

      if (Array.isArray(data[sectionKey]) && bucket[sectionKey].length !== data[sectionKey].length) {
        warnings.push(`${lang}/${sectionLabel}: ${bucket[sectionKey].length} записей вместо ${data[sectionKey].length}`);
      }

      warnings.push(...collectDuplicateIdIssues(bucket[sectionKey], `${lang}/${sectionLabel}`));
    }
  }

  const level = issues.length > 0 ? 'error' : warnings.length > 0 ? 'warn' : 'ok';
  const detail = level === 'ok'
    ? 'Ключевые проверки структуры, ID и переводов пройдены.'
    : issues.length > 0
      ? 'Найдены критичные проблемы в структуре контента.'
      : 'Есть предупреждения по переводам или локализованным коллекциям.';

  return createMonitorResult(level, 'Качество контента', detail, [...issues, ...warnings].slice(0, 8));
}

function runMediaQualityChecks(data) {
  if (!data) {
    return createMonitorResult('warn', 'Медиа и изображения', 'Проверка медиа ограничена, пока JSON невалиден.', []);
  }

  const warnings = [];
  const errors = [];

  const checkRecords = (entries, sectionLabel) => {
    for (const entry of entries || []) {
      const imageUrl = String(entry?.imageUrl || '').trim();
      const imageSeed = String(entry?.imageSeed || '').trim();
      if (!imageUrl && !imageSeed) {
        warnings.push(`${sectionLabel} #${entry?.id ?? '?'}: нет imageUrl и imageSeed`);
      }

      if (imageUrl && !/^(https?:)?\/\//i.test(imageUrl) && !imageUrl.startsWith('/') && !imageUrl.startsWith('./') && !imageUrl.startsWith('../')) {
        errors.push(`${sectionLabel} #${entry?.id ?? '?'}: imageUrl имеет неподдерживаемый формат`);
      }
    }
  };

  checkRecords(data.items, 'Галерея');
  checkRecords(data.articles, 'Статьи');

  const level = errors.length > 0 ? 'error' : warnings.length > 0 ? 'warn' : 'ok';
  const detail = level === 'ok'
    ? 'Медиа-поля заполнены корректно.'
    : errors.length > 0
      ? 'Обнаружены ошибки формата URL изображений.'
      : 'Есть записи без imageUrl/imageSeed.';

  return createMonitorResult(level, 'Медиа и изображения', detail, [...errors, ...warnings].slice(0, 8));
}

async function runGitHubAuthCheck(cfg) {
  if (!cfg.token) {
    return createMonitorResult('warn', 'Доступ GitHub API', 'Токен не заполнен. Часть проверок и запись в репозиторий недоступны.', []);
  }

  try {
    const payload = await githubRequest('https://api.github.com/user', {
      method: 'GET',
      headers: headers(cfg.token)
    });
    return createMonitorResult('ok', 'Доступ GitHub API', `Токен валиден. Пользователь: ${payload.login || 'unknown'}.`, []);
  } catch (error) {
    return createMonitorResult('error', 'Доступ GitHub API', `Ошибка авторизации: ${getErrorMessage(error)}`, []);
  }
}

// Deploy is a VPS cron autopull (push → within ~2 min live), not GitHub
// Actions — the site hasn't used GitHub Pages since the 2026-07-01 VPS
// migration. This compares the commit actually live on the VPS against the
// branch HEAD on GitHub, via the read-only /deploy-status endpoint.
async function runDeployStatusCheck(cfg) {
  if (!cfg.owner || !cfg.repo) {
    return createMonitorResult('warn', 'Статус деплоя', 'Заполните owner/repo для проверки деплоя.', []);
  }

  let vps;
  try {
    const r = await fetch('https://api.eprisjournal.com/deploy-status', { cache: 'no-store', signal: AbortSignal.timeout(8000) });
    vps = await r.json();
    if (!vps.ok) throw new Error(vps.error || 'VPS вернул ошибку');
  } catch (error) {
    return createMonitorResult('error', 'Статус деплоя', `VPS недоступен: ${getErrorMessage(error)}`, []);
  }

  try {
    const head = await githubRequest(
      `https://api.github.com/repos/${encodeURIComponent(cfg.owner)}/${encodeURIComponent(cfg.repo)}/commits/${encodeURIComponent(cfg.branch)}`,
      { method: 'GET', headers: { ...headers(cfg.token), Accept: 'application/vnd.github.sha' } }
    ).catch(async () => {
      // fallback: some proxies mangle the sha media type — ask for the JSON form instead
      return githubRequest(
        `https://api.github.com/repos/${encodeURIComponent(cfg.owner)}/${encodeURIComponent(cfg.repo)}/commits/${encodeURIComponent(cfg.branch)}?per_page=1`,
        { method: 'GET', headers: headers(cfg.token) }
      );
    });
    const headSha = typeof head === 'string' ? head.trim() : (head && head.sha) || '';
    const when = vps.lastDeployAt ? new Date(vps.lastDeployAt).toLocaleString('ru-RU') : 'неизвестно';

    if (headSha && vps.commit && headSha === vps.commit) {
      return createMonitorResult('ok', 'Статус деплоя', `VPS на актуальном коммите ${vps.commitShort} — «${vps.subject}». Последний деплой: ${when}.`, []);
    }
    if (headSha) {
      return createMonitorResult('warn', 'Статус деплоя', `VPS на ${vps.commitShort} («${vps.subject}»), на GitHub есть более новый коммит ${headSha.slice(0, 7)}. Автопул раз в 2 мин — подождите или запустите деплой вручную.`, []);
    }
    return createMonitorResult('ok', 'Статус деплоя', `VPS на коммите ${vps.commitShort} — «${vps.subject}». Последний деплой: ${when}.`, []);
  } catch (error) {
    // Can't reach GitHub to compare — still report what's actually live, which is the important part.
    const when = vps.lastDeployAt ? new Date(vps.lastDeployAt).toLocaleString('ru-RU') : 'неизвестно';
    return createMonitorResult('warn', 'Статус деплоя', `VPS на коммите ${vps.commitShort} — «${vps.subject}» (деплой: ${when}). Не удалось сверить с GitHub: ${getErrorMessage(error)}`, []);
  }
}

async function probeUrl(url) {
  try {
    const response = await fetch(url, {
      method: 'HEAD',
      cache: 'no-store'
    });

    if (response.ok) {
      return { level: 'ok', detail: `${url} доступен (HTTP ${response.status}).` };
    }

    if (response.status >= 500) {
      return { level: 'error', detail: `${url} отвечает ошибкой сервера (HTTP ${response.status}).` };
    }

    return { level: 'warn', detail: `${url} отвечает с кодом HTTP ${response.status}.` };
  } catch {
    try {
      await fetch(url, {
        method: 'GET',
        mode: 'no-cors',
        cache: 'no-store'
      });
      return { level: 'warn', detail: `${url}: браузер не дал прочитать HTTP-статус (CORS), но запрос отправлен.` };
    } catch (error) {
      return { level: 'error', detail: `${url} недоступен: ${getErrorMessage(error)}` };
    }
  }
}

async function runPagesAvailabilityCheck(cfg) {
  const pagesUrl = getPagesBaseUrl(cfg.owner, cfg.repo);
  if (!pagesUrl) {
    return createMonitorResult('warn', 'Доступность сайта', 'Не удалось вычислить URL Pages для проверки.', []);
  }

  const adminUrl = joinUrl(pagesUrl, 'admin/index.html');
  const siteProbe = await probeUrl(pagesUrl);
  const adminProbe = await probeUrl(adminUrl);
  const level = getHigherMonitorLevel(siteProbe.level, adminProbe.level);

  return createMonitorResult(
    level,
    'Доступность сайта',
    'Проверка главной страницы и админки завершена.',
    [siteProbe.detail, adminProbe.detail],
    pagesUrl,
    'Открыть сайт'
  );
}

async function runUploadDirectoryCheck(cfg) {
  if (!cfg.owner || !cfg.repo) {
    return createMonitorResult('warn', 'Папка загрузок', 'Заполните owner/repo, чтобы проверить папку загрузок.', []);
  }

  if (!cfg.uploadDir.startsWith('public/')) {
    return createMonitorResult('error', 'Папка загрузок', 'Папка для фото должна быть внутри public/.', []);
  }

  try {
    const payload = await githubRequest(
      `https://api.github.com/repos/${encodeURIComponent(cfg.owner)}/${encodeURIComponent(cfg.repo)}/contents/${encodePath(cfg.uploadDir)}?ref=${encodeURIComponent(cfg.branch)}`,
      {
        method: 'GET',
        headers: headers(cfg.token)
      }
    );

    if (!Array.isArray(payload)) {
      return createMonitorResult('warn', 'Папка загрузок', `Путь ${cfg.uploadDir} существует, но не является папкой.`, []);
    }

    const files = payload.filter((item) => item && item.type === 'file');
    const latest = files
      .slice(0, 3)
      .map((item) => String(item.name || '').trim())
      .filter(Boolean);

    return createMonitorResult(
      'ok',
      'Папка загрузок',
      `Папка ${cfg.uploadDir} доступна. Файлов: ${files.length}.`,
      latest.length ? [`Последние файлы: ${latest.join(', ')}`] : []
    );
  } catch (error) {
    const message = getErrorMessage(error);
    if (/404/.test(message) || /Not Found/i.test(message)) {
      return createMonitorResult('warn', 'Папка загрузок', `Папка ${cfg.uploadDir} пока не создана. Она появится после первой загрузки.`, []);
    }

    return createMonitorResult('error', 'Папка загрузок', `Не удалось проверить папку: ${message}`, []);
  }
}

async function runMonitoringChecks(options = {}) {
  const mode = options.mode === 'full' ? 'full' : 'local';
  const cfg = getConfig();
  const content = parseEditorJsonSafe();

  if (mode === 'full') {
    monitorRunBtn.disabled = true;
    monitorRunBtn.textContent = 'Проверка...';
  }

  try {
    const localResults = [
      runContentQualityChecks(content),
      runMediaQualityChecks(content),
      runLocalizationHealthCheck(content)
    ];

    let remoteResults = [];
    if (mode === 'full') {
      remoteResults = await Promise.all([
        runGitHubAuthCheck(cfg),
        runDeployStatusCheck(cfg),
        runPagesAvailabilityCheck(cfg),
        runUploadDirectoryCheck(cfg)
      ]);
    } else {
      remoteResults = [
        createMonitorResult(
          'info',
          'Внешние проверки',
          'Быстрая локальная проверка завершена. Для полного мониторинга нажмите «Обновить мониторинг».',
          []
        )
      ];
    }

    renderMonitoringResults([...remoteResults, ...localResults]);
  } finally {
    if (mode === 'full') {
      monitorRunBtn.disabled = false;
      monitorRunBtn.textContent = 'Обновить мониторинг';
    }
  }
}

function downloadJson() {
  try {
    const parsed = parseEditorJson();
    const blob = new Blob([JSON.stringify(parsed, null, 2) + '\n'], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = 'site-content.json';
    link.click();
    URL.revokeObjectURL(url);
    setStatus('success', 'Снимок JSON скачан.');
  } catch (error) {
    setStatus('error', getErrorMessage(error));
  }
}

function isOriginalImageUrl(value) {
  return typeof value === 'string'
    && /(^https?:\/\/|^\/|^\.\/|^\.\.\/).+\.(png|jpe?g|webp|gif|avif)(\?|#|$)/i.test(value);
}

function collectOriginalImageUrls(value, urls) {
  if (isOriginalImageUrl(value)) {
    urls.add(value);
    return;
  }
  if (Array.isArray(value)) {
    value.forEach((item) => collectOriginalImageUrls(item, urls));
    return;
  }
  if (value && typeof value === 'object') {
    Object.values(value).forEach((item) => collectOriginalImageUrls(item, urls));
  }
}

function countArticleOriginals(article) {
  if (!article || typeof article !== 'object') return 0;
  const urls = new Set();
  if (isOriginalImageUrl(article.imageUrl)) urls.add(article.imageUrl);
  collectOriginalImageUrls(article.content || [], urls);
  return urls.size;
}

function pluralImages(count) {
  const mod10 = count % 10;
  const mod100 = count % 100;
  if (mod10 === 1 && mod100 !== 11) return 'изображение';
  if (mod10 >= 2 && mod10 <= 4 && (mod100 < 12 || mod100 > 14)) return 'изображения';
  return 'изображений';
}

function updateAdminToolbarContext() {
  const data = getVisualData();
  if (!data) return;

  const section = visualSectionSelect.value;
  // The primary action must name the thing the editor is creating. A generic
  // “Add” was easy to miss and, worse, made it unclear whether it added a
  // block, a translation, a photo, or an entirely new article.
  const createAction = {
    articles: { label: '+ Создать статью', title: 'Создать новый материал как черновик; переводы запускаются отдельно' },
    reviews: { label: '+ Создать обзор', title: 'Создать новый обзор как черновик; переводы запускаются отдельно' },
    items: { label: '+ Добавить фото', title: 'Создать карточку как черновик; переводы запускаются отдельно' },
    libraryItems: { label: '+ Добавить файл', title: 'Создать запись сразу; перевод запускается при сохранении' }
  }[section] || { label: '+ Создать запись', title: 'Создать новую запись как черновик' };
  if (addEntryBtn) {
    addEntryBtn.textContent = createAction.label;
    addEntryBtn.title = createAction.title;
  }
  const sourceLang = visualLangSelect.value || DEFAULT_LANGUAGE;
  const targetLangs = getTranslationLanguages(data).filter((lang) => lang !== sourceLang);
  if (languageSyncScope) {
    languageSyncScope.textContent = `${sourceLang} → ${targetLangs.length} языков · отдельно`;
    languageSyncScope.title = `Кнопка «Сохранить запись» сохраняет только ${sourceLang}. Для переводов нажмите «Синхронизировать».`;
  }

  if (saveEntryBtnText) {
    saveEntryBtnText.textContent = 'Сохранить запись';
    saveEntryBtn.title = `Сохранить только текущий язык (${sourceLang}) на VPS`;
  }

  const articles = Array.isArray(data.articles) ? data.articles : [];
  const selectedId = Number(visualEntrySelect.value);
  const selectedArticle = articles.find((article) => Number(article.id) === selectedId);
  const selectedEntries = getSectionArray(data, section, DEFAULT_LANGUAGE, false);
  const selectedEntry = selectedEntries.find((entry) => Number(entry.id) === selectedId);
  const selectedState = getPublicationState(data, section, selectedEntry);
  if (visualPublishBtn) visualPublishBtn.disabled = !selectedEntry || selectedState === 'live';
  if (visualDraftBtn) visualDraftBtn.disabled = !selectedEntry || selectedState === 'draft';
  if (visualHideBtn) visualHideBtn.disabled = !selectedEntry || selectedState === 'hidden';
  if (visualPublishBtn) visualPublishBtn.textContent = selectedState === 'hidden' ? 'Показать и опубликовать' : 'Опубликовать';
  const selectedCount = countArticleOriginals(selectedArticle);
  const totalCount = articles.reduce((sum, article) => sum + countArticleOriginals(article), 0);
  const canDownloadSelected = section === 'articles' && Boolean(selectedArticle) && selectedCount > 0;

  if (downloadOriginalsText) {
    downloadOriginalsText.textContent = canDownloadSelected
      ? `ZIP статьи · ${selectedCount}`
      : 'Выберите статью';
  }
  if (downloadAllOriginalsText) {
    downloadAllOriginalsText.textContent = `Все статьи · ${totalCount}`;
  }
  downloadOriginalsBtn.disabled = !canDownloadSelected;
  downloadAllOriginalsBtn.disabled = totalCount === 0;
  if (mediaExportMeta && mediaExportProgress?.hidden !== false) {
    mediaExportMeta.textContent = canDownloadSelected
      ? `#${selectedId}: ${selectedCount} ${pluralImages(selectedCount)} в исходном качестве`
      : `В архиве: ${articles.length} статей, ${totalCount} ${pluralImages(totalCount)}`;
  }
}

function setMediaExportProgress({ active, percent = null, label = '' }) {
  if (!mediaExportProgress || !mediaExportMeta) return;
  mediaExportProgress.hidden = !active;
  mediaExportProgress.classList.toggle('indeterminate', active && percent === null);
  mediaExportProgress.setAttribute('aria-hidden', active ? 'false' : 'true');
  const bar = mediaExportProgress.querySelector('span');
  if (bar) bar.style.width = percent === null ? '32%' : `${Math.max(0, Math.min(100, percent))}%`;
  if (label) mediaExportMeta.textContent = label;
}

function setLanguageSyncProgress({ active, percent = null, label = '' }) {
  if (!languageSyncProgress) return;
  languageSyncProgress.hidden = !active;
  languageSyncProgress.classList.toggle('indeterminate', active && percent === null);
  languageSyncProgress.setAttribute('aria-hidden', active ? 'false' : 'true');
  const bar = languageSyncProgress.querySelector('span');
  if (bar) bar.style.width = percent === null ? '32%' : `${Math.max(0, Math.min(100, percent))}%`;
  if (label && languageSyncScope) languageSyncScope.textContent = label;
}

async function responseBlobWithProgress(response) {
  const total = Number(response.headers.get('Content-Length')) || 0;
  if (!response.body || !total) return response.blob();

  const reader = response.body.getReader();
  const chunks = [];
  let received = 0;
  while (true) {
    const { done, value } = await reader.read();
    if (done) break;
    chunks.push(value);
    received += value.byteLength;
    const percent = Math.round((received / total) * 100);
    setMediaExportProgress({ active: true, percent, label: `Скачивание ZIP: ${percent}%` });
  }
  return new Blob(chunks, { type: response.headers.get('Content-Type') || 'application/zip' });
}

function filenameFromDisposition(header, fallback) {
  const raw = String(header || '');
  const utf = raw.match(/filename\*=UTF-8''([^;]+)/i);
  if (utf && utf[1]) {
    try { return decodeURIComponent(utf[1]); } catch {}
  }
  const plain = raw.match(/filename="([^"]+)"/i) || raw.match(/filename=([^;]+)/i);
  return plain && plain[1] ? plain[1].trim() : fallback;
}

async function downloadArticleOriginals(allArticles = false) {
  try {
    if (!allArticles && visualSectionSelect.value !== 'articles') {
      throw new Error('Оригиналы ZIP доступны для раздела «Статьи». Выберите статью в визуальном редакторе.');
    }
    const pw = getAdminPassword();
    if (!pw) throw new Error('Нет пароля редакции — войдите заново.');

    const selectedId = Number(visualEntrySelect.value);
    if (!allArticles && !selectedId) {
      throw new Error('Выберите статью для выгрузки оригиналов.');
    }

    setBusy(true);
    setStatus('info', allArticles
      ? 'Собираю ZIP со всеми оригинальными изображениями статей...'
      : `Собираю ZIP с оригиналами статьи #${selectedId}...`);
    setMediaExportProgress({
      active: true,
      percent: null,
      label: allArticles ? 'Сервер собирает общий ZIP…' : `Сервер собирает ZIP статьи #${selectedId}…`
    });

    const res = await fetch('https://api.eprisjournal.com/content/article-images', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'X-Admin-Password': pw },
      body: JSON.stringify(allArticles ? { all: true } : { id: selectedId })
    });

    if (!res.ok) {
      const err = await res.json().catch(() => ({}));
      throw new Error(err.error || `VPS вернул статус ${res.status}`);
    }

    const blob = await responseBlobWithProgress(res);
    const count = res.headers.get('X-EPRIS-Image-Count');
    const fileName = filenameFromDisposition(
      res.headers.get('Content-Disposition'),
      allArticles ? 'epris-all-article-originals.zip' : `epris-article-${selectedId}-originals.zip`
    );
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = fileName;
    document.body.appendChild(link);
    link.click();
    link.remove();
    window.setTimeout(() => URL.revokeObjectURL(url), 30000);

    setStatus('success', count
      ? `ZIP с оригиналами готов: ${count} ${pluralImages(Number(count))}.`
      : 'ZIP с оригиналами готов.');
    setMediaExportProgress({ active: true, percent: 100, label: `Готово: ${count || ''} ${count ? pluralImages(Number(count)) : 'файлов'} скачано` });
    showToast('success', 'Оригиналы изображений скачаны в ZIP.');
  } catch (error) {
    setStatus('error', getErrorMessage(error));
  } finally {
    setBusy(false);
    window.setTimeout(() => {
      setMediaExportProgress({ active: false });
      updateAdminToolbarContext();
    }, 1400);
  }
}

// Publishes the editor content to the VPS. The public site reads it live, so
// changes appear immediately — no GitHub commit, no Actions rebuild.
async function saveToGitHub() {
  const confirmed = await showConfirmModal(
    'Опубликовать изменения?',
    'Контент будет сохранён на <strong>VPS</strong> и сайт обновится <strong>сразу</strong> — без пересборки.',
    'Опубликовать'
  );
  if (!confirmed) return;
  await publishContentToVps();
}

/* The publish itself, without the confirmation dialog around it.
   Split out so an action that has ALREADY asked the editor — deleting a record,
   for one — can finish the job in the same click instead of leaving the change
   staged locally and announcing success. That gap is why drafts an editor
   deleted months ago were still live. */
/* ОДНА ОТПРАВКА КОНТЕНТА НА VPS. Вынесена, чтобы публикация могла случиться
   ДО автоперевода и, при необходимости, ещё раз после него. */
async function postContentToVps(payload, pw) {
  const res = await fetch(CONTENT_API, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', 'X-Admin-Password': pw },
    body: JSON.stringify(payload)
  });
  const data = await res.json().catch(() => ({}));
  if (!res.ok || !data.ok) throw new Error(data.error || ('VPS вернул статус ' + res.status));
  return data;
}

/* СНАЧАЛА СОХРАНИТЬ, ПОТОМ ПЕРЕВОДИТЬ.

   Здесь стояло наоборот: перед POST шёл ensureAllContentLanguages — полный
   обход всех статей, карточек, обзоров и библиотеки с достройкой недостающих
   языков через переводчик. Любой сбой на этом круге (исчерпанные квоты
   OpenRouter/DeepL, обрыв сети, «AI returned invalid JSON») выбрасывал
   исключение ДО единственного запроса, который что-то сохраняет. Внешне это
   выглядело так: редактор расставляет порядок статей, жмёт «Сохранить» — и на
   живом сайте не меняется ничего, потому что на сервер не ушло ничего.
   Проверено на живом контенте: в site-content.json нет даже ключа
   homepage.articleOrder, хотя порядок расставляли не раз.

   Порядок обратный: пароль, POST, и только потом достройка языков. Она может
   не получиться — тогда это предупреждение поверх уже сохранённого контента, а
   не потерянная работа. Созданные переводы уходят вторым POST, так что конечное
   состояние на сервере то же, что и раньше. */
async function publishContentToVps({ note = 'Публикую на VPS...' } = {}) {
  let parsed = null;
  let pw = '';
  try {
    setBusy(true);
    setStatus('info', note);

    parsed = parseEditorJson();
    saveSettings();

    pw = getAdminPassword();
    if (!pw) throw new Error('Нет пароля редакции — войдите заново.');

    const data = await postContentToVps(parsed, pw);

    currentSha = '';
    setLastSyncedSnapshotFromText(editor.value);
    localStorage.removeItem(DRAFT_KEY);
    lastSyncedTime = new Date();
    updateLastSyncedBadge();
    setStatus('success', 'Опубликовано на VPS — сайт обновлён мгновенно');
    // Server-side echo of the same "Локализация и главная" check (see
    // runLocalizationHealthCheck) — surfaced here too so a stub that just
    // went live is impossible to miss even by an editor who never opens
    // the Monitoring tab.
    if (Array.isArray(data.localizationWarnings) && data.localizationWarnings.length) {
      showToast?.('error', `После публикации: ${data.localizationWarnings.length} предупреждений по локализации. Смотрите вкладку «Мониторинг».`);
    }
  } catch (error) {
    setStatus('error', getErrorMessage(error));
    return;
  } finally {
    setBusy(false);
  }

  /* Обход языков идёт ПОСЛЕ сохранения и НЕ задерживает его: на десятке статей
     с семью языками он занимает минуты, а при исчерпанных квотах ещё и падает.
     Раньше редактор ждал всё это до записи, а при сбое не получал ничего. */
  syncLanguagesAfterPublish(parsed, pw);
}

/* Достройка недостающих переводов после уже состоявшейся публикации.
   Намеренно не await-ится: её сбой — это предупреждение, а не потеря правки,
   и панель не должна стоять занятой, пока переводчик перебирает записи. */
async function syncLanguagesAfterPublish(parsed, pw) {
  try {
    const syncSummary = await ensureAllContentLanguages(parsed, visualLangSelect.value || DEFAULT_LANGUAGE);
    const total = (syncSummary.created || 0) + (syncSummary.interfaceUpdated || 0);
    if (!total) {
      setStatus('success', 'Опубликовано на VPS — сайт обновлён мгновенно');
      return;
    }
    setEditorData(parsed);
    setStatus('info', `Достроено переводов: ${total}. Досохраняю...`);
    await postContentToVps(parsed, pw);
    setLastSyncedSnapshotFromText(editor.value);
    lastSyncedTime = new Date();
    updateLastSyncedBadge();
    /* Тексты секций считаются отдельно от записей: редактор должен видеть, что
       автоматически перевелось не только содержимое, но и подписи разделов. */
    const parts = [];
    if (syncSummary.created) parts.push(`записей: ${syncSummary.created}`);
    if (syncSummary.interfaceUpdated) parts.push(`текстов секций: ${syncSummary.interfaceUpdated}`);
    setStatus('success', `Опубликовано на VPS. Достроено переводов — ${parts.join(', ')}.`);
  } catch (error) {
    setStatus('success', 'Опубликовано на VPS. Автоперевод не отработал.');
    showToast?.('error', `Контент сохранён, но автоперевод не отработал: ${getErrorMessage(error)}. Переводы можно достроить на вкладке «Переводы».`);
  }
}

let statusCompactTimer = 0;
function setStatus(type, message, options = {}) {
  window.clearTimeout(statusCompactTimer);
  statusEl.className = 'status';

  if (type === 'error') {
    statusEl.classList.add('error');
  }

  if (type === 'success') {
    statusEl.classList.add('success');
  }

  if (type === 'info') {
    statusEl.classList.add('info');
  }

  statusEl.textContent = message;
  statusEl.title = message;
  statusEl.setAttribute('role', 'status');
  statusEl.setAttribute('aria-live', type === 'error' ? 'assertive' : 'polite');

  if (type === 'success' && options.sticky !== true) {
    statusCompactTimer = window.setTimeout(() => {
      statusEl.textContent = 'Синхронизировано';
      statusEl.title = message;
    }, 7000);
  }

  if ((type === 'error' || type === 'success') && !suppressLoginToasts) {
    showToast(type, message);
  }
}

// ===== TOAST NOTIFICATIONS =====
function showToast(type, text, duration = 4000) {
  const toast = document.createElement('div');
  toast.className = `toast toast-${type}`;
  const icons = { success: '\u2713', error: '\u2717', info: '\u2139' };
  toast.innerHTML = `<span class="toast-icon">${icons[type] || icons.info}</span><span class="toast-body">${escapeHtml(text)}</span><button class="toast-close" type="button">\u00D7</button><div class="toast-progress" style="animation-duration:${duration}ms"></div>`;
  toastContainerEl.appendChild(toast);
  const close = toast.querySelector('.toast-close');
  const dismiss = () => { toast.classList.add('removing'); setTimeout(() => toast.remove(), 260); };
  close.addEventListener('click', dismiss);
  setTimeout(dismiss, duration);
}

// Like showToast(), but with a clickable action button (e.g. "\u041E\u0442\u043C\u0435\u043D\u0438\u0442\u044C" after
// a delete). Additive \u2014 no existing showToast(type, text) call site changes.
function showToastWithAction(type, text, actionLabel, onAction, duration = 8000) {
  const toast = document.createElement('div');
  toast.className = `toast toast-${type}`;
  const icons = { success: '\u2713', error: '\u2717', info: '\u2139' };
  toast.innerHTML = `<span class="toast-icon">${icons[type] || icons.info}</span><span class="toast-body">${escapeHtml(text)}</span><button class="toast-action" type="button">${escapeHtml(actionLabel)}</button><button class="toast-close" type="button">\u00D7</button><div class="toast-progress" style="animation-duration:${duration}ms"></div>`;
  toastContainerEl.appendChild(toast);
  const dismiss = () => { toast.classList.add('removing'); setTimeout(() => toast.remove(), 260); };
  toast.querySelector('.toast-close').addEventListener('click', dismiss);
  toast.querySelector('.toast-action').addEventListener('click', () => { onAction(); dismiss(); });
  setTimeout(dismiss, duration);
}

// ===== LAST SYNCED BADGE =====
function updateLastSyncedBadge() {
  if (!lastSyncedTime) { lastSyncedEl.textContent = ''; return; }
  const dirty = isEditorDirty();
  const ago = formatTimeAgo(lastSyncedTime);
  lastSyncedEl.innerHTML = `<span class="last-synced-dot ${dirty ? 'dirty' : 'synced'}"></span>${ago}`;
}

function formatTimeAgo(date) {
  const s = Math.floor((Date.now() - date.getTime()) / 1000);
  if (s < 10) return '\u0442\u043e\u043b\u044c\u043a\u043e \u0447\u0442\u043e';
  if (s < 60) return `${s}\u0441 \u043d\u0430\u0437\u0430\u0434`;
  const m = Math.floor(s / 60);
  if (m < 60) return `${m}\u043c \u043d\u0430\u0437\u0430\u0434`;
  const h = Math.floor(m / 60);
  return `${h}\u0447 \u043d\u0430\u0437\u0430\u0434`;
}

setInterval(updateLastSyncedBadge, 15000);

// ===== SAVE CONFIRMATION MODAL =====
function showConfirmModal(title, bodyHtml, confirmLabel = '\u0414\u0430') {
  return new Promise((resolve) => {
    const overlay = document.createElement('div');
    overlay.className = 'modal-overlay';
    overlay.innerHTML = `<div class="modal-card"><h3 class="modal-title">${escapeHtml(title)}</h3><div class="modal-body">${bodyHtml}</div><div class="modal-actions"><button class="btn" type="button" data-action="cancel">\u041e\u0442\u043c\u0435\u043d\u0430</button><button class="btn btn-primary" type="button" data-action="confirm">${escapeHtml(confirmLabel)}</button></div></div>`;
    document.body.appendChild(overlay);
    const close = (result) => { overlay.classList.add('removing'); setTimeout(() => overlay.remove(), 200); resolve(result); };
    overlay.querySelector('[data-action="cancel"]').addEventListener('click', () => close(false));
    overlay.querySelector('[data-action="confirm"]').addEventListener('click', () => close(true));
    overlay.addEventListener('click', (e) => { if (e.target === overlay) close(false); });
  });
}

// ===== KEYBOARD SHORTCUTS PANEL =====
function showShortcutsPanel() {
  const existing = document.querySelector('.shortcuts-panel');
  if (existing) { existing.classList.add('removing'); setTimeout(() => existing.remove(), 200); return; }
  const shortcuts = [
    { keys: ['Ctrl', 'S'], desc: 'Сохранить на VPS' },
    { keys: ['Ctrl', 'Shift', 'L'], desc: 'Загрузить свежий контент' },
    { keys: ['Ctrl', 'Shift', 'F'], desc: '\u0424\u043e\u0440\u043c\u0430\u0442\u0438\u0440\u043e\u0432\u0430\u0442\u044c JSON' },
    { keys: ['?'], desc: '\u041f\u043e\u043a\u0430\u0437\u0430\u0442\u044c/\u0441\u043a\u0440\u044b\u0442\u044c \u044d\u0442\u0443 \u043f\u0430\u043d\u0435\u043b\u044c' }
  ];
  const rows = shortcuts.map(s => `<div class="shortcut-row"><span class="shortcut-desc">${escapeHtml(s.desc)}</span><span class="shortcut-keys">${s.keys.map(k => `<span class="shortcut-key">${k}</span>`).join('')}</span></div>`).join('');
  const panel = document.createElement('div');
  panel.className = 'shortcuts-panel';
  panel.innerHTML = `<div class="shortcuts-card"><div class="shortcuts-title">\u0413\u043e\u0440\u044f\u0447\u0438\u0435 \u043a\u043b\u0430\u0432\u0438\u0448\u0438<button class="shortcuts-close" type="button">\u00D7</button></div><div class="shortcuts-grid">${rows}</div></div>`;
  document.body.appendChild(panel);
  const close = () => { panel.classList.add('removing'); setTimeout(() => panel.remove(), 200); };
  panel.querySelector('.shortcuts-close').addEventListener('click', close);
  panel.addEventListener('click', (e) => { if (e.target === panel) close(); });
}

function getErrorMessage(error) {
  if (error instanceof Error && error.message) {
    return error.message;
  }

  return String(error);
}


/* ═══ АВТОСОХРАНЕНИЕ ═══════════════════════════════════════════════════════

   У Марии пропали карточки, потому что работа жила в одном месте — в черновике
   браузера — и одно нажатие его стёрло. Корзина черновиков закрыла тот случай,
   но остаётся весь класс потерь, где нажимать ничего не надо: закрытая вкладка,
   очищенный кэш, разряженный ноутбук, «сохраню потом».

   Автосохранение делает две разные вещи, и их важно не путать.

   ПЕРВОЕ работает всегда: раз в две минуты редактор кладёт снимок работы в
   историю браузера — десять последних версий, с отметкой времени. Это ничего
   не публикует и не может ничего испортить.

   ВТОРОЕ — отправка на VPS — выключено по умолчанию и включается галочкой.
   Причина проста: сохранение на сервер в этой админке означает публикацию,
   сайт обновляется мгновенно. Автоматически публиковать недописанное нельзя
   без ведома редактора, поэтому галочка честно называется «сразу на сайт». */
const AUTOSAVE_HISTORY_KEY = 'epris-admin-autosave-history-v1';
const AUTOSAVE_PREF_KEY = 'epris-admin-autosave-to-vps';
const AUTOSAVE_HISTORY_LIMIT = 10;
const AUTOSAVE_INTERVAL_MS = 2 * 60 * 1000;
let autosaveTimer = 0;
let autosaveInFlight = false;

function autosaveHistory() {
  try { return JSON.parse(localStorage.getItem(AUTOSAVE_HISTORY_KEY) || '[]'); } catch { return []; }
}

function pushAutosaveSnapshot() {
  try {
    const text = editor.value.trim();
    if (!text) return null;
    const history = autosaveHistory();
    if (history[0]?.draft === text) return null;   // ничего не изменилось
    history.unshift({ at: new Date().toISOString(), draft: text });
    /* История режется по количеству И по объёму: контент весит около двух
       мегабайт, десять копий переполнили бы хранилище браузера, и тогда мы
       потеряли бы даже обычный черновик. */
    let trimmed = history.slice(0, AUTOSAVE_HISTORY_LIMIT);
    while (trimmed.length > 1) {
      try {
        localStorage.setItem(AUTOSAVE_HISTORY_KEY, JSON.stringify(trimmed));
        return trimmed[0];
      } catch {
        trimmed = trimmed.slice(0, trimmed.length - 1);
      }
    }
    localStorage.setItem(AUTOSAVE_HISTORY_KEY, JSON.stringify(trimmed));
    return trimmed[0];
  } catch { return null; }
}

function setAutosaveNote(text, kind = 'muted') {
  const el = document.getElementById('autosave-status');
  if (!el) return;
  el.textContent = text;
  el.dataset.kind = kind;
}

function autosaveToVpsEnabled() {
  return localStorage.getItem(AUTOSAVE_PREF_KEY) === '1';
}

async function runAutosave() {
  if (autosaveInFlight) return;
  if (!editor || !editor.value.trim()) return;
  if (!isEditorDirty()) return;

  const snapshot = pushAutosaveSnapshot();
  const stamp = new Date().toLocaleTimeString('ru-RU', { hour: '2-digit', minute: '2-digit' });
  if (snapshot) setAutosaveNote(`Черновик сохранён в браузере · ${stamp}`);

  if (!autosaveToVpsEnabled()) return;
  const pw = getAdminPassword();
  if (!pw) { setAutosaveNote('Нет пароля редакции', 'warn'); return; }

  let parsed;
  // Незакрытая скобка в JSON — обычное состояние на середине правки. Молча
  // пропускаем такой круг: сообщать об ошибке каждые две минуты бессмысленно.
  try { parsed = parseEditorJson(); } catch { return; }

  autosaveInFlight = true;
  try {
    await postContentToVps(parsed, pw);
    setLastSyncedSnapshotFromText(editor.value);
    lastSyncedTime = new Date();
    updateLastSyncedBadge();
    setAutosaveNote(`Сохранено на сайте · ${stamp}`, 'ok');
  } catch (error) {
    // Автосохранение не имеет права перебивать ручную работу тревогой на весь
    // экран: пишем в строку статуса и пробуем на следующем круге.
    setAutosaveNote(`Не сохранилось: ${getErrorMessage(error)}`, 'warn');
  } finally {
    autosaveInFlight = false;
  }
}

function startAutosave() {
  clearInterval(autosaveTimer);
  autosaveTimer = setInterval(runAutosave, AUTOSAVE_INTERVAL_MS);
  /* Снимок при уходе со страницы — самый ценный из всех: именно на закрытии
     вкладки теряется работа, которую «сохраню потом». */
  window.addEventListener('beforeunload', () => { try { pushAutosaveSnapshot(); } catch {} });
  document.addEventListener('visibilitychange', () => {
    if (document.visibilityState === 'hidden') { try { pushAutosaveSnapshot(); } catch {} }
  });
}

function restoreAutosaveSnapshot(index = 0) {
  const entry = autosaveHistory()[index];
  if (!entry) { showToast('error', 'Автоснимков пока нет.'); return false; }
  try {
    stashDraftBeforeReplace('возврат автоснимка');
    setEditorData(JSON.parse(entry.draft), { markSynced: false, clearDraft: false });
    showToast('success', `Восстановлен автоснимок от ${new Date(entry.at).toLocaleString('ru-RU')}.`);
    return true;
  } catch (error) {
    showToast('error', `Автоснимок повреждён: ${error.message}`);
    return false;
  }
}
window.autosaveHistory = autosaveHistory;
window.restoreAutosaveSnapshot = restoreAutosaveSnapshot;
// Наружу — чтобы автоснимок можно было снять вручную и проверить работу.
window.pushAutosaveSnapshot = pushAutosaveSnapshot;
window.runAutosave = runAutosave;

/* Список автоснимков — простым диалогом выбора: отдельный экран ради десяти
   строк со временем не окупается, а выбрать нужный момент надо. */
function openAutosaveHistory() {
  const history = autosaveHistory();
  if (!history.length) { showToast('info', 'Автоснимков пока нет — первый появится через две минуты работы.'); return; }
  const lines = history.map((entry, index) => `${index + 1}. ${new Date(entry.at).toLocaleString('ru-RU')}`).join('\n');
  const answer = window.prompt(`Автоснимки редактора:\n${lines}\n\nНомер снимка для восстановления (текущее состояние уйдёт в корзину черновиков):`, '1');
  if (!answer) return;
  const index = Number(answer) - 1;
  if (!Number.isInteger(index) || index < 0 || index >= history.length) { showToast('error', 'Нет снимка с таким номером.'); return; }
  restoreAutosaveSnapshot(index);
}

function refreshAutosaveHistoryButton() {
  const button = document.getElementById('autosaveHistoryBtn');
  if (!button) return;
  const history = autosaveHistory();
  button.hidden = !history.length;
  if (history.length) button.title = `Последний снимок: ${new Date(history[0].at).toLocaleString('ru-RU')} · всего ${history.length}`;
}

document.addEventListener('DOMContentLoaded', () => {
  document.getElementById('autosaveHistoryBtn')?.addEventListener('click', openAutosaveHistory);
  refreshAutosaveHistoryButton();
  const toggle = document.getElementById('autosaveVpsToggle');
  if (toggle) {
    toggle.checked = autosaveToVpsEnabled();
    toggle.addEventListener('change', () => {
      localStorage.setItem(AUTOSAVE_PREF_KEY, toggle.checked ? '1' : '0');
      setAutosaveNote(toggle.checked
        ? 'Правки уходят на сайт каждые 2 минуты'
        : 'Снимки в браузере каждые 2 минуты');
    });
  }
  setAutosaveNote(autosaveToVpsEnabled()
    ? 'Правки уходят на сайт каждые 2 минуты'
    : 'Снимки в браузере каждые 2 минуты');
  startAutosave();
});

/* КОРЗИНА ЧЕРНОВИКА.

   Кнопка «Загрузить свежую версию VPS» стирала локальный черновик начисто:
   редактор делал карточки галереи, видел «на VPS более свежая версия»,
   нажимал — и работа исчезала без следа и без возврата. Ровно это и
   случилось у Марии.

   Теперь перед любой заменой черновик кладётся в корзину: последние пять
   снимков с отметкой времени. Из них можно вернуть работу, пока браузер не
   очистили. Это не отменяет главного правила — сохранять на VPS, — но
   перестаёт наказывать за одно нажатие. */
const DRAFT_TRASH_KEY = 'epris-admin-draft-trash-v1';
const DRAFT_TRASH_LIMIT = 5;

function stashDraftBeforeReplace(reason) {
  try {
    const draft = localStorage.getItem(DRAFT_KEY);
    if (!draft) return;
    // Одинаковый снимок дважды подряд не нужен: чаще всего это повторное
    // нажатие той же кнопки.
    const trash = JSON.parse(localStorage.getItem(DRAFT_TRASH_KEY) || '[]');
    if (trash[0]?.draft === draft) return;
    trash.unshift({ at: new Date().toISOString(), reason: String(reason || ''), draft });
    localStorage.setItem(DRAFT_TRASH_KEY, JSON.stringify(trash.slice(0, DRAFT_TRASH_LIMIT)));
  } catch { /* приватный режим или нет места — не мешаем работе */ }
}

function listDraftTrash() {
  try { return JSON.parse(localStorage.getItem(DRAFT_TRASH_KEY) || '[]'); } catch { return []; }
}

function restoreDraftFromTrash(index = 0) {
  const entry = listDraftTrash()[index];
  if (!entry) { showToast('error', 'Резервных черновиков нет.'); return false; }
  try {
    const data = JSON.parse(entry.draft);
    // Возврат сам по себе тоже замена: текущее состояние уходит в корзину.
    setEditorData(data, { markSynced: false, clearDraft: false });
    showToast('success', `Черновик от ${new Date(entry.at).toLocaleString('ru-RU')} восстановлен. Проверьте и сохраните на VPS.`);
    return true;
  } catch (error) {
    showToast('error', `Не удалось разобрать резервный черновик: ${error.message}`);
    return false;
  }
}
window.restoreDraftFromTrash = restoreDraftFromTrash;
window.listDraftTrash = listDraftTrash;

/* Кнопка возврата видна только когда есть что возвращать, и говорит, за какое
   время черновик: «вернуть» вслепую страшнее, чем не возвращать. */
function refreshDraftTrashButton() {
  const button = document.getElementById('draftTrashBtn');
  if (!button) return;
  const trash = listDraftTrash();
  button.hidden = !trash.length;
  if (trash.length) {
    const when = new Date(trash[0].at);
    button.title = `Черновик от ${when.toLocaleString('ru-RU')} · ${trash[0].reason || 'замена черновика'}`;
  }
}
window.refreshDraftTrashButton = refreshDraftTrashButton;

document.addEventListener('DOMContentLoaded', () => {
  refreshDraftTrashButton();
  document.getElementById('draftTrashBtn')?.addEventListener('click', () => {
    const trash = listDraftTrash();
    if (!trash.length) return;
    const when = new Date(trash[0].at).toLocaleString('ru-RU');
    if (!window.confirm(`Вернуть черновик от ${when}?\n\nТекущее содержимое редактора тоже уйдёт в корзину черновиков.`)) return;
    stashDraftBeforeReplace('возврат черновика из корзины');
    restoreDraftFromTrash(0);
    refreshDraftTrashButton();
  });
});

function setEditorData(data, options = {}) {
  const { markSynced = false, clearDraft = false } = options;
  if (clearDraft) {
    stashDraftBeforeReplace(options.reason || 'замена черновика версией VPS');
    setTimeout(() => { try { refreshDraftTrashButton(); } catch {} }, 0);
  }
  editor.value = JSON.stringify(data, null, 2);
  updateStats(data);
  refreshVisualEditor();
  updateEditorState();
  setTimeout(() => { try { renderDashboard(); } catch {} }, 100);
  if (markSynced) {
    setLastSyncedSnapshotFromText(editor.value);
  }
  if (clearDraft) {
    localStorage.removeItem(DRAFT_KEY);
  } else {
    saveDraft();
  }
  saveSettings();
  queueMonitoringChecks(120);
  // Auto-update polls when data changes
  if (typeof renderPollResults === 'function') {
    try { renderPollResults(); } catch {}
  }
  try { window._renderVisibility?.(); } catch {}
  try { window._renderHomepageTab?.(); } catch {}
  // Re-seed Issue Builder + Translations from freshly loaded content
  if (typeof renderIssuesTab === 'function' && document.getElementById('issueArticlesList')) {
    _issues = null; // force resync of issue archive from reloaded content
    try { renderIssuesTab(); } catch {}
  }
  if (typeof renderTranslationsTab === 'function' && document.getElementById('translBody')) {
    try { renderTranslationsTab(); } catch {}
  }
}

function deepClone(value) {
  return JSON.parse(JSON.stringify(value));
}

function getVisualData() {
  const parsed = parseEditorJsonSafe();
  if (!parsed) {
    setVisualNotice('JSON сейчас некорректный. Исправьте его, чтобы открыть визуальный редактор.', 'error');
    visualFormEl.innerHTML = '';
    visualEntrySelect.innerHTML = '';
    renderCreatorQuality(null);
    renderContentCommand(null);
    return null;
  }

  return parsed;
}

function getLanguageOptions(data) {
  const set = new Set([DEFAULT_LANGUAGE]);

  if (data.translations && typeof data.translations === 'object') {
    for (const lang of Object.keys(data.translations)) {
      set.add(lang);
    }
  }

  if (data.localizedCollections && typeof data.localizedCollections === 'object') {
    for (const lang of Object.keys(data.localizedCollections)) {
      set.add(lang);
    }
  }

  return [DEFAULT_LANGUAGE, ...Array.from(set).filter((lang) => lang !== DEFAULT_LANGUAGE)];
}

function ensureArray(root, key) {
  if (!Array.isArray(root[key])) {
    root[key] = [];
  }
  return root[key];
}

function getSectionArray(data, section, lang, createLocalized) {
  if (lang === DEFAULT_LANGUAGE) {
    return ensureArray(data, section);
  }

  if (!data.localizedCollections || typeof data.localizedCollections !== 'object' || Array.isArray(data.localizedCollections)) {
    if (!createLocalized) {
      return Array.isArray(data[section]) ? data[section] : [];
    }
    data.localizedCollections = {};
  }

  if (!data.localizedCollections[lang]) {
    if (!createLocalized) {
      return Array.isArray(data[section]) ? data[section] : [];
    }
    data.localizedCollections[lang] = {};
  }

  const bucket = data.localizedCollections[lang];

  if (!Array.isArray(bucket[section])) {
    if (!createLocalized) {
      return Array.isArray(data[section]) ? data[section] : [];
    }
    bucket[section] = deepClone(Array.isArray(data[section]) ? data[section] : []);
  }

  return bucket[section];
}

function getSectionLabel(section) {
  return SECTION_CONFIG[section]?.label || section;
}

function getEntryTitle(section, entry) {
  if (!entry || typeof entry !== 'object') {
    return 'Без названия';
  }

  const titleField = SECTION_CONFIG[section]?.titleField;
  if (titleField && entry[titleField]) {
    return entry[titleField];
  }

  return `ID ${entry.id || '-'}`;
}

// One status vocabulary for the editor, visibility registry and public site.
// A manual visibility switch is intentionally separate from `draft`: editors
// can hide a live article without losing its publication state, then restore
// it with one click. Scheduled entries stay hidden until their timestamp.
function getPublicationState(data, section, entry) {
  if (!entry || typeof entry !== 'object') return 'draft';
  if (entry.draft) return 'draft';
  const publishAt = entry.publishAt ? Date.parse(entry.publishAt) : NaN;
  if (Number.isFinite(publishAt) && publishAt > Date.now()) return 'scheduled';
  if (data?.visibility?.entities?.[section]?.[String(entry.id)] === false) return 'hidden';
  return 'live';
}

function publicationStateLabel(state) {
  return {
    live: 'Опубликовано',
    draft: 'Черновик',
    scheduled: 'Отложено',
    hidden: 'Скрыто'
  }[state] || 'Черновик';
}

function publicationStateIcon(state) {
  return { live: '●', draft: '✎', scheduled: '◷', hidden: '⊘' }[state] || '✎';
}

function publicationTimestamp(entry) {
  const values = [entry?.updatedAt, entry?.publishAt, entry?.date];
  for (const value of values) {
    const stamp = value ? Date.parse(value) : NaN;
    if (Number.isFinite(stamp)) return stamp;
  }
  return 0;
}

function renderPublicationSummary(data, section) {
  if (!visualPublicationSummary) return;
  const entries = getSectionArray(data, section, DEFAULT_LANGUAGE, false);
  const counts = entries.reduce((result, entry) => {
    const state = getPublicationState(data, section, entry);
    result[state] = (result[state] || 0) + 1;
    return result;
  }, { live: 0, draft: 0, scheduled: 0, hidden: 0 });
  visualPublicationSummary.innerHTML = `<strong>${entries.length}</strong> записей · <span>${publicationStateIcon('live')} ${counts.live} опубликовано</span> · <span>${publicationStateIcon('draft')} ${counts.draft} черновиков</span> · <span>${publicationStateIcon('scheduled')} ${counts.scheduled} отложено</span> · <span>${publicationStateIcon('hidden')} ${counts.hidden} скрыто</span>`;
}

async function updateSelectedPublicationState(nextState) {
  const data = parseEditorJsonSafe();
  if (!data) { setStatus('error', 'Сначала загрузите корректный контент.'); return; }
  const section = visualSectionSelect.value;
  const selectedId = Number(visualEntrySelect.value);
  const entries = getSectionArray(data, section, DEFAULT_LANGUAGE, false);
  const entry = entries.find((item) => Number(item.id) === selectedId);
  if (!entry) { setStatus('error', 'Выберите запись.'); return; }

  if (!data.visibility || typeof data.visibility !== 'object' || Array.isArray(data.visibility)) data.visibility = {};
  if (!data.visibility.entities || typeof data.visibility.entities !== 'object' || Array.isArray(data.visibility.entities)) data.visibility.entities = {};
  if (!data.visibility.entities[section] || typeof data.visibility.entities[section] !== 'object' || Array.isArray(data.visibility.entities[section])) data.visibility.entities[section] = {};

  if (nextState === 'live') {
    delete entry.draft;
    // A past timestamp is the durable editorial confirmation that this entry
    // was deliberately published. It is also used by the public site to
    // distinguish a consciously published fresh draft from an abandoned
    // blueprint with the default title.
    entry.publishAt = new Date().toISOString();
    data.visibility.entities[section][String(entry.id)] = true;
  } else if (nextState === 'draft') {
    entry.draft = true;
    delete entry.publishAt;
    data.visibility.entities[section][String(entry.id)] = true;
  } else if (nextState === 'hidden') {
    delete entry.draft;
    data.visibility.entities[section][String(entry.id)] = false;
  }

  try {
    setBusy(true);
    // Publication controls are destructive to visibility if they only mutate
    // the local JSON. Persist the canonical entity immediately for the two
    // states that readers can see, so «Опубликовать» cannot leave a draft on
    // the VPS (the old flow required a second, easy-to-miss save click).
    if (nextState === 'live' || nextState === 'draft') {
      await saveEntityToServer(section, DEFAULT_LANGUAGE, entry);
      setEditorData(data, { markSynced: true });
    } else {
      setEditorData(data);
    }
    pendingVisualEntryId = selectedId;
    refreshVisualEditor();
    const persisted = nextState === 'live' || nextState === 'draft';
    setStatus('success', `Статус «${getEntryTitle(section, entry)}» изменён на «${publicationStateLabel(nextState)}».${persisted ? ' Изменения сразу отправлены на VPS.' : ' Нажмите «Сохранить запись», чтобы отправить изменение на VPS.'}`, { sticky: true });
  } catch (error) {
    setStatus('error', `Статус не сохранён на VPS: ${getErrorMessage(error)}`);
  } finally {
    setBusy(false);
  }
}

