function renderCreatorQuality(data, section, lang, entry) {
  if (!creatorQualityEl) {
    return;
  }

  if (!data || !entry) {
    creatorQualityEl.innerHTML = '<span class="quality-chip warn">Нет записи</span>';
    return;
  }

  const chips = [];
  const addChip = (label, ok, danger = false) => {
    chips.push({
      label,
      state: ok ? 'ok' : (danger ? 'danger' : 'warn')
    });
  };

  const languages = getTranslationLanguages(data);
  const entryId = Number(entry.id);
  const concreteLangs = languages.filter((language) => hasConcreteEntryForLanguage(data, section, language, entryId));

  addChip(entry.title ? 'Заголовок' : 'Нет заголовка', Boolean(entry.title), true);
  addChip(`${concreteLangs.length}/${languages.length} языков`, languages.length > 0 && concreteLangs.length === languages.length, true);

  if (section === 'articles') {
    const blocks = Array.isArray(entry.content) ? entry.content : [];
    const hasMedia = Boolean(entry.imageUrl || entry.imageSeed) || blocks.some((block) => ['image', 'gallery'].includes(block?.type));
    const hasPoll = blocks.some((block) => {
      const options = block?.content?.options;
      return block?.type === 'poll' && block.content?.question && Array.isArray(options) && options.length >= 2;
    });
    const words = blocks.reduce((sum, block) => {
      if (['text', 'quote', 'note'].includes(block?.type) && typeof block.content === 'string') {
        return sum + countWords(block.content);
      }
      return sum;
    }, 0);

    addChip(entry.excerpt ? 'Лид' : 'Нет лида', Boolean(entry.excerpt));
    addChip(hasMedia ? 'Обложка' : 'Нет фото', hasMedia);
    addChip(`${blocks.length} блоков`, blocks.length >= 3);
    addChip(`${words} слов`, words >= 80);
    if (words > 0) addChip(`~${Math.max(1, Math.round(words / 200))} мин чтения`, true);
    addChip(Array.isArray(entry.tags) && entry.tags.length ? 'Теги' : 'Нет тегов', Array.isArray(entry.tags) && entry.tags.length);
    addChip(hasPoll ? 'Опрос' : 'Нет опроса', hasPoll);
  } else if (section === 'items') {
    addChip(entry.description ? 'Описание' : 'Нет описания', Boolean(entry.description));
    addChip(entry.imageUrl || entry.imageSeed ? 'Фото' : 'Нет фото', Boolean(entry.imageUrl || entry.imageSeed));
  } else if (section === 'reviews') {
    addChip(entry.content ? 'Текст' : 'Нет текста', Boolean(entry.content));
  } else if (section === 'libraryItems') {
    addChip(entry.type ? 'Тип' : 'Нет типа', Boolean(entry.type));
    addChip(entry.year ? 'Год' : 'Нет года', Boolean(entry.year));
  }

  creatorQualityEl.innerHTML = chips
    .map((chip) => `<span class="quality-chip ${chip.state}">${escapeHtml(chip.label)}</span>`)
    .join('');
}

function getEntryWordCount(section, entry) {
  if (!entry || typeof entry !== 'object') {
    return 0;
  }

  if (section === 'articles') {
    const blocks = Array.isArray(entry.content) ? entry.content : [];
    const blockWords = blocks.reduce((sum, block) => {
      if (['text', 'quote', 'note'].includes(block?.type) && typeof block.content === 'string') {
        return sum + countWords(block.content);
      }
      return sum;
    }, 0);
    return blockWords + countWords(entry.excerpt || '');
  }

  if (section === 'items') {
    return countWords(`${entry.subtitle || ''} ${entry.description || ''}`);
  }

  if (section === 'reviews') {
    return countWords(`${entry.subject || ''} ${entry.content || ''}`);
  }

  return countWords(`${entry.title || ''} ${entry.type || ''} ${entry.year || ''}`);
}

function entryHasMedia(section, entry) {
  if (!entry || typeof entry !== 'object') {
    return false;
  }

  if (section !== 'articles' && section !== 'items') {
    return true;
  }

  if (entry.imageUrl || entry.imageSeed) {
    return true;
  }

  const blocks = Array.isArray(entry.content) ? entry.content : [];
  return blocks.some((block) => {
    if (block?.type === 'image') {
      return Boolean(block.content);
    }
    if (block?.type === 'gallery') {
      return Array.isArray(block.content) && block.content.length > 0;
    }
    return false;
  });
}

function entryHasPoll(section, entry) {
  if (section !== 'articles') {
    return true;
  }

  const blocks = Array.isArray(entry?.content) ? entry.content : [];
  return blocks.some((block) => {
    const options = block?.content?.options;
    return block?.type === 'poll' && Boolean(block.content?.question) && Array.isArray(options) && options.length >= 2;
  });
}

function entryIsThin(section, entry) {
  if (!entry || typeof entry !== 'object') {
    return true;
  }

  if (!entry.title) {
    return true;
  }

  const words = getEntryWordCount(section, entry);
  if (section === 'articles') {
    const blocks = Array.isArray(entry.content) ? entry.content : [];
    return !entry.excerpt || blocks.length < 3 || words < 80;
  }

  if (section === 'items') {
    return !entry.description || words < 18;
  }

  if (section === 'reviews') {
    return !entry.content || words < 25;
  }

  return !entry.type || !entry.year;
}

function getAuditEntry(data, section, preferredLang, entryId) {
  try {
    return requireSourceEntry(data, section, preferredLang, entryId);
  } catch {
    for (const lang of getTranslationLanguages(data)) {
      const entry = findEntryInLanguage(data, section, lang, entryId);
      if (entry) {
        return { entry, lang };
      }
    }
  }

  return null;
}

function buildSectionAudit(data, section, preferredLang = DEFAULT_LANGUAGE) {
  const languages = getTranslationLanguages(data);
  const ids = getConcreteEntryIds(data, section).sort((a, b) => a - b);
  const audit = {
    total: ids.length,
    languages,
    completeLangEntries: 0,
    missingPairs: 0,
    missingLangItems: [],
    noPhoto: [],
    noPoll: [],
    thinText: []
  };

  for (const id of ids) {
    const missingLangs = languages.filter((lang) => !hasConcreteEntryForLanguage(data, section, lang, id));
    if (missingLangs.length) {
      audit.missingPairs += missingLangs.length;
      audit.missingLangItems.push({ id, lang: missingLangs[0], missingLangs });
    } else {
      audit.completeLangEntries += 1;
    }

    const source = getAuditEntry(data, section, preferredLang, id);
    if (!source) {
      continue;
    }

    if (!entryHasMedia(section, source.entry)) {
      audit.noPhoto.push({ id, lang: source.lang });
    }

    if (!entryHasPoll(section, source.entry)) {
      audit.noPoll.push({ id, lang: source.lang });
    }

    if (entryIsThin(section, source.entry)) {
      audit.thinText.push({ id, lang: source.lang });
    }
  }

  return audit;
}

function renderAuditMetric(label, value, state) {
  return `
    <div class="audit-metric ${state || ''}">
      <span>${escapeHtml(label)}</span>
      <strong>${escapeHtml(value)}</strong>
    </div>
  `;
}

function setIssueButton(button, label, count) {
  button.textContent = count ? `${label} (${count})` : label;
  button.disabled = count === 0;
}

function getPreviewMeta(section, entry) {
  if (section === 'articles') {
    return [entry.category, entry.subcategory, entry.date].filter(Boolean).join(' · ');
  }
  if (section === 'items') {
    return [entry.fig, entry.subtitle].filter(Boolean).join(' · ');
  }
  if (section === 'reviews') {
    return [entry.subject, entry.category].filter(Boolean).join(' · ');
  }
  return [entry.type, entry.size, entry.year].filter(Boolean).join(' · ');
}

function truncateText(value, maxLength = 180) {
  const text = String(value || '').replace(/\s+/g, ' ').trim();
  if (text.length <= maxLength) {
    return text;
  }
  return `${text.slice(0, maxLength - 1).trim()}...`;
}

const EXCERPT_PREVIEW_LIMIT = 220; // matches truncateText(excerpt, 220) in renderEntryPreview
function excerptCountHtml(text) {
  const len = String(text || '').length;
  const over = len > EXCERPT_PREVIEW_LIMIT;
  return `<span class="${over ? 'is-over' : ''}">${len} / ${EXCERPT_PREVIEW_LIMIT}</span>${over ? ' — обрежется на карточках сайта' : ''}`;
}

function renderEntryPreview(data, section, lang, entry) {
  if (!entry) {
    return `
      <div class="preview-empty-state">
        <p class="panel-kicker">Предпросмотр</p>
        <h3>Запись не выбрана</h3>
      </div>
    `;
  }

  const title = getEntryTitle(section, entry);
  const imageSource = section === 'articles' || section === 'items'
    ? resolvePreviewImageSource(entry.imageUrl, entry.imageSeed)
    : '';
  const words = getEntryWordCount(section, entry);
  const languages = getTranslationLanguages(data);
  const concreteLangs = languages.filter((language) => hasConcreteEntryForLanguage(data, section, language, entry.id));
  const meta = getPreviewMeta(section, entry);
  const excerpt = section === 'articles'
    ? entry.excerpt
    : section === 'items'
      ? entry.description
      : section === 'reviews'
        ? entry.content
        : `${entry.type || ''} ${entry.size || ''} ${entry.year || ''}`;
  const blocks = Array.isArray(entry.content) ? entry.content : [];
  const tags = Array.isArray(entry.tags) ? entry.tags.slice(0, 5) : [];

  return `
    <div class="preview-head">
      <div>
        <p class="panel-kicker">Предпросмотр</p>
        <h3>${escapeHtml(title)}</h3>
      </div>
      <span class="preview-id">#${escapeHtml(entry.id)} · ${escapeHtml(lang)}</span>
    </div>
    ${imageSource
      ? `<img class="preview-image" src="${escapeHtml(imageSource)}" alt="" loading="lazy" referrerpolicy="no-referrer" />`
      : '<div class="preview-image-empty">Нет обложки</div>'
    }
    <p class="preview-meta">${escapeHtml(meta || getSectionLabel(section))}</p>
    <p class="preview-excerpt">${escapeHtml(truncateText(excerpt, 220) || 'Текст пока пустой.')}</p>
    <div class="preview-pills">
      <span>${escapeHtml(String(words))} слов</span>
      <span>${escapeHtml(String(concreteLangs.length))}/${escapeHtml(String(languages.length))} языков</span>
      ${section === 'articles' ? `<span>${escapeHtml(String(blocks.length))} блоков</span>` : ''}
    </div>
    ${tags.length
      ? `<div class="preview-tags">${tags.map((tag) => `<span>${escapeHtml(tag)}</span>`).join('')}</div>`
      : ''
    }
  `;
}

function renderContentCommand(data, section = visualSectionSelect.value, lang = visualLangSelect.value || DEFAULT_LANGUAGE, entry = null) {
  if (!contentAuditMetricsEl || !entryPreviewEl) {
    return;
  }

  if (!data) {
    contentAuditMetricsEl.innerHTML = renderAuditMetric('JSON', 'не загружен', 'warn');
    entryPreviewEl.innerHTML = renderEntryPreview({ translations: {} }, section, lang, null);
    [findMissingLangBtn, findNoPhotoBtn, findNoPollBtn, findThinTextBtn].forEach((button) => { button.disabled = true; });
    return;
  }

  const audit = buildSectionAudit(data, section, lang);
  const completeState = audit.total && audit.completeLangEntries === audit.total ? 'ok' : 'warn';
  const missingState = audit.missingPairs ? 'danger' : 'ok';
  const weakState = audit.thinText.length ? 'warn' : 'ok';
  const metrics = [
    renderAuditMetric('Записей', String(audit.total), audit.total ? 'ok' : 'warn'),
    renderAuditMetric('7 языков', `${audit.completeLangEntries}/${audit.total}`, completeState),
    renderAuditMetric('Пропусков языка', String(audit.missingPairs), missingState),
    renderAuditMetric(section === 'articles' || section === 'items' ? 'Без фото' : 'Медиа', String(audit.noPhoto.length), audit.noPhoto.length ? 'warn' : 'ok'),
    renderAuditMetric(section === 'articles' ? 'Без опроса' : 'Опросы', String(audit.noPoll.length), audit.noPoll.length ? 'warn' : 'ok'),
    renderAuditMetric('Слабый текст', String(audit.thinText.length), weakState)
  ];
  if (section === 'articles') {
    if (_viewsMap) {
      const total = Object.values(_viewsMap).reduce((s, n) => s + (Number(n) || 0), 0);
      metrics.push(renderAuditMetric('Просмотров всего', String(total), 'ok'));
    } else {
      // First render before the counters arrive — refresh this panel once loaded.
      fetchViewsMap().then(() => renderContentCommand(data, section, lang, entry));
    }
  }

  contentAuditMetricsEl.innerHTML = metrics.join('');
  setIssueButton(findMissingLangBtn, 'Нет языка', audit.missingLangItems.length);
  setIssueButton(findNoPhotoBtn, 'Нет фото', audit.noPhoto.length);
  setIssueButton(findNoPollBtn, 'Нет опроса', audit.noPoll.length);
  setIssueButton(findThinTextBtn, 'Слабый текст', audit.thinText.length);
  entryPreviewEl.innerHTML = renderEntryPreview(data, section, lang, entry);
}

function getFirstIssueTarget(audit, issueType) {
  if (issueType === 'missingLang') {
    return audit.missingLangItems[0] || null;
  }
  if (issueType === 'noPhoto') {
    return audit.noPhoto[0] || null;
  }
  if (issueType === 'noPoll') {
    return audit.noPoll[0] || null;
  }
  if (issueType === 'thinText') {
    return audit.thinText[0] || null;
  }
  return null;
}

function getIssueLabel(issueType) {
  if (issueType === 'missingLang') return 'пропуск языка';
  if (issueType === 'noPhoto') return 'нет фото';
  if (issueType === 'noPoll') return 'нет опроса';
  if (issueType === 'thinText') return 'слабый текст';
  return 'задача';
}

function selectFirstIssueEntry(issueType) {
  try {
    const data = parseEditorJson();
    const section = visualSectionSelect.value;
    const currentLang = visualLangSelect.value || DEFAULT_LANGUAGE;
    const audit = buildSectionAudit(data, section, currentLang);
    const target = getFirstIssueTarget(audit, issueType);

    if (!target) {
      setStatus('success', `В разделе «${getSectionLabel(section)}» нет проблемы: ${getIssueLabel(issueType)}.`);
      return;
    }

    visualSearchInput.value = '';
    if (target.lang) {
      visualLangSelect.value = target.lang;
    }
    pendingVisualEntryId = target.id;
    refreshVisualEditor();
    setStatus('info', `Открыта запись #${target.id}: ${getIssueLabel(issueType)}.`);
  } catch (error) {
    setStatus('error', getErrorMessage(error));
  }
}

function buildQualityEntryFromForm(section, fallback = {}) {
  const base = { ...fallback, id: Number(visualEntrySelect.value) || fallback.id };

  if (section === 'items') {
    return {
      ...base,
      title: getFieldValue('vf-title').trim(),
      description: getFieldValue('vf-description').trim(),
      imageSeed: getFieldValue('vf-imageSeed').trim(),
      imageUrl: getFieldValue('vf-imageUrl').trim()
    };
  }

  if (section === 'reviews') {
    return {
      ...base,
      title: getFieldValue('vf-title').trim()
      // NOTE: content is managed by the WYSIWYG review canvas, not the classic form
    };
  }

  if (section === 'libraryItems') {
    return {
      ...base,
      title: getFieldValue('vf-title').trim(),
      type: getFieldValue('vf-type').trim(),
      size: getFieldValue('vf-size').trim(),
      url: getFieldValue('vf-url').trim(),
      year: getFieldValue('vf-year').trim()
    };
  }

  return {
    ...base,
    title: getFieldValue('vf-title').trim(),
    excerpt: getFieldValue('vf-excerpt').trim(),
    tags: getFieldValue('vf-tags').split(',').map((tag) => tag.trim()).filter(Boolean),
    imageSeed: getFieldValue('vf-imageSeed').trim(),
    imageUrl: getFieldValue('vf-imageUrl').trim(),
    content: collectBlockEditorContent()
  };
}

function refreshCreatorQualityFromForm(fallback = {}) {
  const data = getVisualData();
  if (!data) {
    return;
  }

  const section = visualSectionSelect.value;
  const lang = visualLangSelect.value || DEFAULT_LANGUAGE;
  const entry = buildQualityEntryFromForm(section, fallback);
  renderCreatorQuality(data, section, lang, entry);
  renderContentCommand(data, section, lang, entry);
}

function bindCreatorQualityInputs(fallback = {}) {
  visualFormEl.querySelectorAll('input, textarea, select').forEach((field) => {
    field.addEventListener('input', () => {
      refreshCreatorQualityFromForm(fallback);
      if (typeof scheduleVisualAutoSync === 'function') scheduleVisualAutoSync();
    });
    field.addEventListener('change', () => {
      refreshCreatorQualityFromForm(fallback);
      if (typeof scheduleVisualAutoSync === 'function') scheduleVisualAutoSync();
    });
  });
}

// Every new record is born in the EN collection first. EN is the canonical
// source used by the public site, the localisation audit and the translation
// pass; creating only inside the currently open language used to leave a
// record that disappeared as soon as the editor reloaded its source list.
// Translation is deliberately a separate, explicit action. Creating empty
// language copies made the interface claim that a record already existed in
// seven languages, even though only the English draft had been saved. It also
// let a stale localized list win over the new canonical record on reload.
function stageCanonicalDraft(data, section, entry) {
  const canonical = getSectionArray(data, section, DEFAULT_LANGUAGE, false);
  if (canonical.some((item) => Number(item.id) === Number(entry.id))) {
    throw new Error(`Запись #${entry.id} уже существует.`);
  }

  const draft = { ...entry, draft: true, updatedAt: new Date().toISOString() };
  canonical.push(draft);

  // A new draft must never be hidden by the previous search/status filter.
  visualSectionSelect.value = section;
  visualLangSelect.value = DEFAULT_LANGUAGE;
  if (visualSearchInput) visualSearchInput.value = '';
  if (visualStatusFilter) visualStatusFilter.value = 'all';
  if (visualSort) visualSort.value = 'updated';
  pendingVisualEntryId = Number(draft.id);
  setEditorData(data);
  return { draft, seededLangs: [] };
}

async function persistNewCanonicalDraft(section, entry) {
  // One protected, versioned entity write is enough to make creation durable.
  // It replaces the former whole-document background POST that could arrive
  // after a newer edit and make a just-created draft vanish.
  await saveEntityToServer(section, DEFAULT_LANGUAGE, entry);
}

// Articles and Pics of the week are separate editorial collections. The
// homepage strip accepts only explicitly curated image records; writing an
// article never creates a homepage photo automatically.
async function createArticleFromBlueprint(kind) {
  try {
    setBusy(true);
    const data = parseEditorJson();
    const nextId = getNextEntryId(data, 'articles');
    const { draft } = stageCanonicalDraft(data, 'articles', buildArticleBlueprint(kind, nextId));
    setStatus('info', `Создаю черновик статьи #${nextId} на VPS…`);
    await persistNewCanonicalDraft('articles', draft);
    setStatus('success', `Черновик статьи #${nextId} создан, открыт в редакторе и сохранён на VPS. Переводы появятся только после явной команды «Синхронизировать».`);
  } catch (error) {
    setStatus('error', getErrorMessage(error));
  } finally {
    setBusy(false);
  }
}

async function createReviewFromBlueprint(kind) {
  try {
    setBusy(true);
    const data = parseEditorJson();
    const nextId = getNextEntryId(data, 'reviews');
    const { draft } = stageCanonicalDraft(data, 'reviews', buildReviewBlueprint(kind, nextId));
    setStatus('info', `Создаю черновик обзора #${nextId} на VPS…`);
    await persistNewCanonicalDraft('reviews', draft);
    setStatus('success', `Черновик обзора #${nextId} создан, открыт в редакторе и сохранён на VPS. Переводы появятся только после явной команды «Синхронизировать».`);
  } catch (error) {
    setStatus('error', getErrorMessage(error));
  } finally {
    setBusy(false);
  }
}

function appendArticlePreset(kind) {
  try {
    if (visualSectionSelect.value !== 'articles') {
      throw new Error('Быстрые блоки доступны в разделе «Статьи».');
    }

    const editorEl = document.getElementById('vf-block-editor');
    if (!editorEl) {
      throw new Error('Сначала выберите статью.');
    }

    const preset = ARTICLE_BLOCK_PRESETS[kind];
    if (!preset) {
      throw new Error('Неизвестный шаблон блока.');
    }

    const blocks = collectBlockEditorContent();
    const seed = getFieldValue('vf-imageSeed').trim() || getCreatorInputValue(creatorSeedInput) || `article-${visualEntrySelect.value || 'new'}`;
    const nextBlocks = deepClone(preset).map((block, index) => {
      if (block.type === 'image' && !block.content) {
        return { ...block, content: `${seed}-section-${blocks.length + index + 1}` };
      }
      return block;
    });

    redrawBlockEditor([...blocks, ...nextBlocks]);bindCreatorQualityInputs(buildQualityEntryFromForm('articles'));
    const data = getVisualData();
    const previewEntry = {
      id: Number(visualEntrySelect.value),
      title: getFieldValue('vf-title').trim(),
      excerpt: getFieldValue('vf-excerpt').trim(),
      tags: getFieldValue('vf-tags').split(',').map((tag) => tag.trim()).filter(Boolean),
      imageSeed: getFieldValue('vf-imageSeed').trim(),
      imageUrl: getFieldValue('vf-imageUrl').trim(),
      content: collectBlockEditorContent()
    };
    renderCreatorQuality(data, 'articles', visualLangSelect.value || DEFAULT_LANGUAGE, previewEntry);
    renderContentCommand(data, 'articles', visualLangSelect.value || DEFAULT_LANGUAGE, previewEntry);
    setStatus('success', 'Блоки добавлены. Нажмите «Применить изменения», чтобы записать их в JSON.');
  } catch (error) {
    setStatus('error', getErrorMessage(error));
  }
}

function renderVisualLanguageOptions(data) {
  const options = getLanguageOptions(data);
  const current = visualLangSelect.value || DEFAULT_LANGUAGE;

  visualLangSelect.innerHTML = options
    .map((lang) => `<option value="${escapeHtml(lang)}">${escapeHtml(lang)}</option>`)
    .join('');

  if (options.includes(current)) {
    visualLangSelect.value = current;
  } else {
    visualLangSelect.value = DEFAULT_LANGUAGE;
  }
}

function refreshVisualEditor() {
  const data = getVisualData();
  if (!data) {
    return;
  }

  renderVisualLanguageOptions(data);
  const section = visualSectionSelect.value;
  const lang = visualLangSelect.value || DEFAULT_LANGUAGE;
  const entries = getSectionArray(data, section, lang, false);
  const search = visualSearchInput.value.trim().toLowerCase();
  const statusFilter = visualStatusFilter?.value || 'all';
  const sortMode = visualSort?.value || 'updated';
  renderPublicationSummary(data, section);

  // For non-EN languages, build dropdown from ALL EN entries so untranslated ones are visible
  let dropdownEntries;
  if (lang !== DEFAULT_LANGUAGE) {
    const enEntries = getSectionArray(data, section, DEFAULT_LANGUAGE, false);
    const localizedIds = new Set(entries.map(e => Number(e.id)));
    dropdownEntries = enEntries.map(enEntry => {
      const localizedEntry = entries.find(le => Number(le.id) === Number(enEntry.id));
      return {
        id: enEntry.id,
        _entry: localizedEntry || enEntry,
        _hasTranslation: localizedIds.has(Number(enEntry.id)),
        _enTitle: getEntryTitle(section, enEntry)
      };
    });
  } else {
    dropdownEntries = entries.map(entry => ({
      id: entry.id,
      _entry: entry,
      _hasTranslation: true,
      _enTitle: getEntryTitle(section, entry)
    }));
  }

  const filteredDropdown = dropdownEntries.filter((item) => {
      const publicationState = getPublicationState(data, section, item._entry);
      if (statusFilter !== 'all' && publicationState !== statusFilter) return false;
      if (!search) return true;
      const idText = String(item.id || '').toLowerCase();
      const title = getEntryTitle(section, item._entry).toLowerCase();
      const enTitle = item._enTitle.toLowerCase();
      return idText.includes(search) || title.includes(search) || enTitle.includes(search);
  });
  const visibleDropdown = filteredDropdown.slice().sort((a, b) => {
    if (sortMode === 'title') return getEntryTitle(section, a._entry).localeCompare(getEntryTitle(section, b._entry));
    if (sortMode === 'id') return Number(a.id) - Number(b.id);
    if (sortMode === 'status') {
      const order = { draft: 0, scheduled: 1, hidden: 2, live: 3 };
      return (order[getPublicationState(data, section, a._entry)] ?? 9) - (order[getPublicationState(data, section, b._entry)] ?? 9)
        || publicationTimestamp(b._entry) - publicationTimestamp(a._entry);
    }
    return publicationTimestamp(b._entry) - publicationTimestamp(a._entry)
      || Number(b.id) - Number(a.id);
  });

  const optionsHtml = visibleDropdown
    .map((item) => {
      const id = Number(item.id);
      const publicationState = getPublicationState(data, section, item._entry);
      let label = item._hasTranslation
        ? getEntryTitle(section, item._entry)
        : item._enTitle + ' (не переведено)';
      const e = item._entry || {};
      label += ` ${publicationStateIcon(publicationState)} ${publicationStateLabel(publicationState).toUpperCase()}`;
      return `<option value="${id}">#${id} - ${escapeHtml(label)}</option>`;
    })
    .join('');

  visualEntrySelect.innerHTML = optionsHtml;

  if (!dropdownEntries.length) {
    setVisualNotice(`В разделе "${getSectionLabel(section)}" пока нет записей.`, 'info');
    visualFormEl.innerHTML = '';
    renderCreatorQuality(data, section, lang, null);
    renderContentCommand(data, section, lang, null);
    return;
  }

  if (!visibleDropdown.length) {
    setVisualNotice(`По запросу "${search}" ничего не найдено.`, 'info');
    visualFormEl.innerHTML = '';
    renderCreatorQuality(data, section, lang, null);
    renderContentCommand(data, section, lang, null);
    return;
  }

  const desiredId = pendingVisualEntryId !== null ? String(pendingVisualEntryId) : visualEntrySelect.value;
  pendingVisualEntryId = null;

  if (desiredId && visibleDropdown.some((item) => String(item.id) === desiredId)) {
    visualEntrySelect.value = desiredId;
  } else {
    visualEntrySelect.value = String(visibleDropdown[0].id);
  }

  updateAdminToolbarContext();
  renderVisualForm();
  // Setting .value programmatically fires no 'change' event, so the WYSIWYG
  // and Review live-canvases (which reload only on that event) would keep
  // showing whatever entry was open before — e.g. after "create new article"
  // the canvas kept the previous article, and edits typed there landed back
  // on the OLD entry instead of the new one. Sync both canvases directly.
  if (typeof window._wysReload === 'function') window._wysReload();
  if (typeof window._revReload === 'function') window._revReload();
  // Same reasoning applies to Creator Studio's blueprint button group — a
  // programmatic section change (e.g. createReviewFromBlueprint switching
  // to 'reviews') must also refresh which button set is visible.
  updateCreatorStudioForSection();
}

function setVisualNotice(message, type) {
  visualNoticeEl.className = 'visual-notice';
  if (type === 'error') {
    visualNoticeEl.classList.add('error');
  }
  visualNoticeEl.textContent = message;
}

function setVisualNoticeHtml(html, type) {
  visualNoticeEl.className = 'visual-notice';
  if (type === 'error') visualNoticeEl.classList.add('error');
  if (type === 'success') visualNoticeEl.classList.add('success');
  visualNoticeEl.innerHTML = html;
}

function getOptionalString(value) {
  const normalized = String(value || '').trim();
  return normalized || undefined;
}

function isCustomMediaReference(value) {
  return /^(https?:)?\/\//i.test(value) || value.startsWith('/') || value.startsWith('./') || value.startsWith('../') || value.startsWith('data:') || value.startsWith('blob:');
}

function resolvePreviewImageSource(imageUrl, imageSeed) {
  const normalizedUrl = String(imageUrl || '').trim();
  if (normalizedUrl) {
    return normalizedUrl;
  }

  const normalizedSeed = String(imageSeed || '').trim();
  if (!normalizedSeed) {
    return '';
  }

  if (isCustomMediaReference(normalizedSeed)) {
    return normalizedSeed;
  }

  return `https://picsum.photos/seed/${encodeURIComponent(normalizedSeed)}/900/520`;
}

// Scans the currently loaded content (all languages) for references to a
// given image URL — used by the media picker to show "used ×N" badges and
// warn before deleting a photo that's actually in use. Computed on demand
// from editor.value rather than a server-side count, so it stays correct
// against unsaved edits (exactly the moment a delete decision is being made).
// LibraryItem has no image field, so it's intentionally excluded.
function countMediaUsage(url) {
  const norm = String(url || '').trim();
  if (!norm) return { count: 0, refs: [] };
  const data = parseEditorJsonSafe();
  if (!data) return { count: 0, refs: [] };
  const matches = (v) => typeof v === 'string' && v.trim() === norm;
  const refs = [];
  const langs = getLanguageOptions(data);
  ['articles', 'reviews', 'items'].forEach((section) => {
    langs.forEach((lang) => {
      getSectionArray(data, section, lang, false).forEach((entry) => {
        if (matches(entry.imageUrl)) refs.push({ section, id: entry.id, lang });
        if (section === 'articles' && Array.isArray(entry.content)) {
          entry.content.forEach((block) => {
            if (block.type === 'image' && matches(block.content)) refs.push({ section, id: entry.id, lang });
            if (block.type === 'gallery' && Array.isArray(block.content) && block.content.some(matches)) refs.push({ section, id: entry.id, lang });
          });
        }
      });
    });
  });
  return { count: refs.length, refs };
}

function renderPhotoPreviewMarkup(source) {
  const hasSource = Boolean(source);
  return `
    <div class="photo-preview full">
      <p class="form-hint">
        Предпросмотр. Если заполнен URL, на сайте будет использоваться он. Если URL пустой, используется imageSeed.
      </p>
      <img
        id="vf-preview-image"
        src="${hasSource ? escapeHtml(source) : ''}"
        alt="Предпросмотр изображения"
        loading="lazy"
        referrerpolicy="no-referrer"
        ${hasSource ? '' : 'hidden'}
      />
      <div id="vf-preview-empty" class="photo-preview-empty" ${hasSource ? 'hidden' : ''}>
        Добавьте URL фото или imageSeed, чтобы увидеть превью.
      </div>
    </div>
  `;
}

function refreshPhotoPreviewFromInputs() {
  const imageEl = document.getElementById('vf-preview-image');
  const emptyEl = document.getElementById('vf-preview-empty');
  if (!imageEl || !emptyEl) {
    return;
  }

  const source = resolvePreviewImageSource(getFieldValue('vf-imageUrl'), getFieldValue('vf-imageSeed'));
  if (!source) {
    imageEl.setAttribute('hidden', 'hidden');
    imageEl.setAttribute('src', '');
    emptyEl.removeAttribute('hidden');
    return;
  }

  imageEl.setAttribute('src', source);
  imageEl.removeAttribute('hidden');
  emptyEl.setAttribute('hidden', 'hidden');
}

function bindPhotoPreviewInputs() {
  const imageUrlInput = document.getElementById('vf-imageUrl');
  const imageSeedInput = document.getElementById('vf-imageSeed');
  if (!imageUrlInput || !imageSeedInput) {
    return;
  }

  imageUrlInput.addEventListener('input', refreshPhotoPreviewFromInputs);
  imageSeedInput.addEventListener('input', refreshPhotoPreviewFromInputs);
  refreshPhotoPreviewFromInputs();
}

// Gallery items' extra "photos" repeater — shown in the site's read-detail
// view (GalleryItemView) alongside the cover imageUrl above. Reads current
// row values straight from the DOM before every add/remove so in-progress
// edits in other rows survive the redraw, same pattern as the block editor's
// gallery/checklist/poll repeaters.
function renderGalleryPhotosRepeaterMarkup(photos) {
  if (!photos.length) {
    return '<p class="form-hint">Доп. фото нет — в просмотре покажется только обложка.</p>';
  }
  return photos.map((photo, i) => `
    <div class="vf-photo-row" style="display:flex;gap:8px;align-items:flex-start;margin-bottom:8px;">
      <input class="vf-photo-url" placeholder="URL фото" value="${escapeHtml(photo.url || '')}" style="flex:2;min-width:0" />
      <input class="vf-photo-caption" placeholder="Подпись (необязательно)" value="${escapeHtml(photo.caption || '')}" style="flex:1;min-width:0" />
      <button type="button" class="btn btn-sm" onclick="uploadGalleryPhotoRow(${i})" title="Загрузить с ПК">📁</button>
      <button type="button" class="block-action-btn danger" onclick="removeGalleryPhotoRow(${i})" title="Удалить"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><path d="M18 6 6 18M6 6l12 12"/></svg></button>
    </div>
  `).join('');
}

function readGalleryPhotoRows() {
  return Array.from(document.querySelectorAll('#vf-photos-repeater .vf-photo-row')).map((row) => ({
    url: row.querySelector('.vf-photo-url')?.value || '',
    caption: row.querySelector('.vf-photo-caption')?.value || ''
  }));
}

function redrawGalleryPhotosRepeater(photos) {
  const container = document.getElementById('vf-photos-repeater');
  if (container) container.innerHTML = renderGalleryPhotosRepeaterMarkup(photos);
}

window.addGalleryPhotoRow = function() {
  const photos = readGalleryPhotoRows();
  photos.push({ url: '', caption: '' });
  redrawGalleryPhotosRepeater(photos);
};

window.removeGalleryPhotoRow = function(index) {
  const photos = readGalleryPhotoRows();
  photos.splice(index, 1);
  redrawGalleryPhotosRepeater(photos);
};

window.uploadGalleryPhotoRow = async function(index) {
  const fileInput = document.getElementById('vf-photo-upload-input');
  if (!fileInput) return;
  fileInput.onchange = async () => {
    const file = fileInput.files && fileInput.files[0];
    fileInput.value = '';
    if (!file) return;
    try {
      const url = await uploadImageReturnUrl(file);
      const photos = readGalleryPhotoRows();
      if (photos[index]) {
        photos[index].url = url;
        redrawGalleryPhotosRepeater(photos);
        showToast('success', 'Фото загружено — URL подставлен.');
      }
    } catch (e) {
      showToast('error', getErrorMessage(e));
    }
  };
  fileInput.click();
};

// Shared draft/publishAt fields for the classic (non-canvas) forms — Items,
// LibraryItems, and Reviews' plain-form fallback all reuse this markup.
function renderDraftFieldsMarkup(entry) {
  return `
    <div class="entry-draft-fields full">
      <label class="checkbox-label" for="vf-draft"><input id="vf-draft" type="checkbox" ${entry.draft ? 'checked' : ''} /> Черновик (скрыт с сайта)</label>
      <label>Отложенная публикация (скрыта до этого момента)<input id="vf-publishAt" type="datetime-local" value="${escapeHtml(isoToLocalInput(entry.publishAt))}" /></label>
    </div>
  `;
}

// One byline component for every classic editor.  The public page still gets
// a plain `author` string, while `authorId` keeps the durable connection to
// the registry card (photo, role and translations can evolve independently).
function getRegistryAuthors(data) {
  return (Array.isArray(data?.authors) ? data.authors : [])
    .filter((author) => author && author.id)
    .slice()
    .sort((a, b) => String(a.name || a.id).localeCompare(String(b.name || b.id), 'ru'));
}

function renderRegistryAuthorBlock(data, entry, options = {}) {
  const authors = getRegistryAuthors(data);
  const selected = authors.find((author) => author.id === entry?.authorId) || null;
  const context = options.context || 'материала';
  const optionsMarkup = ['<option value="">— Вручную, без карточки автора —</option>']
    .concat(authors.map((author) => `<option value="${escapeHtml(author.id)}" ${author.id === entry?.authorId ? 'selected' : ''}>${escapeHtml(author.name || author.id)}${author.active === false ? ' · скрыт в команде' : ''}</option>`))
    .join('');
  const portrait = selected?.photoUrl
    ? `<img src="${escapeHtml(selected.photoUrl)}" alt="" loading="lazy" referrerpolicy="no-referrer" />`
    : `<span aria-hidden="true">${escapeHtml((selected?.name || entry?.author || '?').trim().charAt(0).toUpperCase() || '?')}</span>`;
  const selectedText = selected
    ? `${escapeHtml(selected.name || '')}${selected.role ? `<small>${escapeHtml(selected.role)}</small>` : ''}`
    : '<span class="registry-author-empty">Карточка автора пока не выбрана</span>';

  return `
    <section class="registry-author-block full" data-registry-author-block>
      <div class="registry-author-heading">
        <span>Подпись ${escapeHtml(context)}</span>
        <strong>Автор публикации</strong>
        <p>Выберите автора из реестра. Имя и роль подставятся автоматически; при сохранении останется и связь с карточкой автора.</p>
      </div>
      <div class="registry-author-grid">
        <label class="registry-author-select">
          <span>Автор из реестра</span>
          <select id="vf-authorId">${optionsMarkup}</select>
        </label>
        <div class="registry-author-summary" data-registry-author-summary>
          <div class="registry-author-avatar">${portrait}</div>
          <div>${selectedText}</div>
        </div>
        <label>
          <span>Имя в публикации</span>
          <input id="vf-author" value="${escapeHtml(entry?.author || '')}" placeholder="Имя автора" />
        </label>
        <label>
          <span>Роль / credit</span>
          <input id="vf-role" value="${escapeHtml(entry?.role || '')}" placeholder="Автор, фотограф, contributing editor…" />
        </label>
      </div>
    </section>
  `;
}

function bindRegistryAuthorBlock(data) {
  const select = document.getElementById('vf-authorId');
  if (!select) return;
  select.addEventListener('change', () => {
    const author = getRegistryAuthors(data).find((item) => item.id === select.value);
    if (!author) return; // manual byline: retain what the editor already typed
    const authorInput = document.getElementById('vf-author');
    const roleInput = document.getElementById('vf-role');
    if (authorInput) {
      authorInput.value = author.name || '';
    }
    if (roleInput) {
      roleInput.value = author.role || '';
    }
  });
  // A manually changed name is a deliberate free-form byline, not an alias
  // for the previously selected registry author.
  document.getElementById('vf-author')?.addEventListener('input', () => {
    if (select.value) select.value = '';
  });
}

function renderVisualForm() {
  const data = getVisualData();
  if (!data) {
    return;
  }

  const section = visualSectionSelect.value;
  const lang = visualLangSelect.value || DEFAULT_LANGUAGE;
  updateAdminToolbarContext();
  // The modern Editor.js editor only applies to articles; tear it down otherwise.
  if (section !== 'articles') unmountModernEditor();
  const entries = getSectionArray(data, section, lang, false);

  if (!entries.length) {
    visualFormEl.innerHTML = '';
    renderCreatorQuality(data, section, lang, null);
    renderContentCommand(data, section, lang, null);
    return;
  }

  const selectedId = Number(visualEntrySelect.value);
  let entry = entries.find((item) => Number(item.id) === selectedId);

  // If entry not found in localized collection, check if it exists in EN
  if (!entry && lang !== DEFAULT_LANGUAGE) {
    const enEntries = getSectionArray(data, section, DEFAULT_LANGUAGE, false);
    const enEntry = enEntries.find((item) => Number(item.id) === selectedId);
    if (enEntry) {
      setVisualNotice(`Запись #${selectedId} ещё не переведена на ${lang}. Нажмите «Копия из EN», чтобы создать перевод.`, 'info');
      // Show the EN content as read-only preview
      entry = enEntry;
    }
  }

  if (!entry) {
    entry = entries[0];
  }

  if (!entry) {
    visualFormEl.innerHTML = '';
    renderCreatorQuality(data, section, lang, null);
    renderContentCommand(data, section, lang, null);
    return;
  }

  setVisualNotice(`Редактируется: ${getSectionLabel(section)} / #${entry.id} / язык ${lang}`, 'info');
  renderCreatorQuality(data, section, lang, entry);
  renderContentCommand(data, section, lang, entry);

  if (section === 'items') {
    const previewSource = resolvePreviewImageSource(entry.imageUrl, entry.imageSeed);
    const isPicsOfWeekCard = entry.picsOfWeek === true;
    const homepageCategoryOptions = (window._homepageCategories ? window._homepageCategories(data) : []).map((category) => `<option value="${escapeHtml(category.id)}" ${entry.homeCategory === category.id ? 'selected' : ''}>${escapeHtml(category.label)}</option>`).join('');
    visualFormEl.innerHTML = `
      <label>Внутренний ID медиа<input id="vf-id" value="${escapeHtml(entry.id)}" disabled /></label>
      ${isPicsOfWeekCard
        ? `<label>Pics ID<input id="vf-picsId" value="${escapeHtml(picsIdFor(entry))}" disabled /></label>`
        : '<div class="form-hint">Медиа статьи: это не карточка Pics of the week и не попадает в подборку на главной.</div>'}
      <label>FIG<input id="vf-fig" value="${escapeHtml(entry.fig || '')}" /></label>
      <label class="full">Заголовок исходной записи<input id="vf-title" value="${escapeHtml(entry.title || '')}" /></label>
      <label class="full">Подзаголовок исходной записи<input id="vf-subtitle" value="${escapeHtml(entry.subtitle || '')}" /></label>
      <label class="full">Описание исходной записи<textarea id="vf-description">${escapeHtml(entry.description || '')}</textarea></label>
      ${isPicsOfWeekCard ? `
        <label>Категория Pics of the week<select id="vf-homeCategory"><option value="">Выберите категорию</option>${homepageCategoryOptions}</select></label>
        <label>Метка на изображении<input id="vf-homeLabel" value="${escapeHtml(entry.homeLabel || '')}" placeholder="Необязательная подпись" /></label>
        <div class="full homepage-work-fields">
          <div class="homepage-work-fields-head"><strong>Текст карточки на главной · Pics of the week</strong><span>Это самостоятельная работа, а не материал журнала. Пустые поля наследуют базовый текст; после правки синхронизируйте 7 языков.</span></div>
          <label>Название работы<input id="vf-homeTitle" value="${escapeHtml(entry.homeTitle || '')}" placeholder="Название работы" /></label>
          <label>Короткая строка<input id="vf-homeSubtitle" value="${escapeHtml(entry.homeSubtitle || '')}" placeholder="Автор · год · материал" /></label>
          <label class="full">Описание работы<textarea id="vf-homeDescription" placeholder="Короткое описание изображения">${escapeHtml(entry.homeDescription || '')}</textarea></label>
          <label>Автор / источник<input id="vf-homeCredit" value="${escapeHtml(entry.homeCredit || '')}" placeholder="Artist · museum / archive" /></label>
          <label>Источник изображения<input id="vf-homeSourceUrl" value="${escapeHtml(entry.homeSourceUrl || '')}" placeholder="https://…" /></label>
        </div>
      ` : ''}
      <div class="full homepage-image-editor" style="margin-bottom:4px">
        <div class="homepage-work-fields-head"><strong>${isPicsOfWeekCard ? 'Главное фото карточки' : 'Изображение записи'}</strong><span>${isPicsOfWeekCard ? 'Это изображение увидит посетитель в Pics of the week. Вставьте URL или загрузите файл — превью обновится сразу.' : 'Изображение остаётся частью этой записи и никогда не будет автоматически показано в Pics of the week.'}</span></div>
        ${renderPhotoPreviewMarkup(previewSource)}
        <label class="homepage-image-url-field">URL фото<input id="vf-imageUrl" value="${escapeHtml(entry.imageUrl || '')}" placeholder="https://… или /images/…" /></label>
        <div class="homepage-image-editor-actions"><button id="vf-img-upload-btn" class="btn btn-sm" type="button">${adminIcon('upload')}<span class="btn-label">Загрузить файл</span></button><a class="btn btn-sm" href="../" target="_blank" rel="noreferrer"><span class="btn-label">Проверить на главной</span>${adminIcon('external')}</a></div>
        <input id="vf-img-upload-input" type="file" accept="image/*" hidden />
      </div>
      <label class="full">imageSeed (если URL пустой)<input id="vf-imageSeed" value="${escapeHtml(entry.imageSeed || '')}" /></label>
      <div class="full">
        <span class="toolbar-field-label" style="display:block;margin-bottom:6px;">Доп. фото для просмотра «read» (необязательно, с подписями)</span>
        <div id="vf-photos-repeater">${renderGalleryPhotosRepeaterMarkup(entry.images || [])}</div>
        <button type="button" class="btn btn-sm" onclick="addGalleryPhotoRow()" style="margin-top:4px;">+ Добавить фото</button>
        <input id="vf-photo-upload-input" type="file" accept="image/*" hidden />
      </div>
      ${renderDraftFieldsMarkup(entry)}
      ${renderRegistryAuthorBlock(data, entry, { context: 'медиа' })}
    `;
    bindPhotoPreviewInputs();
    bindUploadButton('vf-img-upload-btn', 'vf-img-upload-input', 'vf-imageUrl', () => {
      document.getElementById('vf-imageUrl')?.dispatchEvent(new Event('input'));
    });
    bindRegistryAuthorBlock(data);
    bindCreatorQualityInputs(entry);
    return;
  }

  if (section === 'reviews') {
    const revImg = (entry.imageUrl || '').trim();
    visualFormEl.innerHTML = `
      <label>ID<input id="vf-id" value="${escapeHtml(entry.id)}" disabled /></label>
      <label>Категория<input id="vf-category" value="${escapeHtml(entry.category || '')}" placeholder="Food / Books / Stay…" /></label>
      <label class="checkbox-label" style="align-self:end" for="vf-featured"><input id="vf-featured" type="checkbox" ${entry.featured ? 'checked' : ''} /> Featured — первым в разделе</label>
      <label class="full">Заголовок<input id="vf-title" value="${escapeHtml(entry.title || '')}" /></label>
      <label class="full">Тема (что обозревается)<input id="vf-subject" value="${escapeHtml(entry.subject || '')}" /></label>
      <label class="full">Вердикт (одна строка-вывод)<input id="vf-verdict" value="${escapeHtml(entry.verdict || '')}" /></label>
      <label class="full">Плюсы (по одному на строку)<textarea id="vf-pros">${escapeHtml(Array.isArray(entry.pros) ? entry.pros.join('\n') : '')}</textarea></label>
      <label class="full">Минусы (по одному на строку)<textarea id="vf-cons">${escapeHtml(Array.isArray(entry.cons) ? entry.cons.join('\n') : '')}</textarea></label>
      <label>Мета (локация/цена/год)<input id="vf-meta" value="${escapeHtml(entry.meta || '')}" /></label>
      <label>Ссылка (необязательно)<input id="vf-link" value="${escapeHtml(entry.link || '')}" placeholder="https://…" /></label>
      <label>Дата (необязательно)<input id="vf-date" value="${escapeHtml(entry.date || '')}" /></label>
      <input type="hidden" id="vf-imageUrl" value="${escapeHtml(entry.imageUrl || '')}" />
      <div class="full" style="margin-bottom:4px">
        <div class="photo-preview" style="margin-bottom:8px">
          <img id="vf-rev-preview" src="${revImg ? escapeHtml(revImg) : ''}" alt="Превью обложки" loading="lazy" referrerpolicy="no-referrer" ${revImg ? '' : 'hidden'} />
          <div id="vf-rev-preview-empty" class="photo-preview-empty" ${revImg ? 'hidden' : ''}>Обложка не выбрана</div>
        </div>
        <button id="vf-rev-upload-btn" class="btn btn-sm" type="button">${adminIcon('upload')}<span class="btn-label">Загрузить фото обложки</span></button>
        <input id="vf-rev-upload-input" type="file" accept="image/*" hidden />
      </div>
      ${renderDraftFieldsMarkup(entry)}
      ${renderRegistryAuthorBlock(data, entry, { context: 'обзора' })}
    `;
    const refreshRevPreview = () => {
      const img = document.getElementById('vf-rev-preview');
      const empty = document.getElementById('vf-rev-preview-empty');
      const url = (document.getElementById('vf-imageUrl')?.value || '').trim();
      if (!img || !empty) return;
      if (url) { img.src = url; img.removeAttribute('hidden'); empty.setAttribute('hidden', 'hidden'); }
      else { img.setAttribute('hidden', 'hidden'); img.src = ''; empty.removeAttribute('hidden'); }
    };
    document.getElementById('vf-imageUrl')?.addEventListener('input', refreshRevPreview);
    bindUploadButton('vf-rev-upload-btn', 'vf-rev-upload-input', 'vf-imageUrl', refreshRevPreview);
    bindRegistryAuthorBlock(data);
    bindCreatorQualityInputs(entry);
    return;
  }

  if (section === 'libraryItems') {
    visualFormEl.innerHTML = `
      <label>ID<input id="vf-id" value="${escapeHtml(entry.id)}" disabled /></label>
      <label>Тип<input id="vf-type" value="${escapeHtml(entry.type || '')}" /></label>
      <label class="full">Название<input id="vf-title" value="${escapeHtml(entry.title || '')}" /></label>
      <label class="full">PDF URL<input id="vf-url" placeholder="https://..." value="${escapeHtml(entry.url || '')}" /></label>
      <label>Размер<input id="vf-size" value="${escapeHtml(entry.size || '')}" /></label>
      <label>Год<input id="vf-year" value="${escapeHtml(entry.year || '')}" /></label>
      ${renderDraftFieldsMarkup(entry)}
      ${renderRegistryAuthorBlock(data, entry, { context: 'материала библиотеки' })}
    `;
    bindRegistryAuthorBlock(data);
    bindCreatorQualityInputs(entry);
    return;
  }

  const previewSource = resolvePreviewImageSource(entry.imageUrl, entry.imageSeed);
  const hasSource = Boolean(previewSource);
  visualFormEl.innerHTML = `
    <div class="editor-canvas-layout">
      <!-- MAIN CANVAS -->
      <div class="editor-main-canvas">
        <div class="style-helper-card">
          <div class="style-helper-head">
            <strong>Как менять стиль текста</strong>
            <span>Работает сразу в блоке, без обходных приемов</span>
          </div>
          <div class="style-helper-grid">
            <span><b>Обычный текст</b> – блок Paragraph. Вставка очищается автоматически: чужой шрифт, размер и цвет из Word/Instagram не должны переноситься в статью.</span>
            <span><b>Заголовок</b> – добавьте блок Heading, а не увеличивайте Paragraph вручную. Так сайт сохранит правильный шрифт, размер и SEO-структуру.</span>
            <span><b>Переводы</b> – текущий язык становится источником. «Сохранить + языки» одновременно переводит текст, сохраняет абзацы, ссылки, фото и порядок блоков во всех версиях.</span>
          </div>
        </div>
        <input id="vf-title" class="canvas-title" placeholder="Заголовок статьи..." value="${escapeHtml(entry.title || '')}" />
        <textarea id="vf-excerpt" class="canvas-excerpt" placeholder="Введите краткое описание (лид) статьи...">${escapeHtml(entry.excerpt || '')}</textarea>
        <div class="block-editor" id="vf-block-editor"></div>
      </div>

      <!-- META SIDEBAR -->
      <div class="editor-meta-sidebar">
        <!-- Cover Preview Box -->
        <div class="canvas-cover-preview">
          <img id="vf-preview-image" src="${hasSource ? escapeHtml(previewSource) : ''}" ${!hasSource ? 'hidden' : ''} />
          <div id="vf-preview-empty" class="canvas-cover-empty" ${hasSource ? 'hidden' : ''}>
            <span style="font-size:2rem;margin-bottom:4px">🖼️</span>
            <span>Нет обложки</span>
          </div>
        </div>

        <div class="meta-field-group">
          <label>URL обложки</label>
          <div style="display:flex;gap:4px;">
            <input id="vf-imageUrl" placeholder="https://..." value="${escapeHtml(entry.imageUrl || '')}" style="flex:1" />
            <button id="vf-img-upload-btn" class="btn btn-sm" type="button" title="Загрузить с ПК" style="padding:4px 8px;font-size:.8rem;">📁</button>
            <input id="vf-img-upload-input" type="file" accept="image/*" hidden />
          </div>
        </div>

        <div class="meta-field-group">
          <label>imageSeed (если URL пуст)</label>
          <input id="vf-imageSeed" value="${escapeHtml(entry.imageSeed || '')}" placeholder="visual-seed..." />
        </div>

        <div style="display:flex;gap:12px;width:100%;">
          <div class="meta-field-group" style="width:60px;">
            <label>ID</label>
            <input id="vf-id" value="${escapeHtml(entry.id)}" disabled style="background:var(--bg);opacity:0.7;padding:8px 4px;text-align:center;" />
          </div>
          <div class="meta-field-group" style="flex:1;">
            <label>Дата</label>
            <input id="vf-date" value="${escapeHtml(entry.date || '')}" placeholder="Mar 14, 2026" />
          </div>
        </div>

        <div class="meta-field-group">
          <label>Категория</label>
          <input id="vf-category" value="${escapeHtml(entry.category || '')}" placeholder="Culture, Travel..." />
        </div>

        <div class="meta-field-group">
          <label>Подкатегория</label>
          <input id="vf-subcategory" value="${escapeHtml(entry.subcategory || '')}" placeholder="Essay..." />
        </div>

        <div class="meta-field-group">
          <label>Теги (через запятую)</label>
          <input id="vf-tags" value="${escapeHtml(Array.isArray(entry.tags) ? entry.tags.join(', ') : '')}" placeholder="tag1, tag2..." />
        </div>
      </div>
    </div>
    ${renderRegistryAuthorBlock(data, entry, { context: 'статьи' })}
  `;
  bindPhotoPreviewInputs();
  bindUploadButton('vf-img-upload-btn', 'vf-img-upload-input', 'vf-imageUrl', () => {
    document.getElementById('vf-imageUrl')?.dispatchEvent(new Event('input'));
  });
  bindRegistryAuthorBlock(data);
  // Articles use the modern Editor.js block editor.
  mountModernEditor(entry.content || []);
  bindCreatorQualityInputs(entry);
}

function getFieldValue(id) {
  const element = document.getElementById(id);
  if (!element) {
    return '';
  }
  return element.value;
}

// Applies draft/publishAt from the shared classic-form fields (Items,
// LibraryItems, Reviews) onto `next` in place, using the delete-when-unset
// convention (matches the WYSIWYG drawers, keeps "live" entries field-free).
function applyDraftFieldsFromForm(next) {
  const draftEl = document.getElementById('vf-draft');
  if (draftEl?.checked) next.draft = true; else delete next.draft;
  const pv = document.getElementById('vf-publishAt')?.value;
  if (pv) next.publishAt = new Date(pv).toISOString(); else delete next.publishAt;
}

// Pics of the week keeps its own editorial fields, but an empty field should
// never leave a card without a title or description. Store the inherited value
// explicitly so new cards, translated copies and archive snapshots all keep the
// same source-of-truth even when the homepage is edited later.
function inheritHomepageFields(next) {
  if (!next || typeof next !== 'object') return next;
  if (!String(next.homeTitle || '').trim()) next.homeTitle = String(next.title || '').trim();
  if (!String(next.homeSubtitle || '').trim()) next.homeSubtitle = String(next.subtitle || '').trim();
  if (!String(next.homeDescription || '').trim()) next.homeDescription = String(next.description || '').trim();
  return next;
}

// Reads the current classic-form fields into a full replacement entity for
// `section`, based on `current` (spread first so untouched fields survive).
// Shared by applyVisualChanges() (writes into the whole-document textarea)
// and saveCurrentEntryOnly() (PATCHes just this one entity to the server).
function buildEntryFromVisualForm(section, current) {
  let next = { ...current };

  if (section === 'items') {
    const isPicsOfWeekCard = current?.picsOfWeek === true;
    const photos = readGalleryPhotoRows()
      .map((p) => ({ url: p.url.trim(), caption: p.caption.trim() }))
      .filter((p) => p.url)
      .map((p) => (p.caption ? p : { url: p.url }));
    next = {
      ...next,
      fig: getFieldValue('vf-fig').trim(),
      title: getFieldValue('vf-title').trim(),
      subtitle: getFieldValue('vf-subtitle').trim(),
      description: getFieldValue('vf-description').trim(),
      imageSeed: getFieldValue('vf-imageSeed').trim(),
      imageUrl: getOptionalString(getFieldValue('vf-imageUrl')),
      author: getOptionalString(getFieldValue('vf-author')),
      authorId: getOptionalString(getFieldValue('vf-authorId')),
      role: getOptionalString(getFieldValue('vf-role')),
      ...(isPicsOfWeekCard ? {
        homeCategory: getOptionalString(getFieldValue('vf-homeCategory')),
        homeLabel: getOptionalString(getFieldValue('vf-homeLabel')),
        homeTitle: getOptionalString(getFieldValue('vf-homeTitle')),
        homeSubtitle: getOptionalString(getFieldValue('vf-homeSubtitle')),
        homeDescription: getOptionalString(getFieldValue('vf-homeDescription')),
        homeCredit: getOptionalString(getFieldValue('vf-homeCredit')),
        homeSourceUrl: getOptionalString(getFieldValue('vf-homeSourceUrl')),
      } : {}),
      images: photos.length ? photos : undefined
    };
    applyDraftFieldsFromForm(next);
    if (isPicsOfWeekCard) inheritHomepageFields(next);
  } else if (section === 'reviews') {
    const lines = (id) => getFieldValue(id).split('\n').map((s) => s.trim()).filter(Boolean);
    // NOTE: 'content' is managed by the WYSIWYG review canvas (initReviewCanvas),
    // not by the classic form. We intentionally keep `next.content` from the spread.
    next = {
      ...next,
      title: getFieldValue('vf-title').trim(),
      subject: getFieldValue('vf-subject').trim(),
      author: getFieldValue('vf-author').trim(),
      authorId: getOptionalString(getFieldValue('vf-authorId')),
      role: getOptionalString(getFieldValue('vf-role')),
      category: getOptionalString(getFieldValue('vf-category')),
      verdict: getOptionalString(getFieldValue('vf-verdict')),
      pros: lines('vf-pros'),
      cons: lines('vf-cons'),
      meta: getOptionalString(getFieldValue('vf-meta')),
      link: getOptionalString(getFieldValue('vf-link')),
      date: getOptionalString(getFieldValue('vf-date')),
      imageUrl: getOptionalString(getFieldValue('vf-imageUrl')),
      featured: Boolean(document.getElementById('vf-featured')?.checked)
    };
    applyDraftFieldsFromForm(next);
  } else if (section === 'libraryItems') {
    next = {
      ...next,
      title: getFieldValue('vf-title').trim(),
      type: getFieldValue('vf-type').trim(),
      size: getFieldValue('vf-size').trim(),
      url: getFieldValue('vf-url').trim(),
      year: getFieldValue('vf-year').trim(),
      author: getOptionalString(getFieldValue('vf-author')),
      authorId: getOptionalString(getFieldValue('vf-authorId')),
      role: getOptionalString(getFieldValue('vf-role'))
    };
    applyDraftFieldsFromForm(next);
  } else {
    const parsedContent = collectBlockEditorContent();

    const tags = getFieldValue('vf-tags')
      .split(',')
      .map((tag) => tag.trim())
      .filter(Boolean);

    next = {
      ...next,
      title: getFieldValue('vf-title').trim(),
      author: getFieldValue('vf-author').trim(),
      authorId: getOptionalString(getFieldValue('vf-authorId')),
      role: getFieldValue('vf-role').trim() || undefined,
      date: getFieldValue('vf-date').trim(),
      excerpt: getFieldValue('vf-excerpt').trim(),
      category: getFieldValue('vf-category').trim(),
      subcategory: getFieldValue('vf-subcategory').trim() || undefined,
      tags,
      imageSeed: getFieldValue('vf-imageSeed').trim(),
      imageUrl: getOptionalString(getFieldValue('vf-imageUrl')),
      content: parsedContent
    };
  }

  return next;
}

// Article and review canvases are the actual editing surfaces. The old hidden
// form remains only as a compatibility fallback for the remaining sections.
// Reading that hidden form after somebody has typed in a live canvas was the
// source of an especially damaging failure: a click on "Save" could put the
// previous values back into a new record. Flush the active canvas first and
// then save the entry which is already in the canonical editor JSON.
async function flushActiveEditorialCanvas() {
  if (window.__modernEditorActive) await flushModernEditor();
  if (typeof window._wysFlush === 'function') window._wysFlush();
  if (typeof window._revFlush === 'function') window._revFlush();
}

function usesLiveEditorialCanvas(section) {
  return (section === 'articles' && window.__wysEditorActive === true)
    || (section === 'reviews' && window.__reviewEditorActive === true);
}

async function applyVisualChanges() {
  try {
    setBusy(true);
    await flushActiveEditorialCanvas();
    const data = parseEditorJson();
    const section = visualSectionSelect.value;
    const lang = visualLangSelect.value || DEFAULT_LANGUAGE;
    const entries = getSectionArray(data, section, lang, lang !== DEFAULT_LANGUAGE);

    if (!entries.length) {
      throw new Error('Нет записей для редактирования.');
    }

    const selectedId = Number(visualEntrySelect.value);
    const entryIndex = entries.findIndex((item) => Number(item.id) === selectedId);
    if (entryIndex === -1) {
      throw new Error('Не найдена выбранная запись.');
    }

    const current = entries[entryIndex];
    const next = usesLiveEditorialCanvas(section)
      ? deepClone(current)
      : buildEntryFromVisualForm(section, current);

    entries[entryIndex] = next;
    const syncedLangs = section === 'articles' || section === 'items'
      ? await translateEntryToAllLanguages(data, section, lang, next, {
          statusPrefix: `Обновляю переводы #${selectedId}`
        })
      : await syncMissingEntryLanguages(data, section, lang, next);
    pendingVisualEntryId = selectedId;
    setEditorData(data);
    const syncNote = section === 'articles' || section === 'items'
      ? formatLanguageSyncNote(syncedLangs, 'Языки обновлены')
      : formatLanguageSyncNote(syncedLangs, 'Недостающие языки созданы');
    const statusType = getLanguageSyncFailures(syncedLangs).length ? 'info' : 'success';
    setStatus(statusType, `Запись #${selectedId} обновлена (${getSectionLabel(section)} / ${lang}).${syncNote}`);
    showLanguageSyncReport({
      selectedId,
      section,
      sourceLang: lang,
      savedToServer: false,
      syncResult: syncedLangs,
      actionLabel: 'Запись обновлена'
    });
  } catch (error) {
    setStatus('error', getErrorMessage(error));
  } finally {
    setBusy(false);
  }
}

// ─── Per-entity save: PATCH one record instead of the whole document ─────────
// Fast path for sections with no autopublish safety net (Items, LibraryItems,
// Reviews' classic-form fallback). Fetches the current version right before
// writing so a stale save surfaces as a clear "someone else saved" message
// instead of silently losing an edit.
const CONTENT_META_API = 'https://api.eprisjournal.com/content/meta';
const CONTENT_ENTITY_API = 'https://api.eprisjournal.com/content/entity';
const INTERVIEWS_API = 'https://api.eprisjournal.com/interviews';
async function saveEntityToServer(section, lang, entity, options = {}) {
  const pw = getAdminPassword();
  if (!pw) throw new Error('Нет пароля редакции — войдите заново.');
  const serverEntity = normalizeEntityForServer(section, entity);
  const retries = Number.isInteger(options.retries) ? options.retries : 2;

  // The live article/review canvas and the toolbar can both save legitimately
  // within one second. Retry a fresh version check instead of treating this
  // ordinary race as a lost record. The entity itself is immutable for the
  // duration of this call, so retrying never merges two different edits.
  for (let attempt = 0; attempt <= retries; attempt += 1) {
    const metaRes = await fetch(CONTENT_META_API, { cache: 'no-store' });
    const meta = await metaRes.json().catch(() => ({}));
    if (!metaRes.ok || !meta.version) throw new Error('Не удалось получить актуальную версию контента на VPS.');

    const res = await fetch(CONTENT_ENTITY_API, {
      method: 'PATCH',
      headers: { 'Content-Type': 'application/json', 'X-Admin-Password': pw },
      body: JSON.stringify({ section, id: serverEntity.id, entity: serverEntity, lang, expectedVersion: meta.version }),
    });
    const data = await res.json().catch(() => ({}));
    if (res.status === 409 && attempt < retries) continue;
    if (res.status === 409) throw new Error('Контент изменился несколько раз подряд. Нажмите «Загрузить» и повторите сохранение.');
    if (!res.ok || !data.ok) throw new Error(data.error || ('VPS вернул статус ' + res.status));
    return data;
  }

  throw new Error('Не удалось сохранить запись на VPS.');
}

